#[derive(Debug, Clone)]
pub struct AppError {
    pub code: &'static str,
    pub message: String,
}

impl AppError {
    pub fn invalid_params(message: impl Into<String>) -> Self {
        Self {
            code: "invalid_params",
            message: message.into(),
        }
    }

    pub fn invalid_state(message: impl Into<String>) -> Self {
        Self {
            code: "invalid_state",
            message: message.into(),
        }
    }

    pub fn not_found(message: impl Into<String>) -> Self {
        Self {
            code: "not_found",
            message: message.into(),
        }
    }

    pub fn permission_denied(message: impl Into<String>) -> Self {
        Self {
            code: "permission_denied",
            message: message.into(),
        }
    }

    pub fn unauthorized(message: impl Into<String>) -> Self {
        Self {
            code: "unauthorized",
            message: message.into(),
        }
    }

    pub fn forbidden(message: impl Into<String>) -> Self {
        Self {
            code: "forbidden",
            message: message.into(),
        }
    }

    pub fn new(code: &'static str, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    pub fn method_not_found(method: &str) -> Self {
        Self {
            code: "method_not_found",
            message: format!("Unknown method: {method}"),
        }
    }

    pub fn not_supported(message: impl Into<String>) -> Self {
        Self {
            code: "not_supported",
            message: message.into(),
        }
    }

    pub fn timeout(message: impl Into<String>) -> Self {
        Self {
            code: "timeout",
            message: message.into(),
        }
    }

    pub fn request_failed(message: impl Into<String>) -> Self {
        Self {
            code: "request_failed",
            message: message.into(),
        }
    }

    pub fn unavailable(message: impl Into<String>) -> Self {
        Self {
            code: "unavailable",
            message: message.into(),
        }
    }

    pub fn internal(message: impl Into<String>) -> Self {
        Self {
            code: "internal_error",
            message: message.into(),
        }
    }
}

impl std::fmt::Display for AppError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for AppError {}

type AppResult<T> = std::result::Result<T, AppError>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SurfaceKind {
    Terminal,
    Browser,
    FilePreview,
    Markdown,
    Diff,
    Project,
    Settings,
    AgentSession,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SurfaceCloseSource {
    Api,
    Shortcut,
    TabButton,
    GhosttyRuntime,
    ChildExited,
}

impl SurfaceCloseSource {
    fn from_params(params: &Value) -> AppResult<Self> {
        let Some(raw) = string_param(params, "source") else {
            return Ok(Self::Api);
        };
        match raw.trim() {
            "" | "api" | "socket" | "cli" => Ok(Self::Api),
            "shortcut" | "keyboard" | "command_palette" => Ok(Self::Shortcut),
            "tab_button" | "tab-button" | "close_button" | "middle_click" => Ok(Self::TabButton),
            "ghostty" | "ghostty_runtime" | "runtime" => Ok(Self::GhosttyRuntime),
            "child_exited" | "child-exited" | "child_exit" => Ok(Self::ChildExited),
            other => Err(AppError::invalid_params(format!(
                "unsupported surface close source: {other}"
            ))),
        }
    }
}

impl SurfaceKind {
    fn from_str(value: &str) -> Self {
        match value {
            "browser" => Self::Browser,
            "file" | "file-preview" | "filePreview" | "filepreview" => Self::FilePreview,
            "markdown" => Self::Markdown,
            "diff" => Self::Diff,
            "project" => Self::Project,
            "settings" => Self::Settings,
            "agent-session" => Self::AgentSession,
            _ => Self::Terminal,
        }
    }

    fn from_value(value: Option<&Value>) -> Self {
        match value.and_then(Value::as_str).unwrap_or("terminal") {
            value => Self::from_str(value),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Terminal => "terminal",
            Self::Browser => "browser",
            Self::FilePreview => "filePreview",
            Self::Markdown => "markdown",
            Self::Diff => "diff",
            Self::Project => "project",
            Self::Settings => "settings",
            Self::AgentSession => "agent-session",
        }
    }
}

fn surface_kind_supports_browser_state(kind: SurfaceKind) -> bool {
    matches!(
        kind,
        SurfaceKind::Browser
            | SurfaceKind::Settings
            | SurfaceKind::FilePreview
            | SurfaceKind::Markdown
            | SurfaceKind::Diff
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentLifecycleState {
    Unknown,
    Running,
    Idle,
    NeedsInput,
}

impl AgentLifecycleState {
    fn parse(value: &str) -> Option<Self> {
        let normalized = value.trim().to_ascii_lowercase().replace('_', "-");
        match normalized.as_str() {
            "unknown" => Some(Self::Unknown),
            "running" => Some(Self::Running),
            "idle" => Some(Self::Idle),
            "needsinput" | "needs-input" => Some(Self::NeedsInput),
            _ => None,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Unknown => "unknown",
            Self::Running => "running",
            Self::Idle => "idle",
            Self::NeedsInput => "needsInput",
        }
    }
}

