#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PaneFocusDirection {
    Left,
    Right,
    Up,
    Down,
}

impl PaneFocusDirection {
    fn as_str(self) -> &'static str {
        match self {
            Self::Left => "left",
            Self::Right => "right",
            Self::Up => "up",
            Self::Down => "down",
        }
    }
}

fn spatial_focus_target(
    direction: PaneFocusDirection,
    origin_id: &str,
    frames: &[(String, DebugFrame)],
) -> Option<String> {
    let origin = frames
        .iter()
        .find(|(pane_id, _)| pane_id == origin_id)
        .map(|(_, frame)| *frame)?;
    let origin_mid_x = origin.x + origin.width / 2.0;
    let origin_mid_y = origin.y + origin.height / 2.0;

    frames
        .iter()
        .filter(|(pane_id, _)| pane_id != origin_id)
        .filter_map(|(pane_id, candidate)| {
            let candidate_mid_x = candidate.x + candidate.width / 2.0;
            let candidate_mid_y = candidate.y + candidate.height / 2.0;
            let (axis_distance, orthogonal_distance, overlaps) = match direction {
                PaneFocusDirection::Left | PaneFocusDirection::Right => (
                    if direction == PaneFocusDirection::Right {
                        candidate_mid_x - origin_mid_x
                    } else {
                        origin_mid_x - candidate_mid_x
                    },
                    (candidate_mid_y - origin_mid_y).abs(),
                    candidate.y < origin.y + origin.height
                        && origin.y < candidate.y + candidate.height,
                ),
                PaneFocusDirection::Up | PaneFocusDirection::Down => (
                    if direction == PaneFocusDirection::Down {
                        candidate_mid_y - origin_mid_y
                    } else {
                        origin_mid_y - candidate_mid_y
                    },
                    (candidate_mid_x - origin_mid_x).abs(),
                    candidate.x < origin.x + origin.width
                        && origin.x < candidate.x + candidate.width,
                ),
            };
            if axis_distance <= 0.5 || !axis_distance.is_finite() {
                return None;
            }
            let weight = if overlaps { 0.25 } else { 3.0 };
            let score = axis_distance + weight * orthogonal_distance;
            score.is_finite().then(|| (pane_id.clone(), score))
        })
        .min_by(|(left_id, left_score), (right_id, right_score)| {
            left_score
                .total_cmp(right_score)
                .then_with(|| left_id.cmp(right_id))
        })
        .map(|(pane_id, _)| pane_id)
}

