fn split_track_minimum(total: f64, count: usize) -> f64 {
    80.0_f64.min(total / count.max(1) as f64)
}

fn normalize_split_track_sizes(sizes: &[f64], total: f64) -> Vec<f64> {
    if sizes.is_empty() {
        return Vec::new();
    }
    let minimum = split_track_minimum(total, sizes.len());
    let weights = sizes
        .iter()
        .map(|size| {
            if size.is_finite() {
                (*size - minimum).max(0.0)
            } else {
                0.0
            }
        })
        .collect::<Vec<_>>();
    let available = (total - minimum * sizes.len() as f64).max(0.0);
    let weight_sum = weights.iter().sum::<f64>();
    if weight_sum <= f64::EPSILON {
        return vec![total / sizes.len() as f64; sizes.len()];
    }
    weights
        .into_iter()
        .map(|weight| minimum + available * weight / weight_sum)
        .collect()
}

fn split_track_offsets(sizes: &[f64]) -> Vec<f64> {
    let mut offsets = Vec::with_capacity(sizes.len() + 1);
    let mut offset = 0.0;
    offsets.push(offset);
    for size in sizes {
        offset += size;
        offsets.push(offset);
    }
    offsets
}

fn split_track_position(boundaries: &[i32], sizes: &[f64], coordinate: f64) -> f64 {
    if boundaries.len() != sizes.len() + 1 || boundaries.is_empty() {
        return 0.0;
    }
    if coordinate <= boundaries[0] as f64 {
        return 0.0;
    }

    let mut offset = 0.0;
    for (index, size) in sizes.iter().enumerate() {
        let start = boundaries[index] as f64;
        let end = boundaries[index + 1] as f64;
        if coordinate < end {
            let fraction = ((coordinate - start) / (end - start)).clamp(0.0, 1.0);
            return offset + size * fraction;
        }
        offset += size;
    }
    offset
}

fn nearest_split_track_boundary(offsets: &[f64], coordinate: f64) -> Option<usize> {
    offsets
        .iter()
        .enumerate()
        .min_by(|(_, left), (_, right)| {
            (*left - coordinate)
                .abs()
                .total_cmp(&(*right - coordinate).abs())
        })
        .map(|(index, _)| index)
}

fn rescale_split_track_slice(sizes: &mut [f64], target: f64) {
    let current = sizes.iter().sum::<f64>();
    if current <= f64::EPSILON {
        let size = target / sizes.len().max(1) as f64;
        sizes.fill(size);
        return;
    }
    for size in sizes {
        *size = target * *size / current;
    }
}
