impl DebugFrame {
    fn to_value(self) -> Value {
        json!({
            "x": self.x,
            "y": self.y,
            "width": self.width,
            "height": self.height
        })
    }

    fn columns(self) -> u64 {
        (self.width / DEBUG_CELL_WIDTH).floor().max(1.0) as u64
    }

    fn rows(self) -> u64 {
        (self.height / DEBUG_CELL_HEIGHT).floor().max(1.0) as u64
    }

    fn terminal_size(self) -> TerminalSize {
        TerminalSize {
            cols: clamp_u16(self.columns()),
            rows: clamp_u16(self.rows()),
            pixel_width: clamp_u16(self.width.round().max(1.0) as u64),
            pixel_height: clamp_u16(self.height.round().max(1.0) as u64),
        }
    }
}

fn align_canvas_frames(
    command: &str,
    mut panes: Vec<(String, DebugFrame)>,
    reference: Option<&str>,
    gap: f64,
) -> Vec<(String, DebugFrame)> {
    if panes.len() < 2 {
        return panes;
    }

    match command {
        "align-left" => {
            let x = panes
                .iter()
                .map(|(_, frame)| frame.x)
                .fold(f64::INFINITY, f64::min);
            for (_, frame) in &mut panes {
                frame.x = x;
            }
        }
        "align-right" => {
            let right = panes
                .iter()
                .map(|(_, frame)| frame.x + frame.width)
                .fold(f64::NEG_INFINITY, f64::max);
            for (_, frame) in &mut panes {
                frame.x = right - frame.width;
            }
        }
        "align-top" => {
            let y = panes
                .iter()
                .map(|(_, frame)| frame.y)
                .fold(f64::INFINITY, f64::min);
            for (_, frame) in &mut panes {
                frame.y = y;
            }
        }
        "align-bottom" => {
            let bottom = panes
                .iter()
                .map(|(_, frame)| frame.y + frame.height)
                .fold(f64::NEG_INFINITY, f64::max);
            for (_, frame) in &mut panes {
                frame.y = bottom - frame.height;
            }
        }
        "equalize-widths" | "equalize-heights" => {
            let horizontal = command == "equalize-widths";
            let reference_frame = reference
                .and_then(|reference| {
                    panes
                        .iter()
                        .find(|(pane_id, _)| pane_id == reference)
                        .map(|(_, frame)| *frame)
                })
                .or_else(|| {
                    panes
                        .iter()
                        .max_by(|(left_id, left), (right_id, right)| {
                            let left_size = if horizontal { left.width } else { left.height };
                            let right_size = if horizontal {
                                right.width
                            } else {
                                right.height
                            };
                            left_size
                                .total_cmp(&right_size)
                                .then_with(|| right_id.cmp(left_id))
                        })
                        .map(|(_, frame)| *frame)
                })
                .expect("canvas alignment has at least two panes");
            for (_, frame) in &mut panes {
                if horizontal {
                    frame.width = reference_frame.width;
                } else {
                    frame.height = reference_frame.height;
                }
            }
        }
        "distribute-horizontally" | "distribute-vertically" => {
            let horizontal = command == "distribute-horizontally";
            panes.sort_by(|(left_id, left), (right_id, right)| {
                let left_origin = if horizontal { left.x } else { left.y };
                let right_origin = if horizontal { right.x } else { right.y };
                left_origin
                    .total_cmp(&right_origin)
                    .then_with(|| left_id.cmp(right_id))
            });
            let mut cursor = if horizontal {
                panes[0].1.x + panes[0].1.width
            } else {
                panes[0].1.y + panes[0].1.height
            };
            for (_, frame) in panes.iter_mut().skip(1) {
                if horizontal {
                    frame.x = cursor + gap;
                    cursor = frame.x + frame.width;
                } else {
                    frame.y = cursor + gap;
                    cursor = frame.y + frame.height;
                }
            }
        }
        "tidy" => {
            let origin_x = panes
                .iter()
                .map(|(_, frame)| frame.x)
                .fold(f64::INFINITY, f64::min);
            let origin_y = panes
                .iter()
                .map(|(_, frame)| frame.y)
                .fold(f64::INFINITY, f64::min);
            panes.sort_by(|(left_id, left), (right_id, right)| {
                let left_mid_y = left.y + left.height / 2.0;
                let right_mid_y = right.y + right.height / 2.0;
                let left_mid_x = left.x + left.width / 2.0;
                let right_mid_x = right.x + right.width / 2.0;
                left_mid_y
                    .total_cmp(&right_mid_y)
                    .then_with(|| left_mid_x.total_cmp(&right_mid_x))
                    .then_with(|| left_id.cmp(right_id))
            });

            let mut rows: Vec<Vec<(String, DebugFrame)>> = Vec::new();
            let mut row_bottom = f64::NEG_INFINITY;
            for pane in panes {
                let mid_y = pane.1.y + pane.1.height / 2.0;
                if rows.is_empty() || mid_y >= row_bottom {
                    row_bottom = pane.1.y + pane.1.height;
                    rows.push(vec![pane]);
                } else {
                    row_bottom = row_bottom.max(pane.1.y + pane.1.height);
                    rows.last_mut().expect("canvas row exists").push(pane);
                }
            }

            let mut result = Vec::new();
            let mut y = origin_y;
            for mut row in rows {
                row.sort_by(|(left_id, left), (right_id, right)| {
                    let left_mid_x = left.x + left.width / 2.0;
                    let right_mid_x = right.x + right.width / 2.0;
                    left_mid_x
                        .total_cmp(&right_mid_x)
                        .then_with(|| left_id.cmp(right_id))
                });
                let mut x = origin_x;
                let mut row_height: f64 = 0.0;
                for (pane_id, mut frame) in row {
                    frame.x = x;
                    frame.y = y;
                    x += frame.width + gap;
                    row_height = row_height.max(frame.height);
                    result.push((pane_id, frame));
                }
                y += row_height + gap;
            }
            return result;
        }
        _ => {}
    }

    panes
}

fn place_canvas_frame(
    width: f64,
    height: f64,
    anchor: Option<DebugFrame>,
    existing: &[DebugFrame],
    gap: f64,
) -> DebugFrame {
    if existing.is_empty() {
        return DebugFrame {
            x: anchor.map_or(0.0, |frame| frame.x),
            y: anchor.map_or(0.0, |frame| frame.y),
            width,
            height,
        };
    }
    let Some(anchor) = anchor else {
        return canvas_frame_right_of_content(width, height, existing, gap);
    };

    let candidates = [
        DebugFrame {
            x: anchor.x + anchor.width + gap,
            y: anchor.y,
            width,
            height,
        },
        DebugFrame {
            x: anchor.x,
            y: anchor.y + anchor.height + gap,
            width,
            height,
        },
        DebugFrame {
            x: anchor.x - gap - width,
            y: anchor.y,
            width,
            height,
        },
        DebugFrame {
            x: anchor.x,
            y: anchor.y - gap - height,
            width,
            height,
        },
    ];
    if let Some(frame) = candidates
        .into_iter()
        .find(|candidate| canvas_frame_is_free(*candidate, existing, gap))
    {
        return frame;
    }

    for row in 0..8 {
        let y = anchor.y + row as f64 * (height + gap);
        for column in 0..16 {
            let frame = DebugFrame {
                x: anchor.x + anchor.width + gap + column as f64 * (width + gap),
                y,
                width,
                height,
            };
            if canvas_frame_is_free(frame, existing, gap) {
                return frame;
            }
        }
    }
    canvas_frame_right_of_content(width, height, existing, gap)
}

fn canvas_frame_is_free(candidate: DebugFrame, existing: &[DebugFrame], gap: f64) -> bool {
    let padding = gap - 0.5;
    let probe = DebugFrame {
        x: candidate.x - padding,
        y: candidate.y - padding,
        width: candidate.width + 2.0 * padding,
        height: candidate.height + 2.0 * padding,
    };
    !existing
        .iter()
        .any(|existing| canvas_frames_intersect(probe, *existing))
}

#[cfg(test)]
mod canvas_geometry_tests {
    use super::{
        align_canvas_frames, canvas_fit_magnification, canvas_origin_to_reveal, place_canvas_frame,
        spatial_focus_target, DebugFrame, PaneFocusDirection,
    };

    fn frame(x: f64, y: f64, width: f64, height: f64) -> DebugFrame {
        DebugFrame {
            x,
            y,
            width,
            height,
        }
    }

    fn pane<'a>(panes: &'a [(String, DebugFrame)], id: &str) -> &'a DebugFrame {
        &panes
            .iter()
            .find(|(pane_id, _)| pane_id == id)
            .expect("pane")
            .1
    }

    #[test]
    fn canvas_aligner_uses_reference_and_canonical_distribution_gap() {
        let panes = vec![
            ("a".into(), frame(0.0, 0.0, 100.0, 120.0)),
            ("b".into(), frame(500.0, 50.0, 300.0, 180.0)),
            ("c".into(), frame(130.0, 25.0, 50.0, 140.0)),
        ];
        let equalized = align_canvas_frames("equalize-widths", panes.clone(), Some("a"), 16.0);
        assert!(equalized.iter().all(|(_, frame)| frame.width == 100.0));

        let distributed = align_canvas_frames("distribute-horizontally", panes, None, 16.0);
        assert_eq!(pane(&distributed, "a"), &frame(0.0, 0.0, 100.0, 120.0));
        assert_eq!(pane(&distributed, "c"), &frame(116.0, 25.0, 50.0, 140.0));
        assert_eq!(pane(&distributed, "b"), &frame(182.0, 50.0, 300.0, 180.0));
    }

    #[test]
    fn canvas_spatial_focus_finds_nearest_in_each_direction() {
        let panes = vec![
            ("origin".into(), frame(300.0, 300.0, 100.0, 100.0)),
            ("left".into(), frame(100.0, 300.0, 100.0, 100.0)),
            ("right".into(), frame(500.0, 300.0, 100.0, 100.0)),
            ("up".into(), frame(300.0, 100.0, 100.0, 100.0)),
            ("down".into(), frame(300.0, 500.0, 100.0, 100.0)),
        ];
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Left, "origin", &panes).as_deref(),
            Some("left")
        );
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Right, "origin", &panes).as_deref(),
            Some("right")
        );
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Up, "origin", &panes).as_deref(),
            Some("up")
        );
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Down, "origin", &panes).as_deref(),
            Some("down")
        );
    }

    #[test]
    fn canvas_spatial_focus_prefers_overlapping_band_and_breaks_ties_by_id() {
        let overlapping = vec![
            ("origin".into(), frame(0.0, 0.0, 100.0, 100.0)),
            (
                "closer-misaligned".into(),
                frame(150.0, 400.0, 100.0, 100.0),
            ),
            ("overlapping".into(), frame(300.0, 20.0, 100.0, 100.0)),
        ];
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Right, "origin", &overlapping).as_deref(),
            Some("overlapping")
        );

        let tied = vec![
            ("origin".into(), frame(0.0, 0.0, 100.0, 100.0)),
            ("pane-5".into(), frame(200.0, 110.0, 100.0, 100.0)),
            ("pane-3".into(), frame(200.0, -110.0, 100.0, 100.0)),
        ];
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Right, "origin", &tied).as_deref(),
            Some("pane-3")
        );
    }

    #[test]
    fn canvas_spatial_focus_returns_none_without_directional_candidate_or_origin() {
        let panes = vec![
            ("left".into(), frame(0.0, 0.0, 100.0, 100.0)),
            ("right".into(), frame(200.0, 0.0, 100.0, 100.0)),
        ];
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Left, "left", &panes),
            None
        );
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Right, "right", &panes),
            None
        );
        assert_eq!(
            spatial_focus_target(PaneFocusDirection::Left, "missing", &panes),
            None
        );
    }

    #[test]
    fn canvas_tidy_row_bands_preserve_sizes_and_selection_origin() {
        let panes = vec![
            ("a".into(), frame(7.0, 5.0, 200.0, 150.0)),
            ("b".into(), frame(260.0, -12.0, 320.0, 180.0)),
            ("c".into(), frame(30.0, 320.0, 240.0, 210.0)),
        ];
        let tidied = align_canvas_frames("tidy", panes, None, 16.0);
        assert_eq!(pane(&tidied, "a"), &frame(7.0, -12.0, 200.0, 150.0));
        assert_eq!(pane(&tidied, "b"), &frame(223.0, -12.0, 320.0, 180.0));
        assert_eq!(pane(&tidied, "c"), &frame(7.0, 184.0, 240.0, 210.0));
    }

    #[test]
    fn canvas_placer_tries_neighbors_then_right_of_content() {
        let anchor = frame(1_000.0, 1_000.0, 300.0, 200.0);
        assert_eq!(
            place_canvas_frame(300.0, 200.0, Some(anchor), &[anchor], 16.0),
            frame(1_316.0, 1_000.0, 300.0, 200.0)
        );

        let right = frame(1_316.0, 1_000.0, 300.0, 200.0);
        let below = frame(1_000.0, 1_216.0, 300.0, 200.0);
        assert_eq!(
            place_canvas_frame(300.0, 200.0, Some(anchor), &[anchor, right, below], 16.0,),
            frame(684.0, 1_000.0, 300.0, 200.0)
        );

        let content = [
            frame(0.0, 40.0, 300.0, 200.0),
            frame(350.0, 0.0, 300.0, 200.0),
        ];
        assert_eq!(
            place_canvas_frame(300.0, 200.0, None, &content, 16.0),
            frame(666.0, 0.0, 300.0, 200.0)
        );
    }

    #[test]
    fn canvas_placer_scans_past_offset_blockers_without_overlap() {
        let anchor = frame(0.0, 0.0, 300.0, 200.0);
        let blocker = frame(320.0, 10.0, 300.0, 200.0);
        let placed = place_canvas_frame(300.0, 200.0, Some(anchor), &[anchor, blocker], 16.0);
        let expanded = frame(
            placed.x - 15.5,
            placed.y - 15.5,
            placed.width + 31.0,
            placed.height + 31.0,
        );
        for existing in [anchor, blocker] {
            assert!(
                expanded.x + expanded.width <= existing.x
                    || existing.x + existing.width <= expanded.x
                    || expanded.y + expanded.height <= existing.y
                    || existing.y + existing.height <= expanded.y
            );
        }
    }

    #[test]
    fn canvas_reveal_scrolls_minimally_with_margin() {
        assert_eq!(
            canvas_origin_to_reveal(
                frame(100.0, 100.0, 200.0, 200.0),
                (0.0, 0.0),
                (800.0, 600.0),
                24.0,
            ),
            (0.0, 0.0)
        );
        assert_eq!(
            canvas_origin_to_reveal(
                frame(900.0, 700.0, 200.0, 100.0),
                (0.0, 0.0),
                (800.0, 600.0),
                24.0,
            ),
            (324.0, 224.0)
        );
        assert_eq!(
            canvas_origin_to_reveal(
                frame(-500.0, -300.0, 100.0, 100.0),
                (0.0, 0.0),
                (800.0, 600.0),
                24.0,
            ),
            (-524.0, -324.0)
        );
        assert_eq!(
            canvas_origin_to_reveal(
                frame(100.0, 50.0, 2_000.0, 3_000.0),
                (0.0, 0.0),
                (800.0, 600.0),
                24.0,
            ),
            (76.0, 26.0)
        );
    }

    #[test]
    fn canvas_overview_fit_matches_macos_padding_and_clamps() {
        assert_eq!(
            canvas_fit_magnification(
                frame(0.0, 0.0, 1_504.0, 504.0),
                (800.0, 600.0),
                48.0,
                (0.1, 1.0),
            ),
            0.5
        );
        assert_eq!(
            canvas_fit_magnification(
                frame(0.0, 0.0, 8_000.0, 600.0),
                (800.0, 600.0),
                48.0,
                (0.25, 1.0),
            ),
            0.25
        );
        assert_eq!(
            canvas_fit_magnification(frame(0.0, 0.0, 0.0, 0.0), (800.0, 600.0), 0.0, (0.25, 4.0),),
            1.0
        );
    }
}

fn canvas_frames_intersect(left: DebugFrame, right: DebugFrame) -> bool {
    left.x < right.x + right.width
        && right.x < left.x + left.width
        && left.y < right.y + right.height
        && right.y < left.y + left.height
}

fn canvas_frame_right_of_content(
    width: f64,
    height: f64,
    existing: &[DebugFrame],
    gap: f64,
) -> DebugFrame {
    let min_y = existing
        .iter()
        .map(|frame| frame.y)
        .fold(f64::INFINITY, f64::min);
    let max_x = existing
        .iter()
        .map(|frame| frame.x + frame.width)
        .fold(f64::NEG_INFINITY, f64::max);
    DebugFrame {
        x: max_x + gap,
        y: min_y,
        width,
        height,
    }
}

fn canvas_origin_to_reveal(
    target: DebugFrame,
    viewport_origin: (f64, f64),
    viewport_size: (f64, f64),
    margin: f64,
) -> (f64, f64) {
    (
        canvas_axis_origin_to_reveal(
            target.x - margin,
            target.x + target.width + margin,
            viewport_origin.0,
            viewport_size.0,
        ),
        canvas_axis_origin_to_reveal(
            target.y - margin,
            target.y + target.height + margin,
            viewport_origin.1,
            viewport_size.1,
        ),
    )
}

fn canvas_axis_origin_to_reveal(
    target_min: f64,
    target_max: f64,
    viewport_min: f64,
    viewport_length: f64,
) -> f64 {
    if target_max - target_min >= viewport_length || target_min < viewport_min {
        target_min
    } else if target_max > viewport_min + viewport_length {
        target_max - viewport_length
    } else {
        viewport_min
    }
}

fn canvas_fit_magnification(
    content: DebugFrame,
    viewport_size: (f64, f64),
    padding: f64,
    range: (f64, f64),
) -> f64 {
    let padded_width = content.width + padding * 2.0;
    let padded_height = content.height + padding * 2.0;
    if padded_width <= 0.0
        || padded_height <= 0.0
        || viewport_size.0 <= 0.0
        || viewport_size.1 <= 0.0
    {
        return 1.0_f64.min(range.1);
    }
    (viewport_size.0 / padded_width)
        .min(viewport_size.1 / padded_height)
        .clamp(range.0, range.1)
}

