#[derive(Clone)]
struct ProjectPanelState {
    path: String,
    model: Option<project::ProjectModel>,
    load_error: Option<String>,
    active_tab: String,
    selected_scheme: String,
    selected_configuration: String,
    selected_target_id: String,
    selected_file: String,
    settings_filter: String,
}

impl ProjectPanelState {
    fn new(path: String) -> Self {
        let (model, load_error) = match project::load_project(Path::new(&path)) {
            Ok(model) => (Some(model), None),
            Err(error) => (None, Some(error)),
        };
        let selected_scheme = model
            .as_ref()
            .and_then(|model| {
                model
                    .modules
                    .iter()
                    .flat_map(|module| &module.schemes)
                    .next()
            })
            .map(|scheme| scheme.name.clone())
            .unwrap_or_default();
        let selected_configuration = model
            .as_ref()
            .and_then(|model| {
                model
                    .modules
                    .iter()
                    .flat_map(|module| &module.configurations)
                    .next()
            })
            .map(|configuration| configuration.name.clone())
            .unwrap_or_default();
        let selected_target_id = model
            .as_ref()
            .and_then(|model| {
                model
                    .modules
                    .iter()
                    .flat_map(|module| &module.targets)
                    .next()
            })
            .map(|target| target.id.clone())
            .unwrap_or_default();
        Self {
            path,
            model,
            load_error,
            active_tab: "files".to_string(),
            selected_scheme,
            selected_configuration,
            selected_target_id,
            selected_file: String::new(),
            settings_filter: String::new(),
        }
    }
}

