impl Default for CanvasWorkspaceState {
    fn default() -> Self {
        Self {
            mode: CanvasMode::Splits,
            magnification: 1.0,
            center_x: DEBUG_LAYOUT_WIDTH / 2.0,
            center_y: DEBUG_LAYOUT_HEIGHT / 2.0,
            overview_active: false,
            overview_restore: None,
            z_order: Vec::new(),
        }
    }
}

fn normalized_canvas_z_order(pane_ids: &[String], stored: &[String]) -> Vec<String> {
    let mut ordered = Vec::with_capacity(pane_ids.len());
    for pane_id in stored {
        if pane_ids.contains(pane_id) && !ordered.contains(pane_id) {
            ordered.push(pane_id.clone());
        }
    }
    for pane_id in pane_ids {
        if !ordered.contains(pane_id) {
            ordered.push(pane_id.clone());
        }
    }
    ordered
}

