    pub(crate) fn app_workspace_settings_value(&self) -> Value {
        let settings = self.app_workspace_settings;
        json!({
            "newWorkspacePlacement": settings.new_workspace_placement.as_str(),
            "workspaceInheritWorkingDirectory": settings.workspace_inherit_working_directory,
            "keepWorkspaceOpenWhenClosingLastSurface": settings.keep_workspace_open_when_closing_last_surface,
            "confirmQuit": settings.confirm_quit.as_str(),
            "warnBeforeClosingTab": settings.warn_before_closing_tab,
            "warnBeforeClosingTabXButton": settings.warn_before_closing_tab_x_button,
            "hideTabCloseButton": settings.hide_tab_close_button,
            "availableWorkspacePlacements": ["top", "afterCurrent", "end"]
            ,"availableConfirmQuitPolicies": ["always", "dirty-only", "never"]
        })
    }

    fn set_app_workspace_setting(&mut self, params: &Value) -> AppResult<Value> {
        let key = string_param(params, "key")
            .ok_or_else(|| AppError::invalid_params("key is required"))?;
        let value = params
            .get("value")
            .ok_or_else(|| AppError::invalid_params("value is required"))?;
        let path = match key.as_str() {
            "newWorkspacePlacement" | "app.newWorkspacePlacement" => {
                let raw = value.as_str().ok_or_else(|| {
                    AppError::invalid_params("newWorkspacePlacement must be a string")
                })?;
                let placement = config::WorkspacePlacement::parse(raw).ok_or_else(|| {
                    AppError::invalid_params(
                        "newWorkspacePlacement must be `top`, `afterCurrent`, or `end`",
                    )
                })?;
                config::set_app_workspace_placement(placement).map_err(AppError::internal)?
            }
            "workspaceInheritWorkingDirectory" | "app.workspaceInheritWorkingDirectory" => {
                let enabled = value.as_bool().ok_or_else(|| {
                    AppError::invalid_params(
                        "workspaceInheritWorkingDirectory must be true or false",
                    )
                })?;
                config::set_workspace_inherit_working_directory(enabled)
                    .map_err(AppError::internal)?
            }
            "keepWorkspaceOpenWhenClosingLastSurface"
            | "app.keepWorkspaceOpenWhenClosingLastSurface" => {
                let enabled = value.as_bool().ok_or_else(|| {
                    AppError::invalid_params(
                        "keepWorkspaceOpenWhenClosingLastSurface must be true or false",
                    )
                })?;
                config::set_keep_workspace_open_when_closing_last_surface(enabled)
                    .map_err(AppError::internal)?
            }
            "confirmQuit" | "app.confirmQuit" => {
                let raw = value
                    .as_str()
                    .ok_or_else(|| AppError::invalid_params("confirmQuit must be a string"))?;
                let policy = config::ConfirmQuitPolicy::parse(raw).ok_or_else(|| {
                    AppError::invalid_params(
                        "confirmQuit must be `always`, `dirty-only`, or `never`",
                    )
                })?;
                config::set_app_behavior_setting("confirmQuit", json!(policy.as_str()))
                    .map_err(AppError::internal)?
            }
            "warnBeforeQuit" | "app.warnBeforeQuit" => {
                let enabled = value.as_bool().ok_or_else(|| {
                    AppError::invalid_params("warnBeforeQuit must be true or false")
                })?;
                config::set_app_behavior_setting("warnBeforeQuit", json!(enabled))
                    .map_err(AppError::internal)?
            }
            "warnBeforeClosingTab" | "app.warnBeforeClosingTab" => {
                let enabled = value.as_bool().ok_or_else(|| {
                    AppError::invalid_params("warnBeforeClosingTab must be true or false")
                })?;
                config::set_app_behavior_setting("warnBeforeClosingTab", json!(enabled))
                    .map_err(AppError::internal)?
            }
            "warnBeforeClosingTabXButton" | "app.warnBeforeClosingTabXButton" => {
                let enabled = value.as_bool().ok_or_else(|| {
                    AppError::invalid_params("warnBeforeClosingTabXButton must be true or false")
                })?;
                config::set_app_behavior_setting("warnBeforeClosingTabXButton", json!(enabled))
                    .map_err(AppError::internal)?
            }
            "hideTabCloseButton" | "app.hideTabCloseButton" => {
                let enabled = value.as_bool().ok_or_else(|| {
                    AppError::invalid_params("hideTabCloseButton must be true or false")
                })?;
                config::set_app_behavior_setting("hideTabCloseButton", json!(enabled))
                    .map_err(AppError::internal)?
            }
            _ => {
                return Err(AppError::invalid_params(format!(
                    "unsupported app setting: {key}"
                )));
            }
        };
        self.app_workspace_settings = config::app_workspace_settings();
        self.config_reload_generation = self.config_reload_generation.saturating_add(1);
        let mut settings = self.app_workspace_settings_value();
        if let Some(object) = settings.as_object_mut() {
            object.insert("ok".to_string(), json!(true));
            object.insert("path".to_string(), json!(path));
            object.insert(
                "config_reload_generation".to_string(),
                json!(self.config_reload_generation),
            );
        }
        Ok(settings)
    }

