    fn set_beta_feature_setting(&mut self, params: &Value) -> AppResult<Value> {
        let key = string_param(params, "key")
            .ok_or_else(|| AppError::invalid_params("key is required"))?;
        let key = key.trim().to_string();
        let value = params
            .get("value")
            .cloned()
            .ok_or_else(|| AppError::invalid_params("value is required"))?;
        value
            .as_bool()
            .ok_or_else(|| AppError::invalid_params("value must be true or false"))?;
        let path =
            config::set_beta_feature_setting(&key, value).map_err(AppError::invalid_params)?;
        self.beta_feature_settings = config::beta_feature_settings();
        self.normalize_beta_feature_runtime_state();
        self.custom_sidebar_reload_generation =
            self.custom_sidebar_reload_generation.saturating_add(1);
        self.sidebar_extension_render_cache = None;
        self.config_reload_generation = self.config_reload_generation.saturating_add(1);
        let mut settings = self.beta_feature_settings_value();
        if let Some(object) = settings.as_object_mut() {
            object.insert("ok".to_string(), json!(true));
            object.insert("path".to_string(), json!(path));
            object.insert(
                "config_reload_generation".to_string(),
                json!(self.config_reload_generation),
            );
        }
        Ok(settings)
    }

    fn normalize_beta_feature_runtime_state(&mut self) {
        let feed_enabled = self.beta_feature_settings.right_sidebar_feed;
        let dock_enabled = self.beta_feature_settings.right_sidebar_dock;
        for mode in self.sidebar_mode_by_window.values_mut() {
            if (mode == "feed" && !feed_enabled) || (mode == "dock" && !dock_enabled) {
                *mode = "files".to_string();
            }
        }
        if !self.beta_feature_settings.remote_tmux {
            for runtime in self.remote_tmux_runtimes.values() {
                runtime.stop();
            }
            self.remote_tmux_runtimes.clear();
            self.remote_tmux_connections.clear();
        }
    }

    fn available_right_sidebar_modes(&self) -> Vec<&'static str> {
        let mut modes = vec!["files", "find", "sessions"];
        if self.beta_feature_settings.right_sidebar_feed {
            modes.push("feed");
        }
        if self.beta_feature_settings.right_sidebar_dock {
            modes.push("dock");
        }
        modes
    }

    fn right_sidebar_mode_enabled(&self, mode: &str) -> bool {
        match mode {
            "feed" => self.beta_feature_settings.right_sidebar_feed,
            "dock" => self.beta_feature_settings.right_sidebar_dock,
            "files" | "find" | "vault" | "sessions" => true,
            _ => false,
        }
    }

    fn require_remote_tmux_enabled(&self) -> AppResult<()> {
        if self.beta_feature_settings.remote_tmux {
            Ok(())
        } else {
            Err(AppError::unavailable(
                "Remote tmux is disabled. Enable it in Settings > Beta Features or set `remoteTmux.beta.enabled` to true.",
            ))
        }
    }

