    fn terminal_resume_approval_update(&mut self, params: &Value) -> AppResult<Value> {
        let record_id = string_param(params, "id")
            .or_else(|| string_param(params, "record_id"))
            .and_then(non_empty_trimmed)
            .ok_or_else(|| AppError::invalid_params("id is required"))?;
        let policy = string_param(params, "policy")
            .map(|value| {
                resume_approval::ResumeApprovalPolicy::parse(&value).ok_or_else(|| {
                    AppError::invalid_params("policy must be manual, prompt, or auto")
                })
            })
            .transpose()?;
        let command_prefix = params
            .get("commandPrefix")
            .or_else(|| params.get("command_prefix"))
            .map(|value| {
                value
                    .as_array()
                    .ok_or_else(|| {
                        AppError::invalid_params("commandPrefix must be an array of strings")
                    })?
                    .iter()
                    .map(|item| {
                        item.as_str()
                            .map(str::to_string)
                            .filter(|item| !item.is_empty())
                            .ok_or_else(|| {
                                AppError::invalid_params(
                                    "commandPrefix must contain non-empty strings",
                                )
                            })
                    })
                    .collect::<AppResult<Vec<_>>>()
            })
            .transpose()?;
        resume_approval::update(&record_id, policy, command_prefix)
            .map_err(AppError::invalid_params)?;
        self.config_reload_generation = self.config_reload_generation.saturating_add(1);
        Ok(resume_approval::list_status())
    }

    fn terminal_resume_approval_delete(&mut self, params: &Value) -> AppResult<Value> {
        let record_id = string_param(params, "id")
            .or_else(|| string_param(params, "record_id"))
            .and_then(non_empty_trimmed)
            .ok_or_else(|| AppError::invalid_params("id is required"))?;
        let deleted = resume_approval::delete(&record_id).map_err(AppError::invalid_params)?;
        self.config_reload_generation = self.config_reload_generation.saturating_add(1);
        let mut status = resume_approval::list_status();
        if let Some(object) = status.as_object_mut() {
            object.insert("deleted".to_string(), json!(deleted));
        }
        Ok(status)
    }

