        self.app_workspace_settings = config::app_workspace_settings();
        self.terminal_interaction_settings = config::terminal_interaction_settings();
        self.beta_feature_settings = config::beta_feature_settings();
        self.normalize_beta_feature_runtime_state();
        self.sidebar_extension_render_cache = None;
        self.system_wide_hotkey_enabled = config::system_wide_hotkey_enabled();
        self.pending_shortcut_chords_by_window.clear();
