    fn dogfood_feedback_submit(&self, params: &Value) -> AppResult<Value> {
        let email = self
            .auth_state
            .user
            .as_ref()
            .and_then(|user| user.email.as_deref());
        if !is_privileged_feedback_email(email) {
            return Err(AppError::unauthorized(
                "Feedback agent sink is restricted to privileged accounts",
            ));
        }

        let text = cap_chars(
            &string_param(params, "text").unwrap_or_default(),
            MAX_DOGFOOD_TEXT_CHARS,
        );
        let terminal_text = cap_chars(
            &string_param(params, "terminal_text").unwrap_or_default(),
            MAX_DOGFOOD_TERMINAL_CHARS,
        );
        let build_stamp = cap_chars(
            &string_param(params, "build_stamp").unwrap_or_default(),
            MAX_DOGFOOD_BUILD_STAMP_CHARS,
        );
        let diagnostic_blob_base64 =
            string_param(params, "diagnostic_blob_base64").unwrap_or_default();
        if diagnostic_blob_base64.len() > MAX_DOGFOOD_BLOB_BASE64_CHARS {
            return Err(AppError::invalid_params(
                "diagnostic_blob_base64 exceeds size limit",
            ));
        }
        let diagnostic_data = if diagnostic_blob_base64.is_empty() {
            Vec::new()
        } else {
            base64::engine::general_purpose::STANDARD
                .decode(diagnostic_blob_base64.as_bytes())
                .unwrap_or_default()
        };
        if diagnostic_data.len() > MAX_DOGFOOD_BLOB_BYTES {
            return Err(AppError::invalid_params(
                "diagnostic blob exceeds size limit",
            ));
        }

        let root = dogfood_feedback_store_dir()?;
        create_private_dir(&root)?;
        let bundle_dir = root.join(format!(
            "{}_{}",
            event_timestamp_millis(),
            short_token().to_ascii_lowercase()
        ));
        create_private_dir(&bundle_dir)?;

        let diagnostic_path = bundle_dir.join("diagnostic.log");
        fs::write(&diagnostic_path, &diagnostic_data).map_err(|err| {
            AppError::internal(format!(
                "failed to write diagnostic log {}: {err}",
                diagnostic_path.display()
            ))
        })?;
        set_private_file_permissions(&diagnostic_path)?;

        let manifest = json!({
            "schema": "cmux.dogfood.feedback.v1",
            "received_at": event_timestamp_millis(),
            "text": text,
            "terminal_text": terminal_text,
            "build_stamp": build_stamp,
            "diagnostic_log_file": "diagnostic.log",
            "diagnostic_log_bytes": diagnostic_data.len(),
        });
        let manifest_path = bundle_dir.join("bundle.json");
        let manifest_bytes = serde_json::to_vec_pretty(&manifest).map_err(|err| {
            AppError::internal(format!("failed to encode dogfood feedback: {err}"))
        })?;
        fs::write(&manifest_path, manifest_bytes).map_err(|err| {
            AppError::internal(format!(
                "failed to write dogfood feedback bundle {}: {err}",
                manifest_path.display()
            ))
        })?;
        set_private_file_permissions(&manifest_path)?;
        prune_dogfood_feedback_bundles(&root);

        Ok(json!({
            "ok": true,
            "bundle_path": bundle_dir.to_string_lossy().to_string(),
            "diagnostic_log_bytes": diagnostic_data.len()
        }))
    }

    fn auth_status(&self, timed_out: bool) -> Value {
        let mut result = Map::new();
        result.insert("signed_in".to_string(), json!(self.auth_state.signed_in));
        result.insert("is_restoring_session".to_string(), json!(false));
        result.insert("is_loading".to_string(), json!(false));
        result.insert("timed_out".to_string(), json!(timed_out));
        result.insert("platform".to_string(), json!("linux"));
        result.insert("backend".to_string(), json!("stack_browser"));
        result.insert(
            "state_path".to_string(),
            json!(self.auth_state_path.display().to_string()),
        );
        result.insert(
            "credential_store".to_string(),
            json!(self.auth_credential_store.backend_name()),
        );
        result.insert(
            "credentials_path".to_string(),
            json!(self.auth_credentials_path.display().to_string()),
        );
        if let Some(reason) = self.auth_credential_store.fallback_reason() {
            result.insert(
                "credential_store_fallback_reason".to_string(),
                json!(reason),
            );
        }
        if self.auth_state.signed_in {
            if let Some(user) = &self.auth_state.user {
                result.insert("user".to_string(), user.to_value());
            }
            if let Some(team_id) = &self.auth_state.selected_team_id {
                result.insert("selected_team_id".to_string(), json!(team_id));
            }
            if !self.auth_state.teams.is_empty() {
                result.insert(
                    "teams".to_string(),
                    Value::Array(
                        self.auth_state
                            .teams
                            .iter()
                            .map(AuthTeam::to_value)
                            .collect(),
                    ),
                );
            }
        }
        Value::Object(result)
    }

    fn auth_sign_in_url(&mut self) -> AppResult<Value> {
        let callback_state = new_auth_callback_state();
        let url = linux_auth_sign_in_url(&callback_state)?;
        self.auth_pending_callback_state = Some(callback_state);
        let launcher = linux_auth_launcher();
        Ok(json!({
            "url": url,
            "available": launcher.is_some(),
            "platform": "linux",
            "backend": "stack_browser",
            "launcher": launcher.as_ref().map(linux_auth_launcher_value)
        }))
    }

    fn auth_begin_sign_in(&mut self, _params: &Value) -> AppResult<Value> {
        if self.auth_state.signed_in {
            let mut result = self.auth_status(false);
            result["already_signed_in"] = json!(true);
            return Ok(result);
        }

        let callback_state = self
            .auth_pending_callback_state
            .clone()
            .unwrap_or_else(new_auth_callback_state);
        let sign_in_url = linux_auth_sign_in_url(&callback_state)?;
        self.auth_pending_callback_state = Some(callback_state);
        if let Some(launcher) = linux_auth_launcher() {
            launch_linux_auth_url(&launcher, &sign_in_url)?;
            let mut result = self.auth_status(false);
            result["sign_in_started"] = json!(true);
            result["sign_in_url"] = json!(sign_in_url);
            result["launcher"] = linux_auth_launcher_value(&launcher);
            result["message"] = json!(
                "Opened the Linux sign-in URL. Complete sign-in in the browser, then run `cmux auth status`."
            );
            return Ok(result);
        }

        let mut result = self.auth_status(true);
        result["sign_in_url"] = json!(sign_in_url);
        result["message"] = json!(
            "No Linux desktop URL opener was found. Install xdg-utils or set CMUX_LINUX_AUTH_OPEN_COMMAND, then retry."
        );
        Ok(result)
    }

    fn auth_select_team(&mut self, params: &Value) -> AppResult<Value> {
        if !self.auth_state.signed_in {
            return Err(AppError::unauthorized(
                "Sign in before selecting an active team",
            ));
        }
        let value = params
            .get("team_id")
            .or_else(|| params.get("teamId"))
            .ok_or_else(|| AppError::invalid_params("team_id is required"))?;
        let team_id = value
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string);
        if let Some(team_id) = &team_id {
            if !self.auth_state.teams.iter().any(|team| team.id == *team_id) {
                return Err(AppError::not_found(format!(
                    "auth team not found: {team_id}"
                )));
            }
        }
        self.auth_state.selected_team_id = team_id;
        self.auth_state.team_selection_overridden = true;
        save_auth_state(&self.auth_state_path, &self.auth_state)?;
        let mut result = self.auth_status(false);
        result["team_selection_updated"] = json!(true);
        Ok(result)
    }

    fn auth_complete_callback(&mut self, callback_url: &str) -> AppResult<Value> {
        let payload = parse_auth_callback(callback_url)?;
        if let Some(callback_state) = payload.callback_state.as_deref() {
            if self.auth_pending_callback_state.as_deref() != Some(callback_state) {
                return Err(AppError::unauthorized(
                    "auth callback state did not match the active sign-in attempt",
                ));
            }
        }

        let credentials = AuthCredentials {
            access_token: Some(payload.access_token),
            refresh_token: Some(payload.refresh_token),
        };
        let auth_state = validate_stack_auth_session(&credentials)?;
        self.auth_credential_store.save(&credentials)?;
        self.auth_credential_store.fallback_reason = None;
        self.auth_credentials = credentials;
        self.auth_state = auth_state;
        save_auth_state(&self.auth_state_path, &self.auth_state)?;
        self.auth_pending_callback_state = None;

        let mut result = self.auth_status(false);
        result["callback_completed"] = json!(true);
        Ok(result)
    }

    fn auth_sign_out(&mut self) -> AppResult<Value> {
        let was_signed_in = self.auth_state.signed_in;
        let credentials = self.auth_credentials.clone();
        let invalidated_refresh_token_hash = auth_refresh_token_hash(&credentials);
        self.auth_credentials = AuthCredentials::default();
        self.auth_state = AuthState {
            invalidated_refresh_token_hash,
            ..AuthState::default()
        };
        save_auth_state(&self.auth_state_path, &self.auth_state)?;
        let credential_clear = self.auth_credential_store.save(&self.auth_credentials);
        if credential_clear.is_ok() {
            self.auth_state.invalidated_refresh_token_hash = None;
            save_auth_state(&self.auth_state_path, &self.auth_state)?;
        }
        self.auth_pending_callback_state = None;
        let mut result = self.auth_status(false);
        result["credential_store_clear_succeeded"] = json!(credential_clear.is_ok());
        if let Err(error) = credential_clear {
            result["credential_store_clear_error"] = json!(cap_chars(&error.message, 512));
        }
        if !was_signed_in {
            result["already_signed_out"] = json!(true);
        } else {
            result["server_revocation_attempted"] = json!(credentials.is_complete());
            result["server_revocation_succeeded"] =
                json!(revoke_stack_auth_session(&credentials).is_ok());
        }
        Ok(result)
    }

