    fn vm_list(&mut self, _params: &Value) -> AppResult<Value> {
        let response = self.vm_api_request(
            reqwest::Method::GET,
            &[],
            None,
            &[],
            Duration::from_secs(30),
        )?;
        let items = response
            .get("vms")
            .and_then(Value::as_array)
            .ok_or_else(|| vm_error("Cloud VM list response was missing the `vms` array"))?;
        let vms = items
            .iter()
            .map(Self::vm_summary_payload)
            .collect::<AppResult<Vec<_>>>()?;
        Ok(json!({"vms": vms}))
    }

    fn vm_create(&mut self, params: &Value) -> AppResult<Value> {
        let idempotency_key = string_param(params, "idempotency_key")
            .and_then(non_empty_trimmed)
            .ok_or_else(|| {
                AppError::invalid_params(
                    "vm.create requires `idempotency_key`. Use `cmux vm new` instead of calling the socket method directly.",
                )
            })?;
        let mut body = Map::new();
        if let Some(provider) = string_param(params, "provider").and_then(non_empty_trimmed) {
            body.insert("provider".to_string(), json!(provider));
        }
        if let Some(image) = string_param(params, "image").and_then(non_empty_trimmed) {
            body.insert("image".to_string(), json!(image));
        }
        let response = self.vm_api_request(
            reqwest::Method::POST,
            &[],
            Some(Value::Object(body)),
            &[("Idempotency-Key", idempotency_key)],
            Duration::from_secs(16 * 60),
        )?;
        Self::vm_summary_payload(&response)
    }

    fn vm_destroy(&mut self, params: &Value) -> AppResult<Value> {
        let vm_id = Self::vm_required_string(
            params,
            "id",
            "vm.destroy requires `id`. Run `cmux vm ls` to find one, then `cmux vm rm <id>`.",
        )?;
        self.vm_api_request(
            reqwest::Method::DELETE,
            &[vm_id.as_str()],
            None,
            &[],
            Duration::from_secs(30),
        )?;
        Ok(json!({ "ok": true }))
    }

    fn vm_exec(&mut self, params: &Value) -> AppResult<Value> {
        let vm_id = Self::vm_required_string(
            params,
            "id",
            "vm.exec requires `id`. Run `cmux vm ls` to find one.",
        )?;
        let command = Self::vm_required_string(
            params,
            "command",
            "vm.exec requires `command`. From the CLI, use `cmux vm exec <id> -- <command>`.",
        )?;
        let timeout_ms = int_param(params, "timeout_ms").unwrap_or(30_000).max(1) as u64;
        let response = self.vm_api_request(
            reqwest::Method::POST,
            &[vm_id.as_str(), "exec"],
            Some(json!({"command": command, "timeoutMs": timeout_ms})),
            &[],
            Duration::from_millis(timeout_ms.saturating_add(5_000)),
        )?;
        let exit_code = response
            .get("exitCode")
            .or_else(|| response.get("exit_code"))
            .and_then(json_i64)
            .ok_or_else(|| vm_error("Cloud VM exec response was missing `exitCode`"))?;
        Ok(json!({
            "exit_code": exit_code,
            "stdout": response.get("stdout").and_then(Value::as_str).unwrap_or_default(),
            "stderr": response.get("stderr").and_then(Value::as_str).unwrap_or_default()
        }))
    }

    fn vm_ssh_info(&mut self, params: &Value) -> AppResult<Value> {
        let vm_id = Self::vm_required_string(
            params,
            "id",
            "vm.ssh_info requires `id`. Run `cmux vm ls` to find one.",
        )?;
        let response = self.vm_api_request(
            reqwest::Method::POST,
            &[vm_id.as_str(), "ssh-endpoint"],
            Some(json!({})),
            &[],
            Duration::from_secs(30),
        )?;
        Self::vm_ssh_info_payload(&response)
    }

    fn vm_attach_info(&mut self, params: &Value) -> AppResult<Value> {
        let vm_id = Self::vm_required_string(
            params,
            "id",
            "vm.attach_info requires `id`. Run `cmux vm ls` to find one, then `cmux vm ssh <id>`.",
        )?;
        let require_daemon = bool_param(params, "require_daemon")
            .or_else(|| bool_param(params, "requireDaemon"))
            .unwrap_or(false);
        let response = self.vm_api_request(
            reqwest::Method::POST,
            &[vm_id.as_str(), "attach-endpoint"],
            Some(json!({"requireDaemon": require_daemon})),
            &[],
            Duration::from_secs(16 * 60),
        )?;
        Self::vm_attach_info_payload(&response)
    }

    fn vm_api_request(
        &mut self,
        method: reqwest::Method,
        path_segments: &[&str],
        json_body: Option<Value>,
        extra_headers: &[(&str, String)],
        timeout: Duration,
    ) -> AppResult<Value> {
        const MAX_RESPONSE_BYTES: usize = 4 * 1024 * 1024;

        if !self.auth_state.signed_in || !self.auth_credentials.is_complete() {
            return Err(vm_not_signed_in_error());
        }
        self.ensure_fresh_auth_access_token(false)
            .map_err(|error| vm_error(error.message))?;

        let access_token = self
            .auth_credentials
            .access_token
            .as_deref()
            .filter(|token| !token.is_empty())
            .ok_or_else(vm_not_signed_in_error)?;
        let refresh_token = self
            .auth_credentials
            .refresh_token
            .as_deref()
            .filter(|token| !token.is_empty())
            .ok_or_else(vm_not_signed_in_error)?;
        if !self.auth_state.signed_in {
            return Err(vm_not_signed_in_error());
        }

        let base = normalized_env("CMUX_VM_API_BASE_URL")
            .unwrap_or_else(|| "https://cmux.com".to_string());
        let mut url = Url::parse(&base)
            .map_err(|_| vm_error("CMUX_VM_API_BASE_URL must be an absolute HTTP(S) URL"))?;
        if !matches!(url.scheme(), "http" | "https") || url.host_str().is_none() {
            return Err(vm_error(
                "CMUX_VM_API_BASE_URL must be an absolute HTTP(S) URL",
            ));
        }
        let base_path = url.path().trim_end_matches('/').to_string();
        url.set_path(&format!("{base_path}/api/vm"));
        url.set_query(None);
        url.set_fragment(None);
        {
            let mut segments = url
                .path_segments_mut()
                .map_err(|_| vm_error("could not build the Cloud VM request URL"))?;
            for segment in path_segments {
                if segment.is_empty() {
                    return Err(vm_error("Cloud VM request path contained an empty segment"));
                }
                segments.push(segment);
            }
        }

        let client = reqwest::blocking::Client::builder()
            .connect_timeout(Duration::from_secs(5))
            .timeout(timeout)
            .build()
            .map_err(|_| vm_error("failed to initialize the Cloud VM HTTP client"))?;
        let mut request = client
            .request(method, url.clone())
            .bearer_auth(access_token)
            .header("X-Stack-Refresh-Token", refresh_token);
        if let Some(team_id) = self
            .auth_state
            .selected_team_id
            .as_deref()
            .filter(|team_id| !team_id.is_empty())
        {
            request = request.header("X-Cmux-Team-Id", team_id);
        }
        if let Some(body) = json_body {
            request = request.json(&body);
        }
        for (name, value) in extra_headers {
            request = request.header(*name, value);
        }

        let response = request.send().map_err(|error| {
            let reason = if error.is_timeout() {
                "the request timed out"
            } else if error.is_connect() {
                "the service could not be reached"
            } else {
                "the request failed"
            };
            vm_error(format!(
                "Cannot reach the cmux Cloud VM service at {} ({reason}). Retry the command after checking the service URL and network connection.",
                vm_service_origin(&url)
            ))
        })?;
        let status = response.status();
        if response
            .content_length()
            .is_some_and(|length| length > MAX_RESPONSE_BYTES as u64)
        {
            return Err(vm_error(
                "The Cloud VM backend returned an oversized response",
            ));
        }
        let mut bytes = Vec::new();
        response
            .take((MAX_RESPONSE_BYTES + 1) as u64)
            .read_to_end(&mut bytes)
            .map_err(|_| vm_error("failed to read the Cloud VM backend response"))?;
        if bytes.len() > MAX_RESPONSE_BYTES {
            return Err(vm_error(
                "The Cloud VM backend returned an oversized response",
            ));
        }
        if !status.is_success() {
            return Err(vm_http_error(status.as_u16(), &bytes));
        }
        if bytes.is_empty() {
            return Ok(Value::Null);
        }
        serde_json::from_slice(&bytes)
            .map_err(|_| vm_error("The Cloud VM backend returned malformed JSON"))
    }

    fn ensure_fresh_auth_access_token(&mut self, force: bool) -> AppResult<()> {
        match refresh_stack_auth_credentials(
            &mut self.auth_credentials,
            &mut self.auth_credential_store,
            force,
        ) {
            Ok(()) => Ok(()),
            Err(error) if error.code == "unauthorized" => {
                self.auth_state = AuthState::default();
                save_auth_state(&self.auth_state_path, &self.auth_state)?;
                Err(error)
            }
            Err(error) => Err(error),
        }
    }

    fn vm_required_string(params: &Value, key: &str, message: &'static str) -> AppResult<String> {
        string_param(params, key)
            .and_then(non_empty_trimmed)
            .ok_or_else(|| AppError::invalid_params(message))
    }

    fn vm_summary_payload(vm: &Value) -> AppResult<Value> {
        let required = |key: &str| {
            vm.get(key)
                .and_then(Value::as_str)
                .and_then(|value| non_empty_trimmed(value.to_string()))
                .ok_or_else(|| vm_error(format!("Cloud VM response was missing `{key}`")))
        };
        let created_at = vm
            .get("createdAt")
            .or_else(|| vm.get("created_at"))
            .and_then(json_i64)
            .unwrap_or(0);
        Ok(json!({
            "id": required("id")?,
            "provider": required("provider")?,
            "image": required("image")?,
            "createdAt": created_at
        }))
    }

    fn vm_ssh_info_payload(endpoint: &Value) -> AppResult<Value> {
        let required = |key: &str| {
            endpoint
                .get(key)
                .and_then(Value::as_str)
                .and_then(|value| non_empty_trimmed(value.to_string()))
                .ok_or_else(|| vm_error(format!("Cloud VM SSH response was missing `{key}`")))
        };
        let port = endpoint
            .get("port")
            .and_then(Value::as_u64)
            .filter(|port| (1..=65_535).contains(port))
            .ok_or_else(|| vm_error("Cloud VM SSH response had an invalid `port`"))?;
        let credential = endpoint
            .get("credential")
            .and_then(Value::as_object)
            .ok_or_else(|| vm_error("Cloud VM SSH response was missing `credential`"))?;
        let credential = match credential.get("kind").and_then(Value::as_str) {
            Some("password") => json!({
                "kind": "password",
                "value": credential.get("value").and_then(Value::as_str).ok_or_else(|| vm_error("Cloud VM SSH password credential was malformed"))?
            }),
            Some("authorizedKey") => json!({
                "kind": "authorizedKey",
                "private_key_pem": credential.get("privateKeyPem").or_else(|| credential.get("private_key_pem")).and_then(Value::as_str).ok_or_else(|| vm_error("Cloud VM SSH key credential was malformed"))?
            }),
            _ => {
                return Err(vm_error(
                    "Cloud VM SSH response used an unsupported credential kind",
                ))
            }
        };
        Ok(json!({
            "host": required("host")?,
            "port": port,
            "username": required("username")?,
            "credential": credential,
            "public_key_fingerprint": endpoint.get("publicKeyFingerprint").or_else(|| endpoint.get("public_key_fingerprint")).and_then(Value::as_str).map_or(Value::Null, |value| json!(value))
        }))
    }

    fn vm_attach_info_payload(endpoint: &Value) -> AppResult<Value> {
        let transport = endpoint
            .get("transport")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_ascii_lowercase)
            .ok_or_else(|| vm_error("Cloud VM attach response was missing `transport`"))?;
        match transport.as_str() {
            "ssh" => {
                let mut payload = Self::vm_ssh_info_payload(endpoint)?;
                payload["transport"] = json!("ssh");
                Ok(payload)
            }
            "websocket" => Self::vm_websocket_endpoint_payload(endpoint, true),
            _ => Err(vm_error(
                "Cloud VM attach response used an unsupported transport type",
            )),
        }
    }

    fn vm_websocket_endpoint_payload(
        endpoint: &Value,
        include_transport: bool,
    ) -> AppResult<Value> {
        let required = |camel_key: &str, snake_key: &str| {
            endpoint
                .get(camel_key)
                .or_else(|| endpoint.get(snake_key))
                .and_then(Value::as_str)
                .and_then(|value| non_empty_trimmed(value.to_string()))
                .ok_or_else(|| {
                    vm_error(format!(
                        "Cloud VM attach response was missing `{camel_key}`"
                    ))
                })
        };
        let headers = endpoint
            .get("headers")
            .and_then(Value::as_object)
            .map(|headers| {
                headers
                    .iter()
                    .filter_map(|(name, value)| {
                        value.as_str().map(|value| (name.clone(), json!(value)))
                    })
                    .collect::<Map<String, Value>>()
            })
            .unwrap_or_default();
        let expires_at_unix = endpoint
            .get("expiresAtUnix")
            .or_else(|| endpoint.get("expires_at_unix"))
            .and_then(json_i64)
            .unwrap_or(0);
        let daemon = match endpoint.get("daemon") {
            None | Some(Value::Null) => Value::Null,
            Some(value) if value.is_object() => Self::vm_websocket_endpoint_payload(value, false)?,
            Some(_) => {
                return Err(vm_error(
                    "Cloud VM attach response contained a malformed `daemon` endpoint",
                ))
            }
        };
        let mut payload = json!({
            "url": required("url", "url")?,
            "headers": headers,
            "token": required("token", "token")?,
            "session_id": required("sessionId", "session_id")?,
            "expires_at_unix": expires_at_unix,
            "daemon": daemon
        });
        if include_transport {
            payload["transport"] = json!("websocket");
        } else if let Some(object) = payload.as_object_mut() {
            object.remove("daemon");
        }
        Ok(payload)
    }

    fn mobile_dev_stack_auth_configure(&mut self, params: &Value) -> AppResult<Value> {
        if bool_param(params, "enabled") == Some(false) {
            self.mobile_dev_stack_auth_token = None;
            return Ok(json!({"enabled": false}));
        }

        let token = string_param(params, "token")
            .and_then(non_empty_trimmed)
            .ok_or_else(|| {
                AppError::invalid_params("mobile.dev_stack_auth.configure requires params.token")
            })?;
        let token_prefix = token.chars().take(8).collect::<String>();
        self.mobile_dev_stack_auth_token = Some(token);
        Ok(json!({
            "enabled": true,
            "token_prefix": token_prefix
        }))
    }

    pub(crate) fn mobile_network_auth_context(&self) -> mobile_host::AuthContext {
        mobile_host::AuthContext {
            local_user_id: self
                .auth_state
                .signed_in
                .then(|| self.auth_state.user.as_ref()?.id.clone())
                .flatten(),
            dev_access_token: self.mobile_dev_stack_auth_token.clone(),
        }
    }

    fn mobile_events_subscribe(&mut self, params: &Value) -> AppResult<Value> {
        let mut topics = params
            .get("topics")
            .and_then(Value::as_array)
            .map(|values| {
                values
                    .iter()
                    .filter_map(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .map(ToString::to_string)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        topics.sort();
        topics.dedup();
        if topics.is_empty() {
            return Err(AppError::invalid_params("topics is required"));
        }
        let stream_id = string_param(params, "stream_id")
            .and_then(non_empty_trimmed)
            .unwrap_or_else(new_id);
        let already_subscribed = self.mobile_event_subscriptions.contains_key(&stream_id);
        self.mobile_event_subscriptions
            .insert(stream_id.clone(), topics.clone());
        Ok(json!({
            "stream_id": stream_id,
            "topics": topics,
            "already_subscribed": already_subscribed
        }))
    }

    fn mobile_events_unsubscribe(&mut self, params: &Value) -> AppResult<Value> {
        let stream_id = string_param(params, "stream_id").unwrap_or_default();
        let removed = self
            .mobile_event_subscriptions
            .remove(stream_id.as_str())
            .is_some();
        Ok(json!({
            "stream_id": stream_id,
            "removed": removed
        }))
    }

    fn chat_sessions_dump(&self) -> AppResult<Value> {
        let focused = self.focused_context()?;
        let sessions = self.mobile_chat_session_rows(None)?;
        let session_count = sessions.len();
        Ok(json!({
            "sessions": sessions,
            "session_count": session_count,
            "workspace_count": self.workspaces.len(),
            "surface_count": self.surfaces.len(),
            "focused": focused
        }))
    }

    fn mobile_chat_sessions(&self, params: &Value) -> AppResult<Value> {
        let workspace_id = self.resolve_workspace_optional(
            params
                .get("workspace_id")
                .or_else(|| params.get("workspace")),
        )?;
        Ok(json!({"sessions": self.mobile_chat_session_rows(workspace_id.as_deref())?}))
    }

    fn mobile_chat_history(&mut self, params: &Value) -> AppResult<Value> {
        let session_id = string_param(params, "session_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("Missing session_id"))?;
        let (_workspace_id, surface_id) = self.resolve_mobile_chat_session(&session_id)?;
        if !self.uses_renderer_owned_terminal_input(&surface_id) {
            self.ensure_surface_terminal_started(&surface_id)?;
        }
        let limit = int_param(params, "limit").unwrap_or(100).clamp(1, 200);
        let before_seq = int_param(params, "before_seq");
        let include_block = before_seq.map(|seq| seq > 1).unwrap_or(true);
        let (mut text, pending_input) = if let Some(surface) = self.surfaces.get(&surface_id) {
            let text = surface
                .buffer
                .lock()
                .ok()
                .map(|buffer| clean_terminal_text(&buffer))
                .unwrap_or_default();
            (text, pending_visible_input_line(&surface.input_history))
        } else {
            (String::new(), None)
        };
        if let Some(pending) = pending_input {
            append_line_if_missing(&mut text, &pending);
        }
        let terminal_blocks = if include_block && limit > 0 {
            vec![json!({
                "id": 1,
                "command": "",
                "output": text,
                "exit_code": Value::Null,
                "is_running": false,
                "is_interactive": false
            })]
        } else {
            Vec::new()
        };
        Ok(json!({
            "messages": [],
            "has_more": false,
            "terminal_blocks": terminal_blocks
        }))
    }

    fn mobile_chat_send(&mut self, params: &Value) -> AppResult<Value> {
        let session_id = string_param(params, "session_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("Missing session_id"))?;
        let text = string_param(params, "text").unwrap_or_default();
        let attachments = params
            .get("attachments")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        if text.is_empty() && attachments.is_empty() {
            return Err(AppError::invalid_params("Nothing to send"));
        }
        let (workspace_id, surface_id) = self.resolve_mobile_chat_session(&session_id)?;

        let mut attachment_count = 0usize;
        for (index, attachment) in attachments.iter().enumerate() {
            let data_b64 = string_param(attachment, "data_b64")
                .filter(|value| !value.trim().is_empty())
                .ok_or_else(|| AppError::invalid_params("Attachment missing data_b64"))?;
            let image_format =
                string_param(attachment, "format").unwrap_or_else(|| "png".to_string());
            self.mobile_terminal_paste_image(&json!({
                "workspace_id": workspace_id,
                "surface_id": surface_id,
                "image_base64": data_b64,
                "image_format": image_format
            }))?;
            attachment_count += 1;
            if index + 1 < attachments.len() || !text.is_empty() {
                self.surface_send_text(&json!({
                    "workspace_id": workspace_id,
                    "surface_id": surface_id,
                    "text": " "
                }))?;
            }
        }

        let submitted = if text.is_empty() {
            self.surface_send_key(&json!({
                "workspace_id": workspace_id,
                "surface_id": surface_id,
                "key": "enter"
            }))?;
            true
        } else {
            let mut paste = self.mobile_terminal_paste(&json!({
                "workspace_id": workspace_id,
                "surface_id": surface_id,
                "text": text,
                "submit_key": string_param(params, "submit_key").unwrap_or_else(|| "return".to_string())
            }))?;
            paste["session_id"] = json!(session_id);
            paste["attachment_count"] = json!(attachment_count);
            return Ok(paste);
        };

        Ok(json!({
            "session_id": session_id,
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "submitted": submitted,
            "queued": false,
            "attachment_count": attachment_count
        }))
    }

    fn mobile_chat_interrupt(&mut self, params: &Value) -> AppResult<Value> {
        let session_id = string_param(params, "session_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("Missing session_id"))?;
        let hard = bool_param(params, "hard").unwrap_or(false);
        let (workspace_id, surface_id) = self.resolve_mobile_chat_session(&session_id)?;
        self.surface_send_key(&json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "key": if hard { "ctrl+c" } else { "escape" }
        }))?;
        Ok(json!({
            "session_id": session_id,
            "interrupted": true,
            "hard": hard
        }))
    }

    fn mobile_chat_answer(&mut self, params: &Value) -> AppResult<Value> {
        let session_id = string_param(params, "session_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("Missing session_id or option_index"))?;
        let option_index = int_param(params, "option_index")
            .ok_or_else(|| AppError::invalid_params("Missing session_id or option_index"))?;
        if !(0..=8).contains(&option_index) {
            return Err(AppError::invalid_params(
                "Missing session_id or option_index",
            ));
        }
        let (workspace_id, surface_id) = self.resolve_mobile_chat_session(&session_id)?;
        let digit = (option_index + 1).to_string();
        self.surface_send_text(&json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "text": digit
        }))?;
        Ok(json!({
            "session_id": session_id,
            "answered": true,
            "option_index": option_index
        }))
    }

    fn mobile_chat_session_rows(&self, workspace_id: Option<&str>) -> AppResult<Vec<Value>> {
        if let Some(workspace_id) = workspace_id {
            if !self.workspaces.contains_key(workspace_id) {
                return Err(AppError::not_found("Workspace not found"));
            }
        }
        let mut rows = self
            .surfaces
            .values()
            .filter_map(|surface| {
                let pane = self.panes.get(&surface.pane_id)?;
                if workspace_id.is_some_and(|id| id != pane.workspace_id) {
                    return None;
                }
                self.mobile_chat_session_descriptor(surface, &pane.workspace_id)
            })
            .collect::<Vec<_>>();
        rows.sort_by(|left, right| {
            let left_key = left["terminal_id"].as_str().unwrap_or_default();
            let right_key = right["terminal_id"].as_str().unwrap_or_default();
            left_key.cmp(right_key)
        });
        Ok(rows)
    }

    fn mobile_chat_session_descriptor(
        &self,
        surface: &Surface,
        workspace_id: &str,
    ) -> Option<Value> {
        let agent_kind = self.mobile_chat_agent_kind(surface)?;
        let workspace = self.workspaces.get(workspace_id)?;
        let last_activity_at = iso_timestamp_millis(current_unix_millis());
        Some(json!({
            "session_id": mobile_chat_session_id(&surface.id),
            "agent_kind": agent_kind,
            "kind": "terminal",
            "title": mobile_chat_session_title(surface, workspace),
            "workspace_id": workspace_id,
            "terminal_id": surface.id,
            "cwd": surface.terminal_cwd.as_deref().or(workspace.cwd.as_deref()),
            "state": mobile_chat_state_value(surface, &last_activity_at),
            "last_activity_at": last_activity_at
        }))
    }

    fn mobile_chat_agent_kind(&self, surface: &Surface) -> Option<String> {
        if surface.kind != SurfaceKind::Terminal {
            return None;
        }
        if let Some(provider) = surface
            .terminal_env
            .get("CMUX_AGENT_PROVIDER")
            .and_then(|value| non_empty_trimmed(value.clone()))
        {
            return Some(normalized_chat_agent_kind(&provider));
        }
        let mut haystack = String::new();
        haystack.push_str(&surface.title);
        haystack.push('\n');
        if let Some(title) = &surface.terminal_title {
            haystack.push_str(title);
            haystack.push('\n');
        }
        if let Some(command) = &surface.terminal_command {
            haystack.push_str(command);
        }
        let normalized = haystack.to_ascii_lowercase();
        if normalized.contains("claude") || surface.title.trim_start().starts_with('\u{2733}') {
            Some("claude".to_string())
        } else if normalized.contains("codex") {
            Some("codex".to_string())
        } else if normalized.contains("opencode") || normalized.contains("open code") {
            Some("opencode".to_string())
        } else {
            None
        }
    }

    fn resolve_mobile_chat_session(&self, session_id: &str) -> AppResult<(String, String)> {
        let requested = session_id.trim();
        for surface in self.surfaces.values() {
            let Some(pane) = self.panes.get(&surface.pane_id) else {
                continue;
            };
            if self.mobile_chat_agent_kind(surface).is_none() {
                continue;
            }
            if requested == surface.id || requested == mobile_chat_session_id(&surface.id) {
                return Ok((pane.workspace_id.clone(), surface.id.clone()));
            }
        }
        Err(AppError::not_found(
            "The agent's terminal moved. Open it once in cmux (or send the agent any prompt there), then retry.",
        ))
    }

    fn session_restore_previous(&mut self) -> AppResult<Value> {
        let binding = match self
            .surfaces
            .values()
            .filter_map(|surface| surface.resume_binding.clone())
            .max_by(|left, right| {
                left.updated_at
                    .partial_cmp(&right.updated_at)
                    .unwrap_or(std::cmp::Ordering::Equal)
            }) {
            Some(binding) => binding,
            None => return self.session_restore_persisted_snapshot(),
        };
        let workspace_title = binding
            .name
            .clone()
            .or_else(|| binding.kind.clone())
            .unwrap_or_else(|| "Restored Session".to_string());
        let mut surface = SurfaceSpec::terminal();
        surface.title = Some(workspace_title.clone());
        surface.custom_title = true;
        surface.command = Some(binding.command.clone());
        surface.env = binding.environment.clone();

        let window_id = self.current_window.clone();
        let workspace_id = self.create_workspace_from_specs(
            &window_id,
            workspace_title,
            binding.cwd.clone(),
            vec![PaneSpec {
                surfaces: vec![surface],
            }],
            true,
        )?;
        if let Some(workspace) = self.workspaces.get_mut(&workspace_id) {
            workspace.custom_title = true;
        }
        let surface_id = self
            .workspace_selected_surface(&workspace_id)
            .ok_or_else(|| AppError::internal("failed to restore session surface"))?;
        if let Some(surface) = self.surfaces.get_mut(&surface_id) {
            surface.resume_binding = Some(binding.clone());
        }
        let pane_id = self
            .surfaces
            .get(&surface_id)
            .map(|surface| surface.pane_id.clone())
            .ok_or_else(|| AppError::not_found("surface not found"))?;
        Ok(json!({
            "restored": true,
            "window_id": window_id,
            "window_ref": self.window_ref(&window_id),
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(&pane_id),
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "resume_binding": resume_binding_payload(Some(&binding))
        }))
    }

    fn session_restore_persisted_snapshot(&mut self) -> AppResult<Value> {
        let path = session_snapshot_path();
        if !path.exists() {
            return Err(AppError::not_found(
                "No previous session snapshot available",
            ));
        }
        let snapshot = read_session_snapshot(&path)?;
        let window_count = snapshot.windows.len();
        let workspace_count = snapshot
            .windows
            .iter()
            .map(|window| window.workspaces.len())
            .sum::<usize>();
        let pane_count = snapshot
            .windows
            .iter()
            .flat_map(|window| window.workspaces.iter())
            .map(|workspace| workspace.panes.len())
            .sum::<usize>();
        let surface_count = snapshot
            .windows
            .iter()
            .flat_map(|window| window.workspaces.iter())
            .flat_map(|workspace| workspace.panes.iter())
            .map(|pane| pane.surfaces.len())
            .sum::<usize>();
        self.restore_session_snapshot(snapshot)?;
        Ok(json!({
            "restored": true,
            "source": "session_snapshot",
            "path": path.display().to_string(),
            "window_count": window_count,
            "workspace_count": workspace_count,
            "pane_count": pane_count,
            "surface_count": surface_count,
            "window_id": self.current_window,
            "window_ref": self.window_ref(&self.current_window)
        }))
    }

    fn feed_push(&mut self, params: &Value) -> AppResult<Value> {
        let wait_timeout = feed_wait_timeout(params)?;
        let event = feed_event_payload(params)?;
        let item = feed_item_from_event(&event)?;
        let item_id = item
            .get("id")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();
        persist_feed_audit_record(
            "feed.item.received",
            json!({
                "item": item.clone()
            }),
        );
        self.feed_items.push(item.clone());
        if self.feed_items.len() > FEED_RETAINED_LIMIT {
            let overflow = self.feed_items.len() - FEED_RETAINED_LIMIT;
            self.feed_items.drain(0..overflow);
        }

        let result = json!({
            "status": "acknowledged",
            "item_id": item_id
        });
        if wait_timeout <= 0.0 {
            persist_feed_audit_record(
                "feed.item.completed",
                json!({
                    "item": item,
                    "result": result.clone()
                }),
            );
        }
        Ok(result)
    }

    fn feed_list(&self, params: &Value) -> Value {
        let pending_only = params
            .get("pending_only")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let matching = self
            .feed_items
            .iter()
            .filter(|item| {
                !pending_only
                    || item
                        .get("status")
                        .and_then(Value::as_str)
                        .is_some_and(|status| status == "pending")
            })
            .collect::<Vec<_>>();
        let limit = params
            .get("limit")
            .and_then(Value::as_u64)
            .and_then(|limit| usize::try_from(limit).ok())
            .unwrap_or(matching.len());
        let start = matching.len().saturating_sub(limit);
        let items = matching
            .into_iter()
            .skip(start)
            .cloned()
            .collect::<Vec<_>>();
        json!({"items": items})
    }

    fn feed_jump(&mut self, params: &Value) -> AppResult<Value> {
        let workstream_id = string_param(params, "workstream_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("feed.jump requires workstream_id"))?;
        let matched_item = self
            .feed_items
            .iter()
            .rev()
            .find(|item| {
                item.get("workstream_id")
                    .and_then(Value::as_str)
                    .is_some_and(|value| value == workstream_id)
            })
            .cloned();
        let matched = matched_item.is_some();
        let mut opened = false;
        let mut focused_workspace_id: Option<String> = None;
        let mut focused_surface_id: Option<String> = None;
        if let Some(item) = matched_item {
            let item_workspace_id = feed_string(&item, "workspace_id");
            let item_surface_id = feed_string(&item, "surface_id");
            let source = feed_string(&item, "source")
                .or_else(|| feed_string(&item, "_source"))
                .unwrap_or_default();
            let hook_target = feed_hook_session_target(&source, &workstream_id);
            let workspace_id = item_workspace_id.clone().or_else(|| {
                hook_target
                    .as_ref()
                    .map(|target| target.workspace_id.clone())
            });
            let surface_id = item_surface_id.clone().or_else(|| {
                hook_target.as_ref().and_then(|target| {
                    if item_workspace_id
                        .as_deref()
                        .map_or(true, |workspace_id| workspace_id == target.workspace_id)
                    {
                        Some(target.surface_id.clone())
                    } else {
                        None
                    }
                })
            });

            if let Some(workspace_id) =
                workspace_id.filter(|workspace_id| self.workspaces.contains_key(workspace_id))
            {
                self.select_workspace_by_id(&workspace_id)?;
                opened = true;
                focused_workspace_id = Some(workspace_id.clone());
                if let Some(surface_id) = surface_id.filter(|surface_id| {
                    self.surface_workspace_id(surface_id).ok().as_deref()
                        == Some(workspace_id.as_str())
                }) {
                    self.focus_surface(&surface_id)?;
                    focused_surface_id = Some(surface_id);
                }
            }
        }
        let focused_workspace_ref = focused_workspace_id
            .as_ref()
            .map(|workspace_id| self.workspace_ref(workspace_id));
        let focused_surface_ref = focused_surface_id
            .as_ref()
            .map(|surface_id| self.surface_ref(surface_id));
        Ok(json!({
            "workstream_id": workstream_id,
            "matched": matched,
            "opened": opened,
            "workspace_id": focused_workspace_id,
            "workspace_ref": focused_workspace_ref,
            "surface_id": focused_surface_id,
            "surface_ref": focused_surface_ref
        }))
    }

    fn feed_permission_reply(&mut self, params: &Value) -> AppResult<Value> {
        let request_id = string_param(params, "request_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("feed.permission.reply requires request_id"))?;
        let mode = string_param(params, "mode").ok_or_else(|| {
            AppError::invalid_params(
                "feed.permission.reply requires mode ∈ once|always|all|bypass|deny",
            )
        })?;
        if !matches!(mode.as_str(), "once" | "always" | "all" | "bypass" | "deny") {
            return Err(AppError::invalid_params(
                "feed.permission.reply requires mode ∈ once|always|all|bypass|deny",
            ));
        }
        let decision = json!({"kind": "permission", "mode": mode});
        let resolved_item =
            self.resolve_feed_request(&request_id, "permissionRequest", decision.clone());
        let result = json!({"delivered": true});
        persist_feed_audit_record(
            "feed.item.resolved",
            json!({
                "request_id": request_id,
                "kind": "permissionRequest",
                "decision": decision,
                "item": resolved_item,
                "result": result.clone()
            }),
        );
        Ok(result)
    }

    fn feed_question_reply(&mut self, params: &Value) -> AppResult<Value> {
        let request_id = string_param(params, "request_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("feed.question.reply requires request_id"))?;
        let selections = string_array_param(params, "selections");
        if !params
            .get("selections")
            .is_some_and(|value| value.as_array().is_some())
        {
            return Err(AppError::invalid_params(
                "feed.question.reply requires selections: [string]",
            ));
        }
        let decision = json!({"kind": "question", "selections": selections});
        let resolved_item = self.resolve_feed_request(&request_id, "question", decision.clone());
        let result = json!({"delivered": true});
        persist_feed_audit_record(
            "feed.item.resolved",
            json!({
                "request_id": request_id,
                "kind": "question",
                "decision": decision,
                "item": resolved_item,
                "result": result.clone()
            }),
        );
        Ok(result)
    }

    fn feed_exit_plan_reply(&mut self, params: &Value) -> AppResult<Value> {
        let request_id = string_param(params, "request_id")
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| AppError::invalid_params("feed.exit_plan.reply requires request_id"))?;
        let mode = string_param(params, "mode").ok_or_else(|| {
            AppError::invalid_params(
                "feed.exit_plan.reply requires mode ∈ ultraplan|bypassPermissions|autoAccept|manual|deny",
            )
        })?;
        if !matches!(
            mode.as_str(),
            "ultraplan" | "bypassPermissions" | "autoAccept" | "manual" | "deny"
        ) {
            return Err(AppError::invalid_params(
                "feed.exit_plan.reply requires mode ∈ ultraplan|bypassPermissions|autoAccept|manual|deny",
            ));
        }
        let mut decision = json!({"kind": "exit_plan", "mode": mode});
        if let Some(feedback) =
            string_param(params, "feedback").filter(|value| !value.trim().is_empty())
        {
            decision["feedback"] = json!(feedback);
        }
        let resolved_item = self.resolve_feed_request(&request_id, "exitPlan", decision.clone());
        let result = json!({"delivered": true});
        persist_feed_audit_record(
            "feed.item.resolved",
            json!({
                "request_id": request_id,
                "kind": "exitPlan",
                "decision": decision,
                "item": resolved_item,
                "result": result.clone()
            }),
        );
        Ok(result)
    }

    fn feed_clear(&mut self) -> Value {
        let removed = self.feed_items.len();
        self.feed_items.clear();
        let result = json!({
            "cleared": true,
            "removed": removed,
            "persisted": true
        });
        persist_feed_audit_record(
            "feed.cleared",
            json!({
                "removed": removed,
                "result": result.clone()
            }),
        );
        result
    }

    fn resolve_feed_request(
        &mut self,
        request_id: &str,
        kind: &str,
        decision: Value,
    ) -> Option<Value> {
        if let Some(item) = self.feed_items.iter_mut().rev().find(|item| {
            item.get("request_id")
                .and_then(Value::as_str)
                .is_some_and(|value| value == request_id)
                && item
                    .get("kind")
                    .and_then(Value::as_str)
                    .is_some_and(|value| value == kind)
                && item
                    .get("status")
                    .and_then(Value::as_str)
                    .is_some_and(|value| value == "pending")
        }) {
            mark_feed_item_resolved(item, decision);
            return Some(item.clone());
        }
        None
    }

    pub(crate) fn feed_completed_wait_result(&mut self, item_id: &str) -> Option<Value> {
        let item = self
            .feed_items
            .iter()
            .find(|item| item.get("id").and_then(Value::as_str) == Some(item_id))?
            .clone();
        let status = item.get("status").and_then(Value::as_str)?;
        let result = match status {
            "resolved" => json!({
                "status": "resolved",
                "item_id": item_id,
                "decision": item.get("decision").cloned().unwrap_or(Value::Null)
            }),
            "expired" => json!({
                "status": "timed_out",
                "item_id": item_id
            }),
            _ => return None,
        };
        persist_feed_audit_record(
            "feed.item.completed",
            json!({
                "item": item,
                "result": result.clone()
            }),
        );
        Some(result)
    }

    pub(crate) fn feed_timeout_wait_result(&mut self, item_id: &str) -> Value {
        let item = if let Some(item) = self
            .feed_items
            .iter_mut()
            .find(|item| item.get("id").and_then(Value::as_str) == Some(item_id))
        {
            if item
                .get("status")
                .and_then(Value::as_str)
                .is_some_and(|status| status == "pending")
            {
                mark_feed_item_expired(item);
            }
            Some(item.clone())
        } else {
            None
        };
        let result = match item
            .as_ref()
            .and_then(|item| item.get("status").and_then(Value::as_str))
        {
            Some("resolved") => json!({
                "status": "resolved",
                "item_id": item_id,
                "decision": item
                    .as_ref()
                    .and_then(|item| item.get("decision"))
                    .cloned()
                    .unwrap_or(Value::Null)
            }),
            _ => json!({
                "status": "timed_out",
                "item_id": item_id
            }),
        };
        persist_feed_audit_record(
            "feed.item.completed",
            json!({
                "item": item,
                "result": result.clone()
            }),
        );
        result
    }

    fn refresh_agent_hibernation_settings(&mut self) {
        self.agent_hibernation_settings = if self.agent_hibernation_settings_use_cmux_config {
            config::agent_hibernation_settings()
        } else {
            agent_hibernation_settings::load(&self.agent_hibernation_settings_path)
        };
    }

    fn agent_hibernation_status(&mut self) -> Value {
        self.refresh_agent_hibernation_settings();
        let mut payload = self
            .agent_hibernation_settings
            .payload(&self.agent_hibernation_settings_path);
        if let Some(object) = payload.as_object_mut() {
            object.insert(
                "hibernated_surface_count".to_string(),
                json!(self
                    .surfaces
                    .values()
                    .filter(|surface| surface.agent_hibernation.is_some())
                    .count()),
            );
            object.insert(
                "pending_confirmation_count".to_string(),
                json!(self.agent_hibernation_confirmations.len()),
            );
            object.insert("runtime_supported".to_string(), json!(true));
        }
        payload
    }

    fn set_agent_hibernation_enabled(&mut self, enabled: bool) -> AppResult<Value> {
        self.set_agent_hibernation_settings(&json!({"enabled": enabled}))
    }

    fn set_agent_hibernation_settings(&mut self, params: &Value) -> AppResult<Value> {
        let mut settings = self.agent_hibernation_settings;
        let mut changed = false;
        if let Some(value) = params.get("enabled") {
            settings.enabled = value
                .as_bool()
                .ok_or_else(|| AppError::invalid_params("enabled must be true or false"))?;
            changed = true;
        }
        if let Some(value) = params
            .get("idle_seconds")
            .or_else(|| params.get("idleSeconds"))
        {
            settings.idle_seconds = value.as_u64().ok_or_else(|| {
                AppError::invalid_params("idle_seconds must be a positive integer")
            })?;
            changed = true;
        }
        if let Some(value) = params
            .get("max_live_terminals")
            .or_else(|| params.get("maxLiveTerminals"))
        {
            settings.max_live_terminals = value.as_u64().ok_or_else(|| {
                AppError::invalid_params("max_live_terminals must be a positive integer")
            })?;
            changed = true;
        }
        if let Some(value) = params
            .get("confirmation_seconds")
            .or_else(|| params.get("confirmationSeconds"))
        {
            settings.confirmation_seconds = value.as_u64().ok_or_else(|| {
                AppError::invalid_params("confirmation_seconds must be a positive integer")
            })?;
            changed = true;
        }
        if !changed {
            return Err(AppError::invalid_params(
                "one of enabled, idle_seconds, max_live_terminals, or confirmation_seconds is required",
            ));
        }
        settings = settings.sanitized();
        if self.agent_hibernation_settings_use_cmux_config {
            config::set_agent_hibernation_settings(settings).map_err(|err| {
                AppError::internal(format!("failed to save agent hibernation settings: {err}"))
            })?;
        } else {
            agent_hibernation_settings::save(&self.agent_hibernation_settings_path, settings)
                .map_err(|err| {
                    AppError::internal(format!("failed to save agent hibernation settings: {err}"))
                })?;
        }
        self.agent_hibernation_settings = settings;
        if !settings.enabled {
            self.agent_hibernation_confirmations.clear();
            let hibernated = self
                .surfaces
                .values()
                .filter(|surface| surface.agent_hibernation.is_some())
                .map(|surface| surface.id.clone())
                .collect::<Vec<_>>();
            for surface_id in hibernated {
                let _ = self.resume_agent_hibernated_surface(&surface_id);
            }
        }
        Ok(self.agent_hibernation_status())
    }

    fn maybe_evaluate_agent_hibernation(&mut self) {
        let now_ms = current_unix_millis();
        if now_ms.saturating_sub(self.agent_hibernation_last_evaluation_ms) < 1_000 {
            return;
        }
        self.agent_hibernation_last_evaluation_ms = now_ms;
        self.refresh_agent_hibernation_settings();
        if !self.agent_hibernation_settings.enabled {
            self.agent_hibernation_confirmations.clear();
            return;
        }
        let _ = self.evaluate_agent_hibernation(now_ms);
    }

    fn evaluate_agent_hibernation(&mut self, now_ms: u64) -> usize {
        let settings = self.agent_hibernation_settings;
        if !settings.enabled {
            self.agent_hibernation_confirmations.clear();
            return 0;
        }

        let protected = self.agent_hibernation_protected_surface_ids();
        let process_snapshot = LinuxProcessSnapshot::capture(false);
        let surface_ids = self.surfaces.keys().cloned().collect::<Vec<_>>();
        let mut inputs = Vec::new();
        let mut records = HashMap::new();

        for surface_id in surface_ids {
            let Some(surface) = self.surfaces.get(&surface_id) else {
                continue;
            };
            let has_restorable_agent = surface.kind == SurfaceKind::Terminal
                && surface
                    .resume_binding
                    .as_ref()
                    .is_some_and(|binding| !binding.command.trim().is_empty())
                && !surface.remote_session_active
                && !surface
                    .terminal_env
                    .contains_key(REMOTE_TMUX_CONNECTION_ENV);
            let root_pids = terminal_surface_root_pids(surface);
            let process_ids = process_snapshot.expanded_pids(&root_pids);
            let is_live = surface.agent_hibernation.is_none()
                && (surface.embedded_terminal_ready
                    || surface.terminal.is_some() && !process_ids.is_empty()
                    || !process_ids.is_empty());
            let lifecycle_idle = agent_hibernation_lifecycle_is_idle(surface);
            let has_unconfirmed_terminal_input = surface.agent_hibernation_last_input_ms
                > surface.agent_hibernation_last_lifecycle_change_ms;
            let is_protected = protected.contains(&surface_id);
            let fingerprint = (has_restorable_agent
                && is_live
                && !is_protected
                && lifecycle_idle
                && !has_unconfirmed_terminal_input)
                .then(|| agent_hibernation_fingerprint(surface, &process_ids))
                .flatten();
            let last_activity_ms = surface.agent_hibernation_last_activity_ms;

            let effective_last_activity_ms = if let Some(current_fingerprint) = fingerprint.as_ref()
            {
                let surface = self
                    .surfaces
                    .get_mut(&surface_id)
                    .expect("surface exists during hibernation evaluation");
                if surface.agent_hibernation_tail_fingerprint.as_ref() == Some(current_fingerprint)
                {
                    last_activity_ms.max(surface.agent_hibernation_tail_stable_since_ms)
                } else {
                    surface.agent_hibernation_tail_fingerprint = Some(current_fingerprint.clone());
                    surface.agent_hibernation_tail_stable_since_ms = now_ms;
                    self.agent_hibernation_confirmations.remove(&surface_id);
                    last_activity_ms.max(now_ms)
                }
            } else {
                if let Some(surface) = self.surfaces.get_mut(&surface_id) {
                    surface.agent_hibernation_tail_fingerprint = None;
                    surface.agent_hibernation_tail_stable_since_ms = now_ms;
                }
                last_activity_ms
            };

            inputs.push(agent_hibernation_settings::PlannerInput {
                surface_id: surface_id.clone(),
                has_restorable_agent,
                is_live,
                is_protected,
                lifecycle_idle,
                has_unconfirmed_terminal_input,
                last_activity_ms: effective_last_activity_ms,
            });
            records.insert(
                surface_id.clone(),
                AgentHibernationRuntimeRecord {
                    surface_id,
                    process_ids,
                    fingerprint,
                    effective_last_activity_ms,
                },
            );
        }

        let selected = agent_hibernation_settings::selected_surface_ids(&inputs, settings, now_ms);
        self.agent_hibernation_confirmations
            .retain(|surface_id, _| selected.contains(surface_id));

        let mut hibernated = 0;
        for surface_id in selected {
            let Some(record) = records.get(&surface_id).cloned() else {
                continue;
            };
            let Some(fingerprint) = record.fingerprint.as_ref() else {
                self.agent_hibernation_confirmations.remove(&surface_id);
                continue;
            };
            if let Some(confirmation) = self
                .agent_hibernation_confirmations
                .get(&surface_id)
                .cloned()
            {
                if now_ms < confirmation.due_at_ms {
                    continue;
                }
                if record.effective_last_activity_ms > confirmation.sampled_at_ms
                    || confirmation.fingerprint != *fingerprint
                {
                    self.agent_hibernation_confirmations.remove(&surface_id);
                    continue;
                }
                self.agent_hibernation_confirmations.remove(&surface_id);
                if self.hibernate_agent_surface(&record, now_ms) {
                    hibernated += 1;
                }
            } else {
                self.agent_hibernation_confirmations.insert(
                    surface_id,
                    AgentHibernationConfirmation {
                        fingerprint: fingerprint.clone(),
                        sampled_at_ms: now_ms,
                        due_at_ms: now_ms
                            .saturating_add(settings.confirmation_seconds.saturating_mul(1_000)),
                    },
                );
            }
        }

        if hibernated > 0 && session_snapshot_save_enabled() {
            let _ = self.persist_session_snapshot(true);
        }
        hibernated
    }

    fn agent_hibernation_protected_surface_ids(&self) -> HashSet<String> {
        let mut protected = HashSet::new();
        for window in &self.windows {
            let Some(workspace_id) = window.selected_workspace.as_deref() else {
                continue;
            };
            let Some(workspace) = self.workspaces.get(workspace_id) else {
                continue;
            };
            for pane_id in &workspace.panes {
                if let Some(surface_id) = self
                    .panes
                    .get(pane_id)
                    .and_then(|pane| pane.selected_surface.as_ref())
                {
                    protected.insert(surface_id.clone());
                }
            }
        }
        protected
    }

    fn hibernate_agent_surface(
        &mut self,
        record: &AgentHibernationRuntimeRecord,
        now_ms: u64,
    ) -> bool {
        let can_hibernate = self
            .surfaces
            .get(&record.surface_id)
            .is_some_and(|surface| {
                surface.agent_hibernation.is_none()
                    && surface.resume_binding.is_some()
                    && agent_hibernation_lifecycle_is_idle(surface)
                    && surface.agent_hibernation_last_input_ms
                        <= surface.agent_hibernation_last_lifecycle_change_ms
            });
        if !can_hibernate {
            return false;
        }

        let terminal = self
            .surfaces
            .get(&record.surface_id)
            .and_then(|surface| surface.terminal.clone());
        terminate_agent_hibernation_processes(&record.process_ids);
        if let Some(terminal) = terminal {
            if terminal
                .wait_for_exit(Duration::from_millis(250))
                .ok()
                .flatten()
                .is_none()
            {
                let _ = terminal.kill();
                let _ = terminal.wait_for_exit(Duration::from_millis(250));
            }
        }
        let Some(surface) = self.surfaces.get_mut(&record.surface_id) else {
            return false;
        };
        surface.terminal = None;
        surface.embedded_terminal_ready = false;
        surface.embedded_terminal_input.clear();
        surface.embedded_terminal_foreground_pid = None;
        surface.embedded_terminal_needs_confirm_quit = false;
        surface.embedded_terminal_search = None;
        surface.tty = None;
        surface.terminal_command = None;
        surface.terminal_initial_input = None;
        surface.terminal_scrollback_snapshot = None;
        surface.resume_restore_state = Some("hibernated".to_string());
        surface.agent_hibernation = Some(AgentHibernationSurfaceState {
            hibernated_at_ms: now_ms,
            last_activity_ms: record.effective_last_activity_ms,
        });
        surface.present_count = surface.present_count.saturating_add(1);
        surface.snapshot_generation = surface.snapshot_generation.saturating_add(1);
        if let Ok(mut buffer) = surface.buffer.lock() {
            buffer.clear();
            buffer.shrink_to_fit();
        }
        true
    }

    fn resume_agent_hibernated_surface(&mut self, surface_id: &str) -> AppResult<bool> {
        let binding = self
            .surfaces
            .get(surface_id)
            .and_then(|surface| {
                surface
                    .agent_hibernation
                    .as_ref()
                    .and(surface.resume_binding.as_ref())
            })
            .cloned();
        let Some(binding) = binding else {
            return Ok(false);
        };
        let resume_input = format!("{}\r", resume_binding_startup_input(&binding));
        let now_ms = current_unix_millis();
        let terminal_startup_mode = self.terminal_startup_mode;
        let Some(surface) = self.surfaces.get_mut(surface_id) else {
            return Err(AppError::not_found("surface not found"));
        };
        surface.agent_hibernation = None;
        surface.agent_lifecycle.clear();
        surface.terminal = None;
        surface.embedded_terminal_ready = false;
        surface.embedded_terminal_foreground_pid = None;
        surface.embedded_terminal_input.clear();
        surface.terminal_command = None;
        surface.terminal_initial_input = Some(resume_input);
        surface.terminal_scrollback_snapshot = None;
        surface.terminal_cwd = binding.cwd.or_else(|| surface.terminal_cwd.clone());
        surface.terminal_env.extend(binding.environment);
        surface.resume_restore_state = Some("running".to_string());
        surface.agent_hibernation_last_activity_ms = now_ms;
        surface.agent_hibernation_last_input_ms = 0;
        surface.agent_hibernation_last_lifecycle_change_ms = 0;
        surface.agent_hibernation_tail_fingerprint = None;
        surface.agent_hibernation_tail_stable_since_ms = now_ms;
        surface.present_count = surface.present_count.saturating_add(1);
        surface.snapshot_generation = surface.snapshot_generation.saturating_add(1);
        self.agent_hibernation_confirmations.remove(surface_id);
        if terminal_startup_mode == TerminalStartupMode::CorePty {
            self.ensure_surface_terminal_started(surface_id)?;
        }
        if session_snapshot_save_enabled() {
            let _ = self.persist_session_snapshot(true);
        }
        Ok(true)
    }

    fn agent_hibernation_resume(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_surface_resume_target(params)?;
        let resumed = self.resume_agent_hibernated_surface(&surface_id)?;
        if resumed && bool_param(params, "focus").unwrap_or(true) {
            self.focus_surface(&surface_id)?;
        }
        Ok(json!({
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "resumed": resumed
        }))
    }

    fn record_agent_hibernation_activity(
        &mut self,
        surface_id: &str,
        input: bool,
        lifecycle_change: bool,
    ) {
        let now_ms = current_unix_millis();
        if let Some(surface) = self.surfaces.get_mut(surface_id) {
            surface.agent_hibernation_last_activity_ms = now_ms;
            if input {
                surface.agent_hibernation_last_input_ms = now_ms;
            }
            if lifecycle_change {
                surface.agent_hibernation_last_lifecycle_change_ms = now_ms;
            }
        }
        self.agent_hibernation_confirmations.remove(surface_id);
    }

    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn record_embedded_terminal_input(
        &mut self,
        surface_id: &str,
        input: Option<&[u8]>,
    ) {
        self.record_agent_hibernation_activity(surface_id, true, false);
        if let (Some(surface), Some(input)) = (self.surfaces.get_mut(surface_id), input) {
            apply_surface_input_key(surface, input);
        }
    }

    fn refresh_browser_availability(&mut self) {
        self.browser_enabled = browser_settings::load_enabled(&self.browser_settings_path);
    }

    fn browser_availability_status(&mut self) -> Value {
        self.refresh_browser_availability();
        browser_settings::payload(&self.browser_settings_path, self.browser_enabled)
    }

    fn set_browser_enabled(&mut self, enabled: bool) -> AppResult<Value> {
        browser_settings::save_enabled(&self.browser_settings_path, enabled).map_err(|err| {
            AppError::internal(format!("failed to save browser availability: {err}"))
        })?;
        self.browser_enabled = enabled;
        Ok(browser_settings::payload(
            &self.browser_settings_path,
            self.browser_enabled,
        ))
    }

    fn ensure_browser_creation_enabled(&mut self) -> AppResult<()> {
        self.refresh_browser_availability();
        if self.browser_enabled {
            Ok(())
        } else {
            Err(AppError::invalid_state(
                "cmux browser creation and link interception are disabled",
            ))
        }
    }

    fn ensure_surface_spec_allowed(&mut self, spec: &SurfaceSpec) -> AppResult<()> {
        if spec.kind == SurfaceKind::Browser {
            self.ensure_browser_creation_enabled()
        } else {
            Ok(())
        }
    }

    fn ensure_pane_specs_allowed(&mut self, pane_specs: &[PaneSpec]) -> AppResult<()> {
        if pane_specs
            .iter()
            .flat_map(|pane| pane.surfaces.iter())
            .any(|surface| surface.kind == SurfaceKind::Browser)
        {
            self.ensure_browser_creation_enabled()
        } else {
            Ok(())
        }
    }

