                let window = self.current_window()?;
                let fallback = window.workspaces.last().cloned();
                let id = self
                    .last_workspace_by_window
                    .get(&window.id)
                    .filter(|id| {
                        window
                            .workspaces
                            .iter()
                            .any(|workspace_id| workspace_id == *id)
                    })
                    .cloned()
                    .or(fallback)
                    .ok_or_else(|| AppError::not_found("no workspaces"))?;
                self.select_workspace_by_id(&id)?;
                Ok(json!({"workspace_id": id, "workspace_ref": self.workspace_ref(&id)}))
