    fn update_embedded_terminal_pixel_size(
        &mut self,
        surface_selector: &str,
        width_px: u32,
        height_px: u32,
        initial: bool,
    ) -> AppResult<bool> {
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get_mut(&surface_id) else {
            return Ok(false);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(false);
        }

        let next = Some(EmbeddedTerminalPixelSize {
            width_px,
            height_px,
        });
        let current = if initial {
            &mut surface.embedded_terminal_initial_size
        } else {
            &mut surface.embedded_terminal_cell_size
        };
        if *current == next {
            return Ok(false);
        }
        *current = next;
        surface.present_count += 1;
        Ok(true)
    }

