    fn update_embedded_terminal_string_metadata(
        &mut self,
        surface_selector: &str,
        value: &str,
        select: impl FnOnce(&mut Surface) -> &mut Option<String>,
    ) -> AppResult<bool> {
        let value = value.trim();
        if value.is_empty() {
            return Ok(false);
        }
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get_mut(&surface_id) else {
            return Ok(false);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(false);
        }

        {
            let current = select(surface);
            if current.as_deref() == Some(value) {
                return Ok(false);
            }
            *current = Some(value.to_string());
        }
        surface.present_count += 1;
        Ok(true)
    }

