    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn perform_embedded_terminal_window_action(
        &mut self,
        surface_selector: &str,
        action: &str,
        value: Option<&str>,
    ) -> AppResult<Option<Value>> {
        self.record_embedded_terminal_window_action(surface_selector, action, value)?;
        let (_, _, window_id) = self.embedded_terminal_surface_context(surface_selector)?;
        match action {
            "new_window" => self
                .handle("window.create", &json!({"title": "cmux Linux"}))
                .map(Some),
            "close_window" => {
                let result = self.window_close_request(&json!({
                    "window_id": window_id,
                    "source": "ghostty"
                }))?;
                if result.get("blocked").and_then(Value::as_bool) == Some(true) {
                    self.record_embedded_terminal_ui_action(
                        surface_selector,
                        "close_window_requested",
                        Some("needs_confirm"),
                        None,
                    )?;
                }
                Ok(Some(result))
            }
            "goto_window" => self.embedded_terminal_goto_window(&window_id, value),
            _ => Err(AppError::invalid_params(format!(
                "unsupported embedded terminal window action: {action}"
            ))),
        }
    }

    fn window_has_embedded_terminal_close_confirmation(&self, window_id: &str) -> bool {
        let Some(window) = self.windows.iter().find(|window| window.id == window_id) else {
            return false;
        };
        window.workspaces.iter().any(|workspace_id| {
            self.workspace_surface_ids(workspace_id)
                .into_iter()
                .any(|surface_id| self.surface_needs_close_confirmation(&surface_id))
        })
    }

    fn surface_needs_close_confirmation(&self, surface_id: &str) -> bool {
        self.surfaces.get(surface_id).is_some_and(|surface| {
            surface.kind == SurfaceKind::Terminal && surface.embedded_terminal_needs_confirm_quit
        })
    }

    fn embedded_terminal_goto_window(
        &mut self,
        source_window_id: &str,
        value: Option<&str>,
    ) -> AppResult<Option<Value>> {
        let Some(direction) = value else {
            return Ok(None);
        };
        if self.windows.len() <= 1 {
            return Ok(None);
        }
        let Some(index) = self
            .windows
            .iter()
            .position(|window| window.id == source_window_id)
        else {
            return Ok(None);
        };
        let next_index = match direction {
            "previous" => {
                if index == 0 {
                    self.windows.len() - 1
                } else {
                    index - 1
                }
            }
            "next" => (index + 1) % self.windows.len(),
            _ => return Ok(None),
        };
        let window_id = self.windows[next_index].id.clone();
        self.current_window = window_id.clone();
        Ok(Some(json!({
            "window_id": window_id,
            "window_ref": self.window_ref(&self.current_window)
        })))
    }

    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn perform_embedded_terminal_tab_action(
        &mut self,
        surface_selector: &str,
        action: &str,
        amount: Option<i64>,
    ) -> AppResult<Option<Value>> {
        self.record_embedded_terminal_action(surface_selector, action, None, amount, "tab")?;
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get(&surface_id) else {
            return Ok(None);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(None);
        }
        let pane_id = surface.pane_id.clone();
        match action {
            "goto_tab" => self.embedded_terminal_goto_tab(&surface_id, &pane_id, amount),
            "move_tab" => self.embedded_terminal_move_tab(&surface_id, &pane_id, amount),
            _ => Err(AppError::invalid_params(format!(
                "unsupported embedded terminal tab action: {action}"
            ))),
        }
    }

    fn embedded_terminal_goto_tab(
        &mut self,
        surface_id: &str,
        pane_id: &str,
        target: Option<i64>,
    ) -> AppResult<Option<Value>> {
        let Some(target) = target else {
            return Ok(None);
        };
        let Some(pane) = self.panes.get(pane_id) else {
            return Ok(None);
        };
        if pane.surfaces.is_empty() {
            return Ok(None);
        }
        let current_index = pane
            .surfaces
            .iter()
            .position(|id| id == surface_id)
            .unwrap_or(0);
        let target_index = match target {
            -1 => {
                if current_index == 0 {
                    pane.surfaces.len() - 1
                } else {
                    current_index - 1
                }
            }
            -2 => (current_index + 1) % pane.surfaces.len(),
            -3 => pane.surfaces.len() - 1,
            // Ghostty's numeric goto_tab contract is one-indexed. Its native
            // GTK host also clamps an oversized number to the last tab.
            value if value > 0 => (value as usize - 1).min(pane.surfaces.len() - 1),
            _ => return Ok(None),
        };
        let Some(target_surface_id) = pane.surfaces.get(target_index).cloned() else {
            return Ok(None);
        };
        self.focus_surface(&target_surface_id)?;
        Ok(Some(json!({
            "surface_id": target_surface_id,
            "surface_ref": self.surface_ref(&target_surface_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(pane_id)
        })))
    }

    fn embedded_terminal_move_tab(
        &mut self,
        surface_id: &str,
        pane_id: &str,
        amount: Option<i64>,
    ) -> AppResult<Option<Value>> {
        let amount = amount.unwrap_or(0);
        let Some(pane) = self.panes.get_mut(pane_id) else {
            return Ok(None);
        };
        if pane.surfaces.len() <= 1 || amount == 0 {
            return Ok(None);
        }
        let Some(index) = pane.surfaces.iter().position(|id| id == surface_id) else {
            return Ok(None);
        };
        let target_index =
            (index as i64 + amount).clamp(0, pane.surfaces.len().saturating_sub(1) as i64) as usize;
        if target_index == index {
            return Ok(None);
        }
        let surface_id = pane.surfaces.remove(index);
        pane.surfaces.insert(target_index, surface_id.clone());
        pane.selected_surface = Some(surface_id.clone());
        Ok(Some(json!({
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(pane_id),
            "index": target_index
        })))
    }

    fn record_embedded_terminal_action(
        &mut self,
        surface_selector: &str,
        action: &str,
        value: Option<&str>,
        amount: Option<i64>,
        bucket: &str,
    ) -> AppResult<bool> {
        let action = action.trim();
        if action.is_empty() {
            return Ok(false);
        }
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get_mut(&surface_id) else {
            return Ok(false);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(false);
        }
        surface.embedded_terminal_action_sequence =
            surface.embedded_terminal_action_sequence.saturating_add(1);
        let record = Some(EmbeddedTerminalActionRecord {
            sequence: surface.embedded_terminal_action_sequence,
            action: action.to_string(),
            value: value
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string),
            amount,
        });
        match bucket {
            "app" => surface.embedded_terminal_last_app_action = record,
            "window" => surface.embedded_terminal_last_window_action = record,
            "tab" => surface.embedded_terminal_last_tab_action = record,
            "layout" => surface.embedded_terminal_last_layout_action = record,
            "ui" => surface.embedded_terminal_last_ui_action = record,
            _ => return Ok(false),
        }
        surface.present_count += 1;
        Ok(true)
    }

    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn update_embedded_terminal_progress_report(
        &mut self,
        surface_selector: &str,
        state: &str,
        progress: Option<i8>,
    ) -> AppResult<bool> {
        let state = state.trim();
        if state.is_empty() {
            return Ok(false);
        }
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get_mut(&surface_id) else {
            return Ok(false);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(false);
        }

        let next = if state == "remove" {
            None
        } else {
            Some(EmbeddedTerminalProgress {
                state: state.to_string(),
                progress: progress.filter(|value| (0..=100).contains(value)),
            })
        };
        if surface.embedded_terminal_progress == next {
            return Ok(false);
        }
        surface.embedded_terminal_progress = next;
        surface.present_count += 1;
        Ok(true)
    }

    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn start_embedded_terminal_search(
        &mut self,
        surface_selector: &str,
        needle: &str,
    ) -> AppResult<bool> {
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get_mut(&surface_id) else {
            return Ok(false);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(false);
        }

        let next = Some(EmbeddedTerminalSearch {
            needle: needle.to_string(),
            total: None,
            selected: None,
        });
        if surface.embedded_terminal_search == next {
            return Ok(false);
        }
        surface.embedded_terminal_search = next;
        surface.present_count += 1;
        Ok(true)
    }

