    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn record_embedded_terminal_command_finished(
        &mut self,
        surface_selector: &str,
        exit_code: Option<i16>,
        duration_ns: u64,
    ) -> AppResult<bool> {
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get_mut(&surface_id) else {
            return Ok(false);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(false);
        }

        let next = Some(EmbeddedTerminalCommandFinished {
            exit_code,
            duration_ms: duration_ns / 1_000_000,
        });
        let mut changed = false;
        if surface.embedded_terminal_last_command != next {
            surface.embedded_terminal_last_command = next;
            changed = true;
        }
        if surface.shell_activity_state != "promptIdle" {
            surface.shell_activity_state = "promptIdle".to_string();
            changed = true;
        }
        if changed {
            surface.present_count += 1;
        }
        Ok(changed)
    }

