    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn open_embedded_terminal_config(
        &mut self,
        surface_selector: &str,
    ) -> AppResult<Value> {
        self.open_embedded_terminal_config_with_path(surface_selector, None)
    }

    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn open_embedded_terminal_config_with_path(
        &mut self,
        surface_selector: &str,
        ghostty_path: Option<&str>,
    ) -> AppResult<Value> {
        let (surface_id, workspace_id, _) =
            self.embedded_terminal_surface_context(surface_selector)?;
        if let Some(path) = ghostty_path.map(str::trim).filter(|path| !path.is_empty()) {
            return self.handle(
                "file.open",
                &json!({
                    "path": path,
                    "workspace_id": workspace_id,
                    "surface_id": surface_id,
                    "focus": true
                }),
            );
        }

        let snapshot = config::snapshot();
        if snapshot.ghostty.has_backing_file {
            self.handle(
                "file.open",
                &json!({
                    "path": snapshot.ghostty.path,
                    "workspace_id": workspace_id,
                    "surface_id": surface_id,
                    "focus": true
                }),
            )
        } else {
            self.handle(
                "settings.open",
                &json!({
                    "target": "terminal",
                    "workspace_id": workspace_id,
                    "surface_id": surface_id,
                    "focus": true
                }),
            )
        }
    }

