    fn embedded_terminal_surface_context(
        &self,
        surface_selector: &str,
    ) -> AppResult<(String, String, String)> {
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get(&surface_id) else {
            return Err(AppError::not_found("surface not found"));
        };
        if surface.kind != SurfaceKind::Terminal {
            return Err(AppError::not_found("terminal surface not found"));
        }
        let workspace_id = self.surface_workspace_id(&surface_id)?;
        let window_id = self
            .workspaces
            .get(&workspace_id)
            .map(|workspace| workspace.window_id.clone())
            .ok_or_else(|| AppError::not_found("workspace not found"))?;
        Ok((surface_id, workspace_id, window_id))
    }

    #[cfg_attr(not(feature = "gtk"), allow(dead_code))]
    pub(crate) fn perform_embedded_terminal_layout_action(
        &mut self,
        surface_selector: &str,
        action: &str,
        direction: Option<&str>,
        amount: Option<u16>,
    ) -> AppResult<Option<Value>> {
        self.perform_embedded_terminal_layout_action_with_inherited_options(
            surface_selector,
            action,
            direction,
            amount,
            None,
        )
    }

    pub(crate) fn perform_embedded_terminal_layout_action_with_inherited_options(
        &mut self,
        surface_selector: &str,
        action: &str,
        direction: Option<&str>,
        amount: Option<u16>,
        inherited_options: Option<EmbeddedTerminalInheritedOptions>,
    ) -> AppResult<Option<Value>> {
        self.record_embedded_terminal_layout_action(surface_selector, action, direction, amount)?;
        let surface_id = self.resolve_surface(Some(&json!(surface_selector)), None)?;
        let Some(surface) = self.surfaces.get(&surface_id) else {
            return Ok(None);
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(None);
        }
        let pane_id = surface.pane_id.clone();
        let workspace_id = self.surface_workspace_id(&surface_id)?;

        match action {
            "present_terminal" => {
                self.focus_surface(&surface_id)?;
                Ok(Some(json!({
                    "surface_id": surface_id,
                    "surface_ref": self.surface_ref(&surface_id),
                    "workspace_id": workspace_id,
                    "workspace_ref": self.workspace_ref(&workspace_id)
                })))
            }
            "new_tab" => {
                let mut params = json!({
                        "workspace_id": workspace_id,
                        "pane_id": pane_id,
                        "type": "terminal",
                        "focus": true
                });
                Self::apply_embedded_terminal_inherited_options(
                    &mut params,
                    inherited_options.as_ref(),
                );
                self.handle("surface.create", &params).map(Some)
            }
            "new_split" => {
                let direction = direction
                    .and_then(normalize_split_direction)
                    .ok_or_else(|| AppError::invalid_params("new_split requires a direction"))?;
                let mut params = json!({
                        "workspace_id": workspace_id,
                        "surface_id": surface_id,
                        "direction": direction,
                        "type": "terminal",
                        "focus": true
                });
                Self::apply_embedded_terminal_inherited_options(
                    &mut params,
                    inherited_options.as_ref(),
                );
                self.handle("surface.split", &params).map(Some)
            }
            "close_tab" => {
                let mode = direction
                    .and_then(normalize_close_tab_mode)
                    .unwrap_or("this");
                let close_targets = if mode == "this" {
                    Vec::new()
                } else {
                    self.embedded_terminal_close_tab_targets(
                        &workspace_id,
                        &pane_id,
                        &surface_id,
                        mode,
                    )?
                };
                let confirmation_targets = close_targets
                    .iter()
                    .filter(|target_id| self.surface_needs_close_confirmation(target_id))
                    .cloned()
                    .collect::<Vec<_>>();
                if !close_targets.is_empty()
                    && mode != "this"
                    && self.app_workspace_settings.warn_before_closing_tab
                {
                    let window_id = self
                        .workspaces
                        .get(&workspace_id)
                        .map(|workspace| workspace.window_id.clone())
                        .ok_or_else(|| AppError::not_found("workspace not found"))?;
                    let confirmation = self.enqueue_close_confirmation(
                        window_id,
                        !confirmation_targets.is_empty(),
                        CloseConfirmationAction::SurfaceBatch {
                            surface_id: surface_id.clone(),
                            mode: mode.to_string(),
                        },
                    );
                    self.record_embedded_terminal_ui_action(
                        &surface_id,
                        "close_tabs_requested",
                        Some("needs_confirm"),
                        Some(close_targets.len() as i64),
                    )?;
                    return Ok(Some(json!({
                        "blocked": true,
                        "confirmation_required": true,
                        "reason": "needs_confirm",
                        "action": "close_tab",
                        "mode": mode,
                        "target_count": close_targets.len(),
                        "confirmation": confirmation,
                        "targets": confirmation_targets.iter().map(|target_id| json!({
                            "surface_id": target_id,
                            "surface_ref": self.surface_ref(target_id)
                        })).collect::<Vec<_>>()
                    })));
                }
                match mode {
                    "this" => {
                        let mut result = self.handle(
                            "surface.close",
                            &json!({
                                "workspace_id": workspace_id,
                                "surface_id": surface_id,
                                "source": "shortcut"
                            }),
                        )?;
                        if result.get("blocked").and_then(Value::as_bool) == Some(true) {
                            self.record_embedded_terminal_ui_action(
                                &surface_id,
                                "close_tab_requested",
                                Some("needs_confirm"),
                                Some(1),
                            )?;
                            if let Some(object) = result.as_object_mut() {
                                object.insert("mode".to_string(), json!("this"));
                                object.insert("target_count".to_string(), json!(1));
                                object.insert(
                                    "targets".to_string(),
                                    json!([{
                                        "surface_id": surface_id,
                                        "surface_ref": self.surface_ref(&surface_id)
                                    }]),
                                );
                            }
                        }
                        Ok(Some(result))
                    }
                    "other" | "right" => self
                        .handle(
                            "surface.action",
                            &json!({
                                "workspace_id": workspace_id,
                                "surface_id": surface_id,
                                "action": if mode == "other" { "close_others" } else { "close_right" }
                            }),
                        )
                        .map(Some),
                    _ => unreachable!("normalize_close_tab_mode returned an unexpected value"),
                }
            }
            "goto_split" => {
                let direction = direction
                    .and_then(normalize_goto_split_direction)
                    .ok_or_else(|| AppError::invalid_params("goto_split requires a direction"))?;
                let Some(target_pane_id) =
                    self.embedded_terminal_target_pane(&workspace_id, &pane_id, direction)?
                else {
                    return Ok(None);
                };
                self.focus_pane(&target_pane_id)?;
                Ok(Some(json!({
                    "workspace_id": workspace_id,
                    "workspace_ref": self.workspace_ref(&workspace_id),
                    "pane_id": target_pane_id,
                    "pane_ref": self.pane_ref(&target_pane_id)
                })))
            }
            "resize_split" => {
                let direction = direction
                    .and_then(normalize_resize_split_direction)
                    .ok_or_else(|| AppError::invalid_params("resize_split requires a direction"))?;
                self.handle(
                    "pane.resize",
                    &json!({
                        "pane_id": pane_id,
                        "direction": direction,
                        "amount": amount.unwrap_or(80).max(1)
                    }),
                )
                .map(Some)
            }
            "equalize_splits" => self
                .handle(
                    "workspace.equalize_splits",
                    &json!({
                        "workspace_id": workspace_id
                    }),
                )
                .map(Some),
            "toggle_split_zoom" => {
                self.focus_surface(&surface_id)?;
                self.toggle_embedded_terminal_split_zoom(&workspace_id, &pane_id)
                    .map(Some)
            }
            _ => Err(AppError::invalid_params(format!(
                "unsupported embedded terminal layout action: {action}"
            ))),
        }
    }

    fn embedded_terminal_close_tab_targets(
        &self,
        workspace_id: &str,
        pane_id: &str,
        surface_id: &str,
        mode: &str,
    ) -> AppResult<Vec<String>> {
        if mode == "this" {
            return Ok(self
                .surface_needs_close_confirmation(surface_id)
                .then(|| surface_id.to_string())
                .into_iter()
                .collect());
        }

        let pane_surface_ids = self
            .panes
            .get(pane_id)
            .map(|pane| pane.surfaces.clone())
            .ok_or_else(|| AppError::not_found("Tab pane not found"))?;
        let anchor_index = pane_surface_ids
            .iter()
            .position(|id| id == surface_id)
            .ok_or_else(|| AppError::not_found("Tab not found in pane"))?;
        let targets = match mode {
            "right" => pane_surface_ids
                .get(anchor_index + 1..)
                .unwrap_or_default()
                .to_vec(),
            "other" => pane_surface_ids
                .iter()
                .filter(|id| *id != surface_id)
                .cloned()
                .collect(),
            _ => Vec::new(),
        };
        Ok(targets
            .into_iter()
            .filter(|target_id| {
                self.workspace_surface_ids(workspace_id).len() > 1
                    && self
                        .surfaces
                        .get(target_id)
                        .is_some_and(|surface| !surface.pinned)
            })
            .collect())
    }

    fn apply_embedded_terminal_inherited_options(
        params: &mut Value,
        inherited_options: Option<&EmbeddedTerminalInheritedOptions>,
    ) {
        let Some(inherited_options) = inherited_options else {
            return;
        };
        let Some(object) = params.as_object_mut() else {
            return;
        };
        if let Some(working_directory) = inherited_options
            .working_directory
            .as_deref()
            .filter(|value| !value.trim().is_empty())
        {
            object.insert("cwd".to_string(), json!(working_directory));
        }
        if let Some(font_size) = inherited_options
            .font_size
            .filter(|font_size| font_size.is_finite() && *font_size > 0.0)
        {
            object.insert(
                "terminal_font_size".to_string(),
                json!(font_size.clamp(1.0, 255.0)),
            );
        }
    }

    fn toggle_embedded_terminal_split_zoom(
        &mut self,
        workspace_id: &str,
        pane_id: &str,
    ) -> AppResult<Value> {
        let (zoomed, pane_count) = {
            let workspace = self
                .workspaces
                .get_mut(workspace_id)
                .ok_or_else(|| AppError::not_found("workspace not found"))?;
            if !workspace.panes.iter().any(|id| id == pane_id) {
                return Err(AppError::not_found("pane not found"));
            }
            let pane_count = workspace.panes.len();
            let zoomed = if pane_count <= 1 {
                workspace.zoomed_pane = None;
                false
            } else if workspace.zoomed_pane.as_deref() == Some(pane_id) {
                workspace.zoomed_pane = None;
                false
            } else {
                workspace.zoomed_pane = Some(pane_id.to_string());
                true
            };
            (zoomed, pane_count)
        };

        Ok(json!({
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(workspace_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(pane_id),
            "zoomed": zoomed,
            "pane_count": pane_count
        }))
    }

    fn embedded_terminal_target_pane(
        &self,
        workspace_id: &str,
        source_pane_id: &str,
        direction: &str,
    ) -> AppResult<Option<String>> {
        let pane_ids = self
            .workspaces
            .get(workspace_id)
            .map(|workspace| workspace.panes.clone())
            .ok_or_else(|| AppError::not_found("workspace not found"))?;
        if pane_ids.len() <= 1 {
            return Ok(None);
        }
        let current_index = pane_ids
            .iter()
            .position(|pane_id| pane_id == source_pane_id)
            .ok_or_else(|| AppError::not_found("pane not found"))?;
        match direction {
            "previous" => {
                let index = if current_index == 0 {
                    pane_ids.len() - 1
                } else {
                    current_index - 1
                };
                return Ok(pane_ids.get(index).cloned());
            }
            "next" => {
                let index = (current_index + 1) % pane_ids.len();
                return Ok(pane_ids.get(index).cloned());
            }
            _ => {}
        }

        let source = self
            .panes
            .get(source_pane_id)
            .ok_or_else(|| AppError::not_found("pane not found"))?;
        let target = pane_ids
            .iter()
            .filter(|pane_id| pane_id.as_str() != source_pane_id)
            .filter_map(|pane_id| {
                let pane = self.panes.get(pane_id)?;
                let primary = match direction {
                    "right" if pane.col > source.col => pane.col - source.col,
                    "left" if pane.col < source.col => source.col - pane.col,
                    "down" if pane.row > source.row => pane.row - source.row,
                    "up" if pane.row < source.row => source.row - pane.row,
                    _ => return None,
                };
                let secondary = if matches!(direction, "right" | "left") {
                    (pane.row - source.row).abs()
                } else {
                    (pane.col - source.col).abs()
                };
                Some((primary, secondary, pane_id.clone()))
            })
            .min_by_key(|(primary, secondary, _)| (*primary, *secondary))
            .map(|(_, _, pane_id)| pane_id);
        Ok(target)
    }

    fn uses_renderer_owned_terminal_input(&self, surface_id: &str) -> bool {
        self.terminal_startup_mode == TerminalStartupMode::RendererOwned
            && self.surfaces.get(surface_id).is_some_and(|surface| {
                surface.kind == SurfaceKind::Terminal
                    && surface.terminal.is_none()
                    && !surface.remote_session_active
                    && !surface
                        .terminal_env
                        .contains_key(REMOTE_TMUX_CONNECTION_ENV)
            })
    }

    fn is_remote_tmux_surface(&self, surface_id: &str) -> bool {
        self.surfaces.get(surface_id).is_some_and(|surface| {
            surface.kind == SurfaceKind::Terminal
                && surface
                    .terminal_env
                    .contains_key(REMOTE_TMUX_CONNECTION_ENV)
        })
    }

    fn enqueue_renderer_owned_terminal_text(&mut self, surface_id: &str, text: String) -> bool {
        if !self.uses_renderer_owned_terminal_input(surface_id) {
            return false;
        }
        let Some(surface) = self.surfaces.get_mut(surface_id) else {
            return false;
        };
        surface
            .embedded_terminal_input
            .push_back(EmbeddedTerminalInput::Text(text));
        true
    }

    fn enqueue_renderer_owned_terminal_key(
        &mut self,
        surface_id: &str,
        key: &str,
    ) -> AppResult<bool> {
        if !self.uses_renderer_owned_terminal_input(surface_id) {
            return Ok(false);
        }
        let bytes =
            terminal_key_bytes(key).map_err(|err| AppError::invalid_params(err.to_string()))?;
        let trimmed = key.trim();
        if key.trim_start().starts_with("text:") || trimmed.chars().count() == 1 {
            let text = String::from_utf8(bytes)
                .map_err(|err| AppError::invalid_params(format!("unsupported key bytes: {err}")))?;
            return Ok(self.enqueue_renderer_owned_terminal_text(surface_id, text));
        }
        let Some(surface) = self.surfaces.get_mut(surface_id) else {
            return Ok(false);
        };
        surface
            .embedded_terminal_input
            .push_back(EmbeddedTerminalInput::Key(trimmed.to_string()));
        Ok(true)
    }

    fn enqueue_renderer_owned_terminal_binding_action(
        &mut self,
        surface_id: &str,
        action: &str,
    ) -> bool {
        if !self.uses_renderer_owned_terminal_input(surface_id) {
            return false;
        }
        let Some(surface) = self.surfaces.get_mut(surface_id) else {
            return false;
        };
        surface
            .embedded_terminal_input
            .push_back(EmbeddedTerminalInput::BindingAction(action.to_string()));
        true
    }

    fn flush_terminal_title_events(&mut self) -> AppResult<()> {
        let terminals = self
            .surfaces
            .iter()
            .filter_map(|(id, surface)| {
                surface
                    .terminal
                    .clone()
                    .map(|terminal| (id.clone(), terminal))
            })
            .collect::<Vec<_>>();
        for (surface_id, terminal) in terminals {
            for title in terminal.drain_title_events() {
                self.apply_terminal_title(&surface_id, &title)?;
            }
        }
        Ok(())
    }

    fn apply_terminal_title(&mut self, surface_id: &str, title: &str) -> AppResult<bool> {
        let title = title.trim();
        if title.is_empty() {
            return Ok(false);
        }
        let title = title.to_string();
        let workspace_id = self.surface_workspace_id(surface_id)?;
        let workspace_surface_ids = self.workspace_surface_ids(&workspace_id);
        let is_single_surface_workspace =
            workspace_surface_ids.len() == 1 && workspace_surface_ids[0] == surface_id;
        let mut changed = false;

        if let Some(surface) = self.surfaces.get_mut(surface_id) {
            if surface.terminal_title.as_deref() != Some(title.as_str()) {
                surface.terminal_title = Some(title.clone());
            }
            if !surface.custom_title && surface.auto_title.is_none() && surface.title != title {
                surface.title = title.clone();
                surface.present_count += 1;
                changed = true;
            }
        }

        if is_single_surface_workspace {
            if let Some(workspace) = self.workspaces.get_mut(&workspace_id) {
                if workspace.terminal_title.as_deref() != Some(title.as_str()) {
                    workspace.terminal_title = Some(title.clone());
                }
                if !workspace.custom_title
                    && workspace.auto_title.is_none()
                    && workspace.title != title
                {
                    workspace.title = title;
                    changed = true;
                }
            }
        }

        Ok(changed)
    }

    fn ingest_terminal_notification_sequences(
        &mut self,
        surface_id: &str,
        text: &str,
    ) -> AppResult<()> {
        let workspace_id = self.surface_workspace_id(surface_id)?;
        for title in terminal_title_events_from_text(text) {
            self.apply_terminal_title(surface_id, &title)?;
        }
        if let Some((title, body)) = parse_osc777_notification(text) {
            self.create_notification_for_target(
                workspace_id.clone(),
                Some(surface_id.to_string()),
                title,
                String::new(),
                body,
            );
        }

        for event in parse_osc99_events(text) {
            match event {
                Osc99Event::Simple { title } => {
                    self.create_notification_for_target(
                        workspace_id.clone(),
                        Some(surface_id.to_string()),
                        title,
                        String::new(),
                        String::new(),
                    );
                }
                Osc99Event::Title { id, title } => {
                    self.kitty_chunks.entry(id).or_default().title = Some(title);
                }
                Osc99Event::Body { id, body } => {
                    let title = self
                        .kitty_chunks
                        .remove(&id)
                        .and_then(|chunk| chunk.title)
                        .unwrap_or_else(|| "cmux".to_string());
                    self.create_notification_for_target(
                        workspace_id.clone(),
                        Some(surface_id.to_string()),
                        title,
                        String::new(),
                        body,
                    );
                }
            }
        }
        Ok(())
    }

    fn sidebar_agent_lifecycle_set(&mut self, params: &Value) -> AppResult<Value> {
        let workspace_id = self.agent_lifecycle_workspace_id(params)?;
        let key = string_param(params, "key")
            .or_else(|| string_param(params, "agent"))
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .ok_or_else(|| AppError::invalid_params("agent lifecycle key is required"))?;
        let lifecycle_raw = string_param(params, "lifecycle")
            .or_else(|| string_param(params, "state"))
            .or_else(|| string_param(params, "value"))
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .ok_or_else(|| AppError::invalid_params("agent lifecycle value is required"))?;
        let lifecycle = AgentLifecycleState::parse(&lifecycle_raw).ok_or_else(|| {
            AppError::invalid_params(
                "agent lifecycle must be unknown, running, idle, or needsInput",
            )
        })?;
        let surface_id = self.agent_lifecycle_surface_id(params, &workspace_id)?;

        if let Some(surface_id) = &surface_id {
            self.surfaces
                .get_mut(surface_id)
                .ok_or_else(|| AppError::not_found("surface not found"))?
                .agent_lifecycle
                .insert(key.clone(), lifecycle);
            self.record_agent_hibernation_activity(surface_id, false, true);
        }

        if lifecycle == AgentLifecycleState::NeedsInput {
            let title = self.waiting_for_input_notification_title(surface_id.as_deref());
            self.create_notification_for_target(
                workspace_id.clone(),
                surface_id.clone(),
                title,
                String::new(),
                "Agent needs input".to_string(),
            );
        }

        Ok(json!({
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "surface_id": surface_id,
            "surface_ref": surface_id.as_ref().map(|id| self.surface_ref(id)),
            "key": key,
            "lifecycle": lifecycle.as_str()
        }))
    }

    fn agent_lifecycle_workspace_id(&self, params: &Value) -> AppResult<String> {
        self.resolve_workspace_optional(
            params
                .get("workspace_id")
                .or_else(|| params.get("workspace"))
                .or_else(|| params.get("tab_id"))
                .or_else(|| params.get("tab")),
        )?
        .or_else(|| {
            params
                .get("surface_id")
                .or_else(|| params.get("surface"))
                .or_else(|| params.get("panel_id"))
                .or_else(|| params.get("panel"))
                .and_then(|surface| self.resolve_surface(Some(surface), None).ok())
                .and_then(|surface_id| self.surface_workspace_id(&surface_id).ok())
        })
        .map(Ok)
        .unwrap_or_else(|| self.current_workspace_id())
    }

    fn agent_lifecycle_surface_id(
        &self,
        params: &Value,
        workspace_id: &str,
    ) -> AppResult<Option<String>> {
        if let Some(surface) = params
            .get("surface_id")
            .or_else(|| params.get("surface"))
            .or_else(|| params.get("panel_id"))
            .or_else(|| params.get("panel"))
        {
            return self
                .resolve_surface(Some(surface), Some(workspace_id))
                .map(Some);
        }
        Ok(self
            .workspace_selected_surface(workspace_id)
            .or_else(|| self.workspace_surface_ids(workspace_id).into_iter().next()))
    }

    fn waiting_for_input_notification_title(&self, surface_id: Option<&str>) -> String {
        let base = "Waiting for input";
        let Some(surface_id) = surface_id else {
            return base.to_string();
        };
        let Some(surface) = self.surfaces.get(surface_id) else {
            return base.to_string();
        };
        let title = surface.title.trim();
        if surface.custom_title && !title.is_empty() {
            format!("{base}: {title}")
        } else {
            base.to_string()
        }
    }

    fn sidebar_status_set(&mut self, params: &Value) -> AppResult<Value> {
        let workspace_id = self.metadata_workspace_id(params)?;
        let key = string_param(params, "key")
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .ok_or_else(|| AppError::invalid_params("status key is required"))?;
        let value = string_param(params, "value")
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .ok_or_else(|| AppError::invalid_params("status value is required"))?;
        let priority = int_param(params, "priority").unwrap_or(0);
        let icon = string_param(params, "icon");
        let color = string_param(params, "color");
        let url = string_param(params, "url").or_else(|| string_param(params, "link"));
        let format = string_param(params, "format")
            .map(|format| format.trim().to_ascii_lowercase())
            .filter(|format| matches!(format.as_str(), "plain" | "markdown"))
            .unwrap_or_else(|| "plain".to_string());
        let workspace = self
            .workspaces
            .get_mut(&workspace_id)
            .ok_or_else(|| AppError::not_found("workspace not found"))?;
        workspace.status_entries.retain(|entry| entry.key != key);
        workspace.status_entries.push(SidebarStatusEntry {
            key: key.clone(),
            value: value.clone(),
            priority,
            icon,
            color,
            url,
            format: format.clone(),
        });
        Ok(json!({
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "key": key,
            "value": value,
            "priority": priority,
            "format": format
        }))
    }

