    fn project_get_state(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_project_panel_surface(params)?;
        let panel = self
            .project_panels
            .get(&surface_id)
            .ok_or_else(project_panel_not_found)?;
        Ok(project_panel_state_value(&surface_id, panel))
    }

    fn resolve_project_panel_surface(&self, params: &Value) -> AppResult<String> {
        if let Some(surface_value) = params.get("surface_id").filter(|value| !value.is_null()) {
            let surface_id = self
                .resolve_surface_optional(Some(surface_value), None)
                .ok()
                .flatten()
                .ok_or_else(project_panel_not_found)?;
            return self
                .project_panels
                .contains_key(&surface_id)
                .then_some(surface_id)
                .ok_or_else(project_panel_not_found);
        }

        let workspace_id = self
            .resolve_workspace_optional(
                params
                    .get("workspace_id")
                    .or_else(|| params.get("workspace")),
            )?
            .or_else(|| self.current_workspace_id().ok());
        if let Some(workspace_id) = workspace_id.as_deref() {
            if let Some(surface_id) = self
                .workspace_selected_surface(workspace_id)
                .filter(|surface_id| self.project_panels.contains_key(surface_id))
            {
                return Ok(surface_id);
            }
            if let Some(surface_id) = self
                .workspace_surface_ids(workspace_id)
                .into_iter()
                .find(|surface_id| self.project_panels.contains_key(surface_id))
            {
                return Ok(surface_id);
            }
        }

        self.current_surface_id()
            .ok()
            .filter(|surface_id| self.project_panels.contains_key(surface_id))
            .ok_or_else(project_panel_not_found)
    }

    fn configure_document_surface(
        &mut self,
        surface_id: &str,
        document: DocumentState,
        url: &str,
        html: String,
    ) -> AppResult<()> {
        let surface = self
            .surfaces
            .get_mut(surface_id)
            .ok_or_else(|| AppError::not_found("surface not found"))?;
        surface.document = Some(document);
        surface.url = Some(url.to_string());
        surface.browser = BrowserState::from_html(url, html);
        surface.present_count += 1;
        Ok(())
    }

    fn resolve_document_surface(&self, params: &Value) -> AppResult<String> {
        if let Some(value) = params
            .get("surface_id")
            .or_else(|| params.get("surface"))
            .filter(|value| !value.is_null())
        {
            let surface_id = self
                .resolve_surface_optional(Some(value), None)?
                .ok_or_else(document_surface_not_found)?;
            return self
                .surfaces
                .get(&surface_id)
                .is_some_and(|surface| surface.document.is_some())
                .then_some(surface_id)
                .ok_or_else(document_surface_not_found);
        }

        self.current_surface_id()
            .ok()
            .filter(|surface_id| {
                self.surfaces
                    .get(surface_id)
                    .is_some_and(|surface| surface.document.is_some())
            })
            .ok_or_else(document_surface_not_found)
    }

    fn refresh_document_compatibility_html(&mut self, surface_id: &str) -> AppResult<()> {
        let surface = self
            .surfaces
            .get(surface_id)
            .ok_or_else(document_surface_not_found)?;
        let document = surface
            .document
            .clone()
            .ok_or_else(document_surface_not_found)?;
        let title = surface.title.clone();
        let url = surface
            .url
            .clone()
            .unwrap_or_else(|| "about:blank".to_string());
        let html = match document.kind.as_str() {
            "markdown" => render_markdown_document(
                &document.content,
                &title,
                document.path.as_deref().unwrap_or_default(),
                document.font_size,
            ),
            "filePreview" => render_file_document(&title, &document),
            "diff" => diff_viewer::replace_diff_document_layout(
                &surface.browser.html,
                &document.content,
                &document.display_mode,
            )
            .unwrap_or_else(|| surface.browser.html.clone()),
            _ => return Ok(()),
        };
        let surface = self
            .surfaces
            .get_mut(surface_id)
            .ok_or_else(document_surface_not_found)?;
        browser_set_html_content(&mut surface.browser, &url, html);
        surface.present_count += 1;
        Ok(())
    }

    fn document_get_state(&self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_document_surface(params)?;
        let document = self
            .surfaces
            .get(&surface_id)
            .and_then(|surface| surface.document.as_ref())
            .ok_or_else(document_surface_not_found)?;
        Ok(json!({
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "document": document
        }))
    }

    fn document_set_content(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_document_surface(params)?;
        let content = string_param(params, "content")
            .or_else(|| string_param(params, "text"))
            .ok_or_else(|| AppError::invalid_params("document content is required"))?;
        if content.len() as u64 > MAX_NATIVE_DOCUMENT_BYTES {
            return Err(AppError::invalid_params(format!(
                "document content exceeds {} bytes",
                MAX_NATIVE_DOCUMENT_BYTES
            )));
        }
        let document = self
            .surfaces
            .get_mut(&surface_id)
            .and_then(|surface| surface.document.as_mut())
            .ok_or_else(document_surface_not_found)?;
        ensure_editable_document(document)?;
        document.dirty = document.saved_content != content;
        document.content = content;
        self.refresh_document_compatibility_html(&surface_id)?;
        self.document_get_state(&json!({"surface_id": surface_id}))
    }

    fn document_set_mode(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_document_surface(params)?;
        let mode = string_param(params, "mode")
            .ok_or_else(|| AppError::invalid_params("document mode is required"))?;
        let kind = self
            .surfaces
            .get(&surface_id)
            .and_then(|surface| surface.document.as_ref())
            .map(|document| document.kind.clone())
            .ok_or_else(document_surface_not_found)?;
        match kind.as_str() {
            "markdown" if matches!(mode.as_str(), "preview" | "text") => {}
            "diff" if config::DiffViewerLayout::parse(&mode).is_some() => {}
            "markdown" => {
                return Err(AppError::invalid_params(
                    "markdown document mode must be 'preview' or 'text'",
                ));
            }
            "diff" => {
                return Err(AppError::invalid_params(
                    "diff document mode must be 'unified' or 'split'",
                ));
            }
            _ => {
                return Err(AppError::invalid_params(
                    "document does not support display mode changes",
                ));
            }
        }
        self.surfaces
            .get_mut(&surface_id)
            .and_then(|surface| surface.document.as_mut())
            .ok_or_else(document_surface_not_found)?
            .display_mode = mode.clone();
        if kind == "diff" && bool_param(params, "persist").unwrap_or(true) {
            let layout = config::DiffViewerLayout::parse(&mode)
                .expect("validated diff document display mode");
            config::set_diff_viewer_default_layout(layout).map_err(AppError::internal)?;
        }
        self.refresh_document_compatibility_html(&surface_id)?;
        self.document_get_state(&json!({"surface_id": surface_id}))
    }

    fn document_save(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_document_surface(params)?;
        let (path, content) = {
            let document = self
                .surfaces
                .get(&surface_id)
                .and_then(|surface| surface.document.as_ref())
                .ok_or_else(document_surface_not_found)?;
            ensure_editable_document(document)?;
            let content = string_param(params, "content")
                .or_else(|| string_param(params, "text"))
                .unwrap_or_else(|| document.content.clone());
            if content.len() as u64 > MAX_NATIVE_DOCUMENT_BYTES {
                return Err(AppError::invalid_params(format!(
                    "document content exceeds {} bytes",
                    MAX_NATIVE_DOCUMENT_BYTES
                )));
            }
            let path = document
                .path
                .clone()
                .ok_or_else(|| AppError::invalid_state("document has no file path"))?;
            (path, content)
        };
        fs::write(&path, content.as_bytes()).map_err(|err| {
            AppError::permission_denied(format!("failed to save document {path}: {err}"))
        })?;
        if let Some(document) = self
            .surfaces
            .get_mut(&surface_id)
            .and_then(|surface| surface.document.as_mut())
        {
            document.content = content;
            document.saved_content = document.content.clone();
            document.dirty = false;
        }
        self.refresh_document_compatibility_html(&surface_id)?;
        self.document_get_state(&json!({"surface_id": surface_id}))
    }

    fn document_reload(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_document_surface(params)?;
        let current = self
            .surfaces
            .get(&surface_id)
            .and_then(|surface| surface.document.clone())
            .ok_or_else(document_surface_not_found)?;
        ensure_editable_document(&current)?;
        let path_text = current
            .path
            .clone()
            .ok_or_else(|| AppError::invalid_state("document has no file path"))?;
        let path = PathBuf::from(&path_text);
        let mut document = if current.kind == "markdown" {
            let content = fs::read_to_string(&path).map_err(|err| {
                AppError::invalid_state(format!("failed to reload document {path_text}: {err}"))
            })?;
            DocumentState {
                saved_content: content.clone(),
                content,
                dirty: false,
                ..current
            }
        } else {
            file_document_state(&path)?
        };
        document.dirty = false;
        let surface = self
            .surfaces
            .get_mut(&surface_id)
            .ok_or_else(document_surface_not_found)?;
        surface.document = Some(document);
        self.refresh_document_compatibility_html(&surface_id)?;
        self.document_get_state(&json!({"surface_id": surface_id}))
    }

    fn file_open(&mut self, params: &Value) -> AppResult<Value> {
        let raw_paths = file_open_raw_paths(params);
        if raw_paths.is_empty() {
            return Err(AppError::invalid_params(
                "Missing 'path' or 'paths' parameter",
            ));
        }
        let mut file_paths = Vec::new();
        for raw_path in raw_paths {
            file_paths.push(resolve_readable_file_path(&raw_path)?);
        }

        let focus = bool_param(params, "focus").unwrap_or(true);
        let requested_window =
            self.resolve_window_optional(params.get("window_id").or_else(|| params.get("window")))?;
        let workspace_hint = self.resolve_workspace_optional(
            params
                .get("workspace_id")
                .or_else(|| params.get("workspace")),
        )?;
        let workspace_id = workspace_hint
            .or_else(|| {
                requested_window.as_ref().and_then(|window_id| {
                    self.windows
                        .iter()
                        .find(|window| &window.id == window_id)
                        .and_then(|window| window.selected_workspace.clone())
                })
            })
            .unwrap_or(self.current_workspace_id()?);
        let pane_id = if let Some(pane_value) = params
            .get("pane_id")
            .or_else(|| params.get("pane"))
            .filter(|value| !value.is_null())
        {
            let pane_id = self
                .resolve_pane_optional(Some(pane_value), Some(&workspace_id))
                .map_err(|_| AppError::not_found("Pane not found"))?
                .ok_or_else(|| AppError::not_found("Pane not found"))?;
            let pane_matches_workspace = self
                .panes
                .get(&pane_id)
                .is_some_and(|pane| pane.workspace_id == workspace_id);
            if !pane_matches_workspace {
                return Err(AppError::not_found("Pane not found"));
            }
            pane_id
        } else if let Some(surface_value) = params
            .get("surface_id")
            .or_else(|| params.get("surface"))
            .filter(|value| !value.is_null())
        {
            let surface_id = self
                .resolve_surface_optional(Some(surface_value), Some(&workspace_id))
                .map_err(|_| AppError::not_found("Source surface not found"))?
                .ok_or_else(|| AppError::not_found("Source surface not found"))?;
            let surface = self
                .surfaces
                .get(&surface_id)
                .ok_or_else(|| AppError::not_found("Source surface not found"))?;
            let pane = self
                .panes
                .get(&surface.pane_id)
                .ok_or_else(|| AppError::not_found("Pane not found"))?;
            if pane.workspace_id != workspace_id {
                return Err(AppError::not_found("Source surface not found"));
            }
            pane.id.clone()
        } else {
            self.workspaces
                .get(&workspace_id)
                .and_then(|workspace| {
                    workspace
                        .selected_pane
                        .clone()
                        .or_else(|| workspace.panes.first().cloned())
                })
                .ok_or_else(|| AppError::not_found("Pane not found"))?
        };

        let mut surface_payloads = Vec::new();
        for file_path in &file_paths {
            let path = PathBuf::from(file_path);
            let title = path
                .file_name()
                .and_then(|value| value.to_str())
                .filter(|value| !value.is_empty())
                .unwrap_or(file_path)
                .to_string();
            let url = file_url_for_path(file_path);
            let document = file_document_state(&path)?;
            let html = render_file_document(&title, &document);
            let preview_mode = document.display_mode.clone();
            let mut spec = SurfaceSpec::document(SurfaceKind::FilePreview);
            spec.url = Some(url.clone());
            spec.title = Some(title);
            spec.custom_title = true;
            let surface_id = self.create_surface(&workspace_id, &pane_id, spec)?;
            self.configure_document_surface(&surface_id, document, &url, html)?;
            surface_payloads.push(json!({
                "surface_id": surface_id,
                "surface_ref": self.surface_ref(&surface_id),
                "pane_id": pane_id,
                "pane_ref": self.pane_ref(&pane_id),
                "panel_type": "filePreview",
                "path": file_path,
                "preview_mode": preview_mode
            }));
        }
        if surface_payloads.is_empty() {
            return Err(AppError::internal("Failed to open file"));
        }
        let primary = surface_payloads
            .last()
            .cloned()
            .ok_or_else(|| AppError::internal("Failed to open file"))?;
        let primary_surface_id = primary
            .get("surface_id")
            .and_then(Value::as_str)
            .ok_or_else(|| AppError::internal("Failed to open file"))?
            .to_string();
        if focus {
            self.focus_surface(&primary_surface_id)?;
        }
        let window_id = self
            .workspaces
            .get(&workspace_id)
            .map(|workspace| workspace.window_id.clone())
            .ok_or_else(|| AppError::not_found("Workspace not found"))?;
        Ok(json!({
            "window_id": window_id,
            "window_ref": self.window_ref(&window_id),
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(&pane_id),
            "surface_id": primary["surface_id"].clone(),
            "surface_ref": primary["surface_ref"].clone(),
            "panel_type": primary["panel_type"].clone(),
            "path": primary["path"].clone(),
            "paths": file_paths,
            "surfaces": surface_payloads,
            "preview_mode": primary["preview_mode"].clone()
        }))
    }

    fn diff_open(&mut self, params: &Value) -> AppResult<Value> {
        let requested_window =
            self.resolve_window_optional(params.get("window_id").or_else(|| params.get("window")))?;
        let workspace_hint = self.resolve_workspace_optional(
            params
                .get("workspace_id")
                .or_else(|| params.get("workspace")),
        )?;
        let workspace_id = workspace_hint
            .or_else(|| {
                requested_window.as_ref().and_then(|window_id| {
                    self.windows
                        .iter()
                        .find(|window| &window.id == window_id)
                        .and_then(|window| window.selected_workspace.clone())
                })
            })
            .unwrap_or(self.current_workspace_id()?);

        let font_size = float_param(params, "font_size").unwrap_or(10.0);
        if !(8.0..=48.0).contains(&font_size) {
            return Err(AppError::invalid_params(
                "diff font size must be between 8 and 48 points",
            ));
        }
        let layout = match string_param(params, "layout") {
            Some(layout) => config::DiffViewerLayout::parse(&layout).ok_or_else(|| {
                AppError::invalid_params("diff layout must be 'unified' or 'split'")
            })?,
            None => config::diff_viewer_default_layout(),
        };
        let focus = bool_param(params, "focus").unwrap_or(false);
        let source = string_param(params, "source").unwrap_or_else(|| "unstaged".to_string());
        let (diff_text, source_label, repo_path) =
            self.diff_open_source_text(params, &workspace_id, &source)?;
        let title =
            string_param(params, "title").unwrap_or_else(|| format!("Diff - {source_label}"));
        let mut review_comments =
            diff_viewer::review_comments_from_params(params).map_err(AppError::invalid_params)?;
        let explicit_review_comments = !review_comments.is_empty();
        if review_comments.is_empty() {
            if let Some(repo_path) = repo_path.as_deref() {
                review_comments = self.diff_review_comments_for_repo_root(repo_path)?;
            }
        }
        let html = diff_viewer::render_diff_document_with_layout(
            &diff_text,
            &title,
            &source_label,
            font_size,
            &review_comments,
            layout.as_str(),
        );
        let url = format!(
            "data:text/html;charset=utf-8,{}",
            percent_encode_data_url_component(&html)
        );
        let document = DocumentState {
            kind: "diff".to_string(),
            path: repo_path.clone(),
            content: diff_text.clone(),
            display_mode: layout.as_str().to_string(),
            mime_type: "text/x-diff".to_string(),
            font_size,
            source_label: Some(source_label.clone()),
            annotations: review_comments
                .iter()
                .map(|comment| DocumentAnnotation {
                    file_path: comment.file_path.clone(),
                    line: comment.end_line.or(comment.start_line),
                    message: comment.message.clone(),
                    side: comment.side.clone(),
                })
                .collect(),
            dirty: false,
            saved_content: diff_text.clone(),
        };
        let pane_id = self.resolve_pane_optional(
            params.get("pane_id").or_else(|| params.get("pane")),
            Some(&workspace_id),
        )?;

        let mut payload = if let Some(pane_id) = pane_id {
            let mut spec = SurfaceSpec::document(SurfaceKind::Diff);
            spec.url = Some(url.clone());
            spec.title = Some(title.clone());
            spec.custom_title = true;
            let surface_id = self.create_surface(&workspace_id, &pane_id, spec)?;
            self.configure_document_surface(&surface_id, document.clone(), &url, html.clone())?;
            if focus {
                self.focus_surface(&surface_id)?;
            }
            json!({
                "workspace_id": workspace_id,
                "workspace_ref": self.workspace_ref(&workspace_id),
                "pane_id": pane_id,
                "pane_ref": self.pane_ref(&pane_id),
                "target_pane_id": pane_id,
                "target_pane_ref": self.pane_ref(&pane_id),
                "created_split": false,
                "surface_id": surface_id,
                "surface_ref": self.surface_ref(&surface_id)
            })
        } else {
            let mut split_params = Map::new();
            split_params.insert("type".to_string(), json!("diff"));
            split_params.insert("title".to_string(), json!(title.clone()));
            split_params.insert("url".to_string(), json!(url.clone()));
            split_params.insert("workspace_id".to_string(), json!(workspace_id.clone()));
            split_params.insert("focus".to_string(), json!(focus));
            split_params.insert(
                "direction".to_string(),
                json!(string_param(params, "direction").unwrap_or_else(|| "right".to_string())),
            );
            if let Some(surface_id) = self.resolve_surface_optional(
                params.get("surface_id").or_else(|| params.get("surface")),
                Some(&workspace_id),
            )? {
                split_params.insert("surface_id".to_string(), json!(surface_id));
            }
            let payload = self.surface_split(&Value::Object(split_params))?;
            let surface_id = payload
                .get("surface_id")
                .and_then(Value::as_str)
                .ok_or_else(|| AppError::internal("diff surface was not created"))?
                .to_string();
            self.configure_document_surface(&surface_id, document.clone(), &url, html.clone())?;
            payload
        };

        if let Some(object) = payload.as_object_mut() {
            object.insert("url".to_string(), json!(url));
            object.insert("title".to_string(), json!(title));
            object.insert("source".to_string(), json!(source));
            object.insert("source_label".to_string(), json!(source_label));
            object.insert("font_size".to_string(), json!(font_size));
            object.insert("layout".to_string(), json!(layout.as_str()));
            object.insert(
                "review_comment_count".to_string(),
                json!(review_comments.len()),
            );
            object.insert(
                "review_comments_source".to_string(),
                json!(if explicit_review_comments {
                    "request"
                } else if review_comments.is_empty() {
                    "none"
                } else {
                    "store"
                }),
            );
            if let Some(repo_path) = repo_path {
                object.insert("repo_path".to_string(), json!(repo_path));
            }
        }
        Ok(payload)
    }

    fn diff_open_source_text(
        &self,
        params: &Value,
        workspace_id: &str,
        source: &str,
    ) -> AppResult<(String, String, Option<String>)> {
        if let Some(diff_text) =
            string_param(params, "diff").or_else(|| string_param(params, "patch"))
        {
            if diff_text.trim().is_empty() {
                return Err(AppError::invalid_params("diff patch is empty"));
            }
            let label = string_param(params, "source_label").unwrap_or_else(|| "patch".to_string());
            return Ok((diff_text, label, None));
        }
        if let Some(raw_path) =
            string_param(params, "path").or_else(|| string_param(params, "patch_file"))
        {
            let path = PathBuf::from(&raw_path);
            let path = path.canonicalize().unwrap_or(path);
            let text = fs::read_to_string(&path).map_err(|err| {
                AppError::invalid_params(format!(
                    "failed to read diff patch {}: {err}",
                    path.display()
                ))
            })?;
            if text.trim().is_empty() {
                return Err(AppError::invalid_params(format!(
                    "diff patch is empty: {}",
                    path.display()
                )));
            }
            return Ok((text, path.display().to_string(), None));
        }

        let cwd = self.diff_open_cwd(params, workspace_id)?;
        let repo_path = cwd.display().to_string();
        match source {
            "unstaged" => run_app_git_diff(&cwd, &["diff"], "unstaged")
                .map(|(text, label)| (text, label, Some(repo_path))),
            "staged" => run_app_git_diff(&cwd, &["diff", "--staged"], "staged")
                .map(|(text, label)| (text, label, Some(repo_path))),
            "branch" => {
                let base =
                    string_param(params, "base").unwrap_or_else(|| "origin/HEAD".to_string());
                run_app_git_diff(&cwd, &["diff", base.as_str()], &format!("branch {base}"))
                    .map(|(text, label)| (text, label, Some(repo_path)))
            }
            "last-turn" => {
                let surface_id = self
                    .resolve_surface_optional(
                        params.get("surface_id").or_else(|| params.get("surface")),
                        Some(workspace_id),
                    )?
                    .or_else(|| self.workspace_selected_terminal(workspace_id))
                    .ok_or_else(|| {
                        AppError::invalid_params(
                            "diff --last-turn requires a workspace and surface context",
                        )
                    })?;
                let last_turn = diff_baseline::last_turn_diff(
                    &cwd,
                    Some(workspace_id),
                    Some(surface_id.as_str()),
                )
                .map_err(|err| {
                    AppError::invalid_state(format!("diff --last-turn failed: {err}"))
                })?;
                Ok((
                    last_turn.patch,
                    last_turn.source_label,
                    Some(last_turn.repo_root.display().to_string()),
                ))
            }
            other => Err(AppError::invalid_params(format!(
                "unknown diff source: {other}"
            ))),
        }
    }

    fn diff_open_cwd(&self, params: &Value, workspace_id: &str) -> AppResult<PathBuf> {
        let raw_path = string_param(params, "cwd")
            .or_else(|| string_param(params, "repo"))
            .or_else(|| {
                self.workspaces
                    .get(workspace_id)
                    .and_then(|workspace| workspace.cwd.clone())
            });
        let path = if let Some(raw_path) = raw_path {
            PathBuf::from(raw_path)
        } else {
            std::env::current_dir().map_err(|err| {
                AppError::internal(format!("failed to resolve current directory: {err}"))
            })?
        };
        let canonical = path.canonicalize().map_err(|err| {
            AppError::invalid_params(format!(
                "diff cwd does not exist: {}: {err}",
                path.display()
            ))
        })?;
        if !canonical.is_dir() {
            return Err(AppError::invalid_params(format!(
                "diff cwd is not a directory: {}",
                canonical.display()
            )));
        }
        Ok(canonical)
    }

    fn markdown_open(&mut self, params: &Value) -> AppResult<Value> {
        let raw_path = string_param(params, "path")
            .ok_or_else(|| AppError::invalid_params("markdown open path is required"))?;
        let path = PathBuf::from(&raw_path);
        let path = path.canonicalize().unwrap_or(path);
        let metadata = fs::metadata(&path).map_err(|err| {
            AppError::invalid_params(format!(
                "markdown open target does not exist: {raw_path}: {err}"
            ))
        })?;
        if !metadata.is_file() {
            return Err(AppError::invalid_params(format!(
                "markdown open target is not a file: {raw_path}"
            )));
        }
        let source = fs::read_to_string(&path)
            .map_err(|err| AppError::internal(format!("failed to read markdown file: {err}")))?;
        let path_text = path.to_string_lossy().to_string();
        let title = markdown_document_title(&source, &path);
        let font_size = float_param(params, "font_size").unwrap_or(MARKDOWN_DEFAULT_FONT_SIZE);
        if !(MARKDOWN_MIN_FONT_SIZE..=MARKDOWN_MAX_FONT_SIZE).contains(&font_size) {
            return Err(AppError::invalid_params(
                "markdown font size must be between 8 and 96 points",
            ));
        }
        let html = render_markdown_document(&source, &title, &path_text, font_size);
        let url = format!(
            "data:text/html;charset=utf-8,{}",
            percent_encode_data_url_component(&html)
        );
        let document = DocumentState {
            kind: "markdown".to_string(),
            path: Some(path_text.clone()),
            content: source.clone(),
            display_mode: "preview".to_string(),
            mime_type: "text/markdown".to_string(),
            font_size,
            source_label: None,
            annotations: Vec::new(),
            dirty: false,
            saved_content: source,
        };
        let focus = bool_param(params, "focus").unwrap_or(false);

        let requested_window =
            self.resolve_window_optional(params.get("window_id").or_else(|| params.get("window")))?;
        let workspace_hint = self.resolve_workspace_optional(
            params
                .get("workspace_id")
                .or_else(|| params.get("workspace")),
        )?;
        let workspace_id = workspace_hint
            .or_else(|| {
                requested_window.as_ref().and_then(|window_id| {
                    self.windows
                        .iter()
                        .find(|window| &window.id == window_id)
                        .and_then(|window| window.selected_workspace.clone())
                })
            })
            .unwrap_or(self.current_workspace_id()?);
        let pane_id = self.resolve_pane_optional(
            params.get("pane_id").or_else(|| params.get("pane")),
            Some(&workspace_id),
        )?;

        let mut payload = if let Some(pane_id) = pane_id {
            let mut spec = SurfaceSpec::document(SurfaceKind::Markdown);
            spec.url = Some(url.clone());
            spec.title = Some(title.clone());
            spec.custom_title = true;
            let surface_id = self.create_surface(&workspace_id, &pane_id, spec)?;
            self.configure_document_surface(&surface_id, document.clone(), &url, html.clone())?;
            if focus {
                self.focus_surface(&surface_id)?;
            }
            json!({
                "workspace_id": workspace_id,
                "workspace_ref": self.workspace_ref(&workspace_id),
                "pane_id": pane_id,
                "pane_ref": self.pane_ref(&pane_id),
                "target_pane_id": pane_id,
                "target_pane_ref": self.pane_ref(&pane_id),
                "created_split": false,
                "surface_id": surface_id,
                "surface_ref": self.surface_ref(&surface_id)
            })
        } else {
            let mut split_params = Map::new();
            split_params.insert("type".to_string(), json!("markdown"));
            split_params.insert("title".to_string(), json!(title.clone()));
            split_params.insert("url".to_string(), json!(url.clone()));
            split_params.insert("workspace_id".to_string(), json!(workspace_id.clone()));
            split_params.insert("focus".to_string(), json!(focus));
            split_params.insert(
                "direction".to_string(),
                json!(string_param(params, "direction").unwrap_or_else(|| "right".to_string())),
            );
            if let Some(surface_id) = self.resolve_surface_optional(
                params.get("surface_id").or_else(|| params.get("surface")),
                Some(&workspace_id),
            )? {
                split_params.insert("surface_id".to_string(), json!(surface_id));
            }
            let payload = self.surface_split(&Value::Object(split_params))?;
            let surface_id = payload
                .get("surface_id")
                .and_then(Value::as_str)
                .ok_or_else(|| AppError::internal("markdown surface was not created"))?
                .to_string();
            self.configure_document_surface(&surface_id, document.clone(), &url, html.clone())?;
            payload
        };

        if let Some(object) = payload.as_object_mut() {
            object.insert("path".to_string(), json!(path_text));
            object.insert("url".to_string(), json!(url));
            object.insert("title".to_string(), json!(title));
            object.insert("font_size".to_string(), json!(font_size));
        }
        Ok(payload)
    }

    fn browser_new_tab(&mut self, params: &Value) -> AppResult<Value> {
        self.ensure_browser_creation_enabled()?;
        let workspace_id = self
            .resolve_workspace_optional(
                params
                    .get("workspace_id")
                    .or_else(|| params.get("workspace")),
            )?
            .unwrap_or(self.current_workspace_id()?);
        let caller_surface_id = self
            .resolve_surface_optional(
                params.get("surface_id").or_else(|| params.get("surface")),
                Some(&workspace_id),
            )?
            .or_else(|| self.workspace_selected_surface(&workspace_id))
            .ok_or_else(|| AppError::not_found("caller surface not found"))?;
        let pane_id = self
            .surfaces
            .get(&caller_surface_id)
            .map(|surface| surface.pane_id.clone())
            .ok_or_else(|| AppError::not_found("caller surface not found"))?;
        let inherited_profile_id = self.surfaces.get(&caller_surface_id).and_then(|surface| {
            (surface.kind == SurfaceKind::Browser).then(|| surface.browser.profile_id.clone())
        });
        let url = string_param(params, "url").unwrap_or_else(|| "about:blank".to_string());
        let mut spec = SurfaceSpec::browser();
        spec.url = Some(url.clone());
        spec.browser_profile_id = browser_profile_query(params).or(inherited_profile_id);
        let surface_id = self.create_surface(&workspace_id, &pane_id, spec)?;
        self.load_browser_url(&surface_id, &url)?;
        let focus = bool_param(params, "focus").unwrap_or(false);
        if focus {
            self.focus_surface(&surface_id)?;
        }
        let profile_id = self
            .surfaces
            .get(&surface_id)
            .map(|surface| surface.browser.profile_id.clone())
            .unwrap_or_else(default_browser_profile_id);
        let mut result = json!({
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(&pane_id),
            "created_split": false,
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "profile_id": profile_id
        });
        if bool_param(params, "shortcut").unwrap_or(false) {
            result["browser_shortcut_action"] = json!("focus_address_bar");
            result["handled"] = json!(true);
        }
        Ok(result)
    }

    fn browser_open_split(&mut self, params: &Value) -> AppResult<Value> {
        self.ensure_browser_creation_enabled()?;
        let mut spec = SurfaceSpec::browser();
        let url = string_param(params, "url").unwrap_or_else(|| "about:blank".to_string());
        spec.url = Some(url.clone());
        spec.browser_profile_id = browser_profile_query(params);
        let workspace_id = self
            .resolve_workspace_optional(
                params
                    .get("workspace_id")
                    .or_else(|| params.get("workspace")),
            )?
            .unwrap_or(self.current_workspace_id()?);
        let caller_surface_id = self
            .resolve_surface_optional(
                params.get("surface_id").or_else(|| params.get("surface")),
                Some(&workspace_id),
            )?
            .or_else(|| self.workspace_selected_surface(&workspace_id))
            .ok_or_else(|| AppError::not_found("caller surface not found"))?;
        let caller_pane_id = self
            .surfaces
            .get(&caller_surface_id)
            .map(|surface| surface.pane_id.clone())
            .ok_or_else(|| AppError::not_found("caller surface not found"))?;
        let (pane_id, created_split) =
            if let Some(pane_id) = self.nearest_right_pane(&caller_pane_id)? {
                (pane_id, false)
            } else {
                (
                    self.create_split_pane(&workspace_id, &caller_pane_id, "right")?,
                    true,
                )
            };
        let surface_id = self.create_surface(&workspace_id, &pane_id, spec)?;
        if bool_param(params, "focus").unwrap_or(false) {
            self.focus_surface(&surface_id)?;
        }
        self.load_browser_url(&surface_id, &url)?;
        let profile_id = self
            .surfaces
            .get(&surface_id)
            .map(|surface| surface.browser.profile_id.clone())
            .unwrap_or_else(default_browser_profile_id);
        Ok(json!({
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(&pane_id),
            "target_pane_id": pane_id,
            "target_pane_ref": self.pane_ref(&pane_id),
            "created_split": created_split,
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "profile_id": profile_id
        }))
    }

    fn browser_split_shortcut(&mut self, direction: &str) -> AppResult<Value> {
        self.ensure_browser_creation_enabled()?;
        let mut result = self.surface_split(&json!({
            "type": "browser",
            "url": "about:blank",
            "direction": direction,
            "focus": true
        }))?;
        let surface_id = result
            .get("surface_id")
            .and_then(Value::as_str)
            .ok_or_else(|| AppError::internal("browser split was not created"))?
            .to_string();
        self.load_browser_url(&surface_id, "about:blank")?;
        if let Some(object) = result.as_object_mut() {
            object.insert("direction".to_string(), json!(direction));
            object.insert(
                "browser_shortcut_action".to_string(),
                json!("focus_address_bar"),
            );
            object.insert("handled".to_string(), json!(true));
        }
        Ok(result)
    }

    fn browser_window_new(&mut self, params: &Value) -> AppResult<Value> {
        self.ensure_browser_creation_enabled()?;
        let url = string_param(params, "url")
            .or_else(|| positional_arg(params, 0))
            .unwrap_or_else(|| "about:blank".to_string());
        let window_title = string_param(params, "window_title")
            .or_else(|| string_param(params, "title"))
            .unwrap_or_else(|| "cmux Linux".to_string());
        let workspace_title =
            string_param(params, "workspace_title").unwrap_or_else(|| "Browser".to_string());
        let focus = bool_param(params, "focus").unwrap_or(true);
        let window_id = self.create_window_internal(window_title);
        let mut spec = SurfaceSpec::browser();
        spec.url = Some(url.clone());
        spec.browser_profile_id = browser_profile_query(params);
        let workspace_id = self.create_workspace_from_specs(
            &window_id,
            workspace_title,
            None,
            vec![PaneSpec {
                surfaces: vec![spec],
            }],
            focus,
        )?;
        let surface_id = self
            .workspace_surface_ids(&workspace_id)
            .into_iter()
            .find(|surface_id| {
                self.surfaces
                    .get(surface_id)
                    .is_some_and(|surface| surface.kind == SurfaceKind::Browser)
            })
            .ok_or_else(|| AppError::internal("browser surface was not created"))?;
        self.load_browser_url(&surface_id, &url)?;
        let pane_id = self
            .surfaces
            .get(&surface_id)
            .map(|surface| surface.pane_id.clone())
            .ok_or_else(|| AppError::internal("browser surface was not created"))?;
        let profile_id = self
            .surfaces
            .get(&surface_id)
            .map(|surface| surface.browser.profile_id.clone())
            .unwrap_or_else(default_browser_profile_id);
        Ok(json!({
            "window_id": window_id,
            "window_ref": self.window_ref(&window_id),
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "pane_id": pane_id,
            "pane_ref": self.pane_ref(&pane_id),
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "profile_id": profile_id,
            "url": url,
            "created_window": true,
            "created_split": false,
            "focused": focus
        }))
    }

    fn browser_connect(&mut self, params: &Value) -> AppResult<Value> {
        let explicit_surface = params.get("surface_id").or_else(|| params.get("surface"));
        let requested_url = string_param(params, "url").or_else(|| positional_arg(params, 0));
        let create_allowed = bool_param(params, "create").unwrap_or(true);
        let mut created = false;
        let surface_id = if explicit_surface.is_some() {
            self.resolve_browser_surface(params)?
        } else if create_allowed && requested_url.is_some() {
            let mut open_params = Map::new();
            open_params.insert("url".to_string(), json!(requested_url.unwrap()));
            open_params.insert(
                "focus".to_string(),
                json!(bool_param(params, "focus").unwrap_or(false)),
            );
            if let Some(workspace) = params
                .get("workspace_id")
                .or_else(|| params.get("workspace"))
            {
                open_params.insert("workspace_id".to_string(), workspace.clone());
            }
            if let Some(profile) = browser_profile_query(params) {
                open_params.insert("profile_id".to_string(), json!(profile));
            }
            let opened = self.browser_open_split(&Value::Object(open_params))?;
            created = true;
            opened
                .get("surface_id")
                .and_then(Value::as_str)
                .ok_or_else(|| AppError::internal("browser surface was not created"))?
                .to_string()
        } else if let Some(surface_id) = self.current_or_first_browser_surface_id() {
            surface_id
        } else if create_allowed {
            let mut open_params = Map::new();
            open_params.insert("url".to_string(), json!("about:blank"));
            open_params.insert(
                "focus".to_string(),
                json!(bool_param(params, "focus").unwrap_or(false)),
            );
            if let Some(workspace) = params
                .get("workspace_id")
                .or_else(|| params.get("workspace"))
            {
                open_params.insert("workspace_id".to_string(), workspace.clone());
            }
            if let Some(profile) = browser_profile_query(params) {
                open_params.insert("profile_id".to_string(), json!(profile));
            }
            let opened = self.browser_open_split(&Value::Object(open_params))?;
            created = true;
            opened
                .get("surface_id")
                .and_then(Value::as_str)
                .ok_or_else(|| AppError::internal("browser surface was not created"))?
                .to_string()
        } else {
            return Err(AppError::not_found("browser surface not found"));
        };
        let workspace_id = self.surface_workspace_id(&surface_id)?;
        let surface = self
            .surfaces
            .get(&surface_id)
            .ok_or_else(|| AppError::not_found("surface not found"))?;
        let surface_url = surface.url.clone().unwrap_or_default();
        let browser_title = surface.browser.title.clone();
        let mut payload = self.browser_action_payload(&workspace_id, &surface_id)?;
        let browser_status = self.browser_availability_status();
        if let Some(object) = payload.as_object_mut() {
            object.insert("connected".to_string(), json!(true));
            object.insert("created".to_string(), json!(created));
            object.insert("url".to_string(), json!(surface_url));
            object.insert("title".to_string(), json!(browser_title));
            object.insert("browser".to_string(), browser_status);
        }
        Ok(payload)
    }

    fn current_or_first_browser_surface_id(&self) -> Option<String> {
        self.current_surface_id()
            .ok()
            .filter(|surface_id| {
                self.surfaces
                    .get(surface_id)
                    .is_some_and(|surface| surface.kind == SurfaceKind::Browser)
            })
            .or_else(|| {
                self.current_workspace_id().ok().and_then(|workspace_id| {
                    self.workspace_surface_ids(&workspace_id)
                        .into_iter()
                        .find(|surface_id| {
                            self.surfaces
                                .get(surface_id)
                                .is_some_and(|surface| surface.kind == SurfaceKind::Browser)
                        })
                })
            })
            .or_else(|| {
                self.surfaces
                    .values()
                    .find(|surface| surface.kind == SurfaceKind::Browser)
                    .map(|surface| surface.id.clone())
            })
    }

    fn browser_navigate(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_surface(
            params.get("surface_id").or_else(|| params.get("surface")),
            None,
        )?;
        let url = string_param(params, "url")
            .ok_or_else(|| AppError::invalid_params("url is required"))?;
        let surface = self
            .surfaces
            .get_mut(&surface_id)
            .ok_or_else(|| AppError::not_found("surface not found"))?;
        if surface.kind != SurfaceKind::Browser {
            return Err(AppError::invalid_params("surface is not a browser"));
        }
        let _ = surface;
        self.load_browser_url(&surface_id, &url)?;
        let surface = self
            .surfaces
            .get(&surface_id)
            .ok_or_else(|| AppError::not_found("surface not found"))?;
        Ok(browser_post_action_snapshot(params, &surface.browser))
    }

    fn browser_runtime_sync(&mut self, params: &Value) -> AppResult<Value> {
        let surface_id = self.resolve_browser_surface(params)?;
        let requested_title =
            string_param(params, "title").filter(|title| !title.trim().is_empty());
        let webview_focused = bool_param(params, "webview_focused");
        let cookies = params
            .get("cookies")
            .map(browser_runtime_cookies_from_value)
            .transpose()?;
        if let Some(focused) = webview_focused {
            let is_active_surface = self
                .current_surface_id()
                .is_ok_and(|current| current == surface_id);
            if !focused || is_active_surface {
                self.set_browser_webview_focus(&surface_id, focused);
            }
        }
        let surface = self
            .surfaces
            .get_mut(&surface_id)
            .ok_or_else(|| AppError::not_found("surface not found"))?;
        if let Some(title) = requested_title.as_ref() {
            surface.browser.title = title.clone();
            if !surface.custom_title {
                surface.title = title.clone();
            }
        }
        if let Some(cookies) = cookies {
            surface.browser.cookies = cookies;
        }
        surface.present_count = surface.present_count.saturating_add(1);
        let url = surface.url.clone();
        let title = surface.browser.title.clone();
        let cookies = surface.browser.cookies.len();
        let profile_id = surface.browser.profile_id.clone();
        let profile_cookies = surface.browser.cookies.clone();
        let surface_ref = self.surface_ref(&surface_id);
        if let Some(profile) = self.browser_profiles.get_mut(&profile_id) {
            profile.cookies = profile_cookies.clone();
        }
        for candidate in self.surfaces.values_mut().filter(|candidate| {
            candidate.id != surface_id
                && candidate.kind == SurfaceKind::Browser
                && candidate
                    .browser
                    .profile_id
                    .eq_ignore_ascii_case(&profile_id)
        }) {
            candidate.browser.cookies = profile_cookies.clone();
        }
        if let (Some(url), Some(requested_title)) = (url.as_deref(), requested_title.as_deref()) {
            self.update_browser_history_title(&profile_id, url, requested_title);
        }
        Ok(json!({
            "surface_id": surface_id,
            "surface_ref": surface_ref,
            "url": url,
            "title": title,
            "profile_id": profile_id,
            "cookie_count": cookies
        }))
    }

