                let key = selector_key(&selector);
                let entry = surface.browser.values.entry(key).or_default();
                if method == "browser.type" {
                    entry.push_str(&text);
                } else {
                    *entry = text;
                }
                Ok(browser_post_action_snapshot(params, &surface.browser))
