    fn execute_numbered_shortcut(&mut self, name: &str, digit: u8) -> AppResult<Value> {
        match name {
            "select_surface_by_number" => {
                let pane_id = self.current_pane_id()?;
                let surfaces = self
                    .panes
                    .get(&pane_id)
                    .map(|pane| pane.surfaces.clone())
                    .ok_or_else(|| AppError::not_found("pane not found"))?;
                let target = numbered_shortcut_target(&surfaces, digit).cloned();
                if let Some(surface_id) = target.as_ref() {
                    self.focus_surface(surface_id)?;
                }
                Ok(json!({
                    "handled": true,
                    "action": "selectSurfaceByNumber",
                    "digit": digit,
                    "pane_id": pane_id,
                    "pane_ref": self.pane_ref(&pane_id),
                    "surface_id": target,
                    "surface_ref": target.as_ref().map(|id| self.surface_ref(id)),
                    "selected": target.is_some()
                }))
            }
            "select_workspace_by_number" => {
                let window_id = self.current_window.clone();
                let workspaces = self
                    .windows
                    .iter()
                    .find(|window| window.id == window_id)
                    .map(|window| window.workspaces.clone())
                    .ok_or_else(|| AppError::not_found("window not found"))?;
                let target = numbered_shortcut_target(&workspaces, digit).cloned();
                if let Some(workspace_id) = target.as_ref() {
                    self.select_workspace_by_id(workspace_id)?;
                }
                Ok(json!({
                    "handled": true,
                    "action": "selectWorkspaceByNumber",
                    "digit": digit,
                    "window_id": window_id,
                    "window_ref": self.window_ref(&window_id),
                    "workspace_id": target,
                    "workspace_ref": target.as_ref().map(|id| self.workspace_ref(id)),
                    "selected": target.is_some()
                }))
            }
            _ => Err(AppError::invalid_params("Unknown numbered shortcut action")),
        }
    }

    fn execute_browser_shortcut(
        &mut self,
        action: &str,
        method: Option<&str>,
        mut params: Value,
    ) -> AppResult<Value> {
        let mut surface_id = self.current_surface_id()?;
        let browser_focused = self
            .surfaces
            .get(&surface_id)
            .is_some_and(|surface| surface.kind == SurfaceKind::Browser);
        let mut opened = None;
        if !browser_focused && action == "focus_address_bar" {
            let result = self.command_palette_execute_command("palette.openBrowser")?;
            surface_id = result
                .get("surface_id")
                .and_then(Value::as_str)
                .ok_or_else(|| AppError::not_found("browser surface not found"))?
                .to_string();
            opened = Some(result);
        } else if !browser_focused {
            return Ok(json!({"handled": false, "reason": "browser_not_focused"}));
        }
        params["surface_id"] = json!(surface_id);
        let mut result = if let Some(result) = opened {
            result
        } else if let Some(method) = method {
            self.browser_handle(method, &params)?
        } else {
            let workspace_id = self.surface_workspace_id(&surface_id)?;
            self.browser_action_payload(&workspace_id, &surface_id)?
        };
        if !result.is_object() {
            result = json!({});
        }
        let object = result.as_object_mut().expect("browser shortcut object");
        object.insert("handled".to_string(), json!(true));
        object.insert("surface_id".to_string(), json!(surface_id));
        object.insert(
            "surface_ref".to_string(),
            json!(self.surface_ref(&surface_id)),
        );
        object.insert("browser_shortcut_action".to_string(), json!(action));
        Ok(result)
    }

    fn toggle_react_grab_shortcut(&mut self) -> AppResult<Value> {
        let workspace_id = self.current_workspace_id()?;
        let focused_surface_id = self.current_surface_id()?;
        let focused_kind = self
            .surfaces
            .get(&focused_surface_id)
            .map(|surface| surface.kind);
        let (browser_surface_id, return_terminal_surface_id) = match focused_kind {
            Some(SurfaceKind::Browser) => (focused_surface_id, None),
            Some(SurfaceKind::Terminal) => {
                let browser_surfaces = self
                    .workspace_surface_ids(&workspace_id)
                    .into_iter()
                    .filter(|surface_id| {
                        self.surfaces
                            .get(surface_id)
                            .is_some_and(|surface| surface.kind == SurfaceKind::Browser)
                    })
                    .collect::<Vec<_>>();
                let [browser_surface_id] = browser_surfaces.as_slice() else {
                    return Ok(json!({
                        "handled": false,
                        "reason": "react_grab_route_unavailable"
                    }));
                };
                (browser_surface_id.clone(), Some(focused_surface_id))
            }
            _ => {
                return Ok(json!({
                    "handled": false,
                    "reason": "react_grab_route_unavailable"
                }));
            }
        };

        self.focus_surface(&browser_surface_id)?;
        let mut result = self.browser_react_grab_toggle(&json!({
            "workspace_id": workspace_id,
            "surface_id": browser_surface_id
        }))?;
        let return_terminal_surface_ref = return_terminal_surface_id
            .as_ref()
            .map(|surface_id| self.surface_ref(surface_id));
        let object = result
            .as_object_mut()
            .ok_or_else(|| AppError::internal("React Grab shortcut returned invalid payload"))?;
        object.insert("handled".to_string(), json!(true));
        object.insert(
            "browser_shortcut_action".to_string(),
            json!("toggle_react_grab"),
        );
        object.insert(
            "return_terminal_surface_id".to_string(),
            json!(return_terminal_surface_id),
        );
        object.insert(
            "return_terminal_surface_ref".to_string(),
            json!(return_terminal_surface_ref),
        );
        Ok(result)
    }

    fn toggle_terminal_copy_mode_shortcut(&mut self) -> AppResult<Value> {
        let surface_id = self.current_surface_id()?;
        let Some(surface) = self.surfaces.get_mut(&surface_id) else {
            return Ok(json!({"handled": false, "reason": "surface_not_found"}));
        };
        if surface.kind != SurfaceKind::Terminal {
            return Ok(json!({
                "handled": false,
                "reason": "terminal_not_focused",
                "action": "toggleTerminalCopyMode"
            }));
        }
        surface.embedded_terminal_copy_mode_active = !surface.embedded_terminal_copy_mode_active;
        surface.present_count += 1;
        let active = surface.embedded_terminal_copy_mode_active;
        Ok(json!({
            "handled": true,
            "action": "toggleTerminalCopyMode",
            "terminal_shortcut_action": "toggle_copy_mode",
            "terminal_copy_mode_active": active,
            "copy_mode_active": active,
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id)
        }))
    }

    fn reopen_previous_session_shortcut(&mut self) -> AppResult<Value> {
        let Some(snapshot) = self.reopen_session_snapshot.clone() else {
            return Ok(json!({
                "handled": true,
                "restored": false,
                "reason": "previous_launch_unavailable",
                "action": "reopenPreviousSession"
            }));
        };
        let existing_window_ids = self
            .windows
            .iter()
            .map(|window| window.id.clone())
            .collect::<HashSet<_>>();
        let saved_at = snapshot.saved_at;
        self.append_session_snapshot(snapshot)?;
        let restored_window_ids = self
            .windows
            .iter()
            .filter(|window| !existing_window_ids.contains(&window.id))
            .map(|window| window.id.clone())
            .collect::<Vec<_>>();
        let Some(primary_window_id) = restored_window_ids.first().cloned() else {
            return Err(AppError::internal(
                "previous launch restore created no windows",
            ));
        };
        self.current_window = primary_window_id.clone();
        let restored_window_refs = restored_window_ids
            .iter()
            .map(|window_id| self.window_ref(window_id))
            .collect::<Vec<_>>();
        Ok(json!({
            "handled": true,
            "restored": true,
            "source": "previous_app_launch",
            "action": "reopenPreviousSession",
            "session_shortcut_action": "reopen_previous_session",
            "saved_at": saved_at,
            "window_count": restored_window_ids.len(),
            "window_ids": restored_window_ids,
            "window_refs": restored_window_refs,
            "window_id": primary_window_id,
            "window_ref": self.window_ref(&primary_window_id)
        }))
    }

    fn set_persisted_shortcut(&mut self, params: &Value) -> AppResult<Value> {
        let name = string_param(params, "name")
            .map(|name| name.trim().to_ascii_lowercase())
            .filter(|name| !name.is_empty())
            .ok_or_else(|| AppError::invalid_params("Missing shortcut name"))?;
        let config_id = shortcut_config_id(&name)
            .ok_or_else(|| AppError::invalid_params("Shortcut is not configurable in cmux.json"))?;
        let previous = self.shortcut_overrides.clone();
        let mut result = self.set_shortcut(params)?;
        let mode = result
            .get("mode")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let update = match mode {
            "custom" => config::ShortcutBindingUpdate::Set(
                self.shortcut_strokes(&name)
                    .ok_or_else(|| AppError::internal("custom shortcut was not retained"))?,
            ),
            "unbound" => config::ShortcutBindingUpdate::Unbind,
            "default" => config::ShortcutBindingUpdate::Reset,
            _ => return Err(AppError::internal("unknown shortcut update mode")),
        };
        let path = match config::set_shortcut_binding(config_id, update) {
            Ok(path) => path,
            Err(error) => {
                self.shortcut_overrides = previous;
                return Err(AppError::internal(error));
            }
        };
        self.shortcut_overrides = configured_shortcut_overrides();
        self.shortcut_when_overrides = configured_shortcut_when_overrides();
        self.config_reload_generation = self.config_reload_generation.saturating_add(1);
        if let Some(object) = result.as_object_mut() {
            object.insert("persisted".to_string(), json!(true));
            object.insert("config_id".to_string(), json!(config_id));
            object.insert("path".to_string(), json!(path));
            object.insert(
                "config_reload_generation".to_string(),
                json!(self.config_reload_generation),
            );
        }
        Ok(result)
    }

    fn shortcut_hint(&self, name: &str) -> String {
        let hint = self
            .shortcut_strokes(name)
            .map(|strokes| {
                strokes
                    .iter()
                    .map(|stroke| shortcut_hint_from_combo(stroke))
                    .collect::<Vec<_>>()
                    .join(" ")
            })
            .unwrap_or_default();
        numbered_shortcut_display(name, hint)
    }

    fn shortcut_label(&self, name: &str) -> String {
        let label = self
            .shortcut_strokes(name)
            .map(|strokes| {
                strokes
                    .iter()
                    .map(|stroke| linux_shortcut_label_from_hint(&shortcut_hint_from_combo(stroke)))
                    .collect::<Vec<_>>()
                    .join(" ")
            })
            .unwrap_or_default();
        numbered_shortcut_display(name, label)
    }

    fn shortcut_strokes(&self, name: &str) -> Option<Vec<String>> {
        match self.shortcut_overrides.get(name) {
            Some(config::ShortcutBinding::Single(combo)) => {
                Some(vec![normalize_shortcut_combo(combo)])
            }
            Some(config::ShortcutBinding::Chord(first, second)) => Some(vec![
                normalize_shortcut_combo(first),
                normalize_shortcut_combo(second),
            ]),
            Some(config::ShortcutBinding::Unbound) => None,
            None => default_shortcut_combo(name)
                .and_then(|combo| normalize_shortcut_strokes_for(name, combo)),
        }
    }

    fn effective_shortcut_combo(&self, name: &str) -> Option<String> {
        self.shortcut_strokes(name)
            .filter(|strokes| strokes.len() == 1)
            .and_then(|strokes| strokes.into_iter().next())
    }

    fn shortcut_matches(&self, name: &str, normalized_combo: &str) -> bool {
        self.effective_shortcut_combo(name).as_deref() == Some(normalized_combo)
    }

    fn shortcut_uses_default(&self, name: &str) -> bool {
        !self.shortcut_overrides.contains_key(name)
    }

    fn browser_load_state_for_url(
        &self,
        workspace_id: Option<&str>,
        url: &str,
        offline_enabled: bool,
        routes: &[BrowserNetworkRoute],
    ) -> BrowserLoadResult {
        if offline_enabled && is_browser_network_url(url) {
            return BrowserLoadResult {
                state: BrowserState::from_html(
                    url,
                    format!(
                        "<!doctype html><title>{url}</title><body>Offline emulation blocked network request</body>"
                    ),
                ),
                status: None,
                error: Some("offline".to_string()),
                route_id: None,
            };
        }

        if let Some(route) = matching_browser_network_route(routes, url) {
            if route.abort {
                return BrowserLoadResult {
                    state: BrowserState::from_html(
                        url,
                        format!(
                            "<!doctype html><title>{url}</title><body>Request aborted by browser.network.route</body>"
                        ),
                    ),
                    status: None,
                    error: Some("aborted".to_string()),
                    route_id: Some(route.id),
                };
            }
            if let Some(body) = &route.body {
                return BrowserLoadResult {
                    state: BrowserState::from_html(url, body.clone()),
                    status: Some(200),
                    error: None,
                    route_id: Some(route.id),
                };
            }
        }

        if let Some((html, favicon_png_base64, favicon_url)) =
            workspace_id.and_then(|workspace_id| self.remote_browser_payload(workspace_id, url))
        {
            let mut state = BrowserState::from_html(url, html);
            state.favicon_png_base64 = favicon_png_base64;
            state.favicon_url = favicon_url;
            BrowserLoadResult {
                state,
                status: Some(200),
                error: None,
                route_id: None,
            }
        } else {
            BrowserLoadResult {
                state: BrowserState::from_url(url),
                status: Some(200),
                error: None,
                route_id: None,
            }
        }
    }

