        let import_dialog_scope = surface.browser.import_dialog_scope.clone();
        let import_dialog_destination_profile_id =
            surface.browser.import_dialog_destination_profile_id.clone();
        let extra_headers = surface.browser.extra_headers.clone();
        let credentials = surface.browser.credentials.clone();
