        let surface = self
            .surfaces
            .get_mut(surface_id)
            .ok_or_else(|| AppError::not_found("surface not found"))?;
        surface.url = Some(url.to_string());
        if !history.is_empty() {
            let current_index = history_index.min(history.len() - 1);
            let mut next_history = history;
            if next_history
                .get(current_index)
                .is_some_and(|current| browser_navigation_urls_equal(current, url))
            {
                next_history[current_index] = url.to_string();
                browser.history = next_history;
                browser.history_index = current_index;
            } else {
                next_history.truncate(current_index + 1);
                next_history.push(url.to_string());
                browser.history_index = next_history.len() - 1;
                browser.history = next_history;
            }
        }
        browser.cookies = cookies;
        browser.local_storage = local_storage;
        browser.session_storage = session_storage;
        browser.storage_generation = storage_generation;
        browser.init_marker = init_marker;
