    fn layout_debug(&self) -> AppResult<Value> {
        let workspace_id = self.current_workspace_id()?;
        let workspace = self
            .workspaces
            .get(&workspace_id)
            .ok_or_else(|| AppError::not_found("workspace not found"))?;
        let panes = self.pane_rows(Some(&workspace_id))?;
        let container_debug_frame = debug_container_frame();
        let container_frame = container_debug_frame.to_value();
        let frames = self.workspace_debug_frames(&workspace_id)?;
        let zoomed_pane = self.workspace_zoomed_pane(workspace);
        let selected = workspace
            .panes
            .iter()
            .enumerate()
            .filter_map(|(index, pane_id)| {
                let pane = self.panes.get(pane_id)?;
                let surface_id = pane.selected_surface.as_ref()?;
                let surface = self.surfaces.get(surface_id)?;
                let is_zoomed = zoomed_pane == Some(pane_id.as_str());
                let hidden = zoomed_pane.is_some() && !is_zoomed;
                let frame = if is_zoomed {
                    container_debug_frame
                } else {
                    frames
                        .get(pane_id)
                        .copied()
                        .unwrap_or_else(|| debug_pane_frame(index, workspace.panes.len()))
                };
                let frame_value = frame.to_value();
                Some(json!({
                    "paneId": pane.id,
                    "paneRef": self.pane_ref(&pane.id),
                    "pane_id": pane.id,
                    "pane_ref": self.pane_ref(&pane.id),
                    "paneFrame": frame_value.clone(),
                    "panelId": surface.id,
                    "panelRef": self.surface_ref(&surface.id),
                    "surfaceId": surface.id,
                    "surfaceRef": self.surface_ref(&surface.id),
                    "surface_id": surface.id,
                    "surface_ref": self.surface_ref(&surface.id),
                    "viewFrame": frame_value,
                    "inWindow": true,
                    "hidden": hidden,
                    "zoomed": is_zoomed,
                    "type": surface.kind.as_str(),
                    "splitViews": [
                        {"frame": container_frame.clone(), "role": "container"},
                        {"frame": frame.to_value(), "role": "pane"}
                    ]
                }))
            })
            .collect::<Vec<_>>();
        Ok(json!({
            "layout": {
                "containerFrame": container_frame.clone(),
                "container_frame": container_frame,
                "panes": panes,
                "zoomed_pane_id": zoomed_pane,
                "zoomed_pane_ref": zoomed_pane.map(|id| self.pane_ref(id))
            },
            "selectedPanels": selected
        }))
    }

    fn toggle_sidebar_current_window(&mut self) -> AppResult<Value> {
        let window_id = self.current_window.clone();
        let next = !self
            .sidebar_visible_by_window
            .get(&window_id)
            .copied()
            .unwrap_or(true);
        self.sidebar_visible_by_window
            .insert(window_id.clone(), next);
        Ok(json!({"window_id": window_id, "visible": next}))
    }

