    fn claude_warm_pool_status(&mut self, params: &Value) -> AppResult<Value> {
        self.prune_claude_warm_pool();
        let target_size = claude_warm_pool_target_size(params);
        Ok(json!({
            "provider": "claude",
            "target_size": target_size,
            "available": self.claude_warm_pool_workspaces.len(),
            "workspaces": self.claude_warm_pool_rows()
        }))
    }

    fn claude_warm_pool_ensure(&mut self, params: &Value) -> AppResult<Value> {
        let target_size = claude_warm_pool_target_size(params);
        self.ensure_claude_warm_pool(target_size)?;
        Ok(json!({
            "provider": "claude",
            "target_size": target_size,
            "available": self.claude_warm_pool_workspaces.len(),
            "workspaces": self.claude_warm_pool_rows()
        }))
    }

    fn claude_warm_pool_claim(&mut self, params: &Value) -> AppResult<Value> {
        let target_size = claude_warm_pool_target_size(params).max(1);
        self.ensure_claude_warm_pool(target_size)?;
        let workspace_id = self
            .claude_warm_pool_workspaces
            .first()
            .cloned()
            .ok_or_else(|| AppError::internal("Claude Code warm pool is empty"))?;
        self.claude_warm_pool_workspaces.remove(0);
        self.select_workspace_by_id(&workspace_id)?;
        let surface_id = self
            .workspace_selected_surface(&workspace_id)
            .ok_or_else(|| AppError::not_found("warm Claude Code surface not found"))?;
        self.ensure_claude_warm_pool(target_size)?;
        Ok(json!({
            "provider": "claude",
            "claimed": true,
            "workspace_id": workspace_id,
            "workspace_ref": self.workspace_ref(&workspace_id),
            "surface_id": surface_id,
            "surface_ref": self.surface_ref(&surface_id),
            "available": self.claude_warm_pool_workspaces.len(),
            "workspaces": self.claude_warm_pool_rows()
        }))
    }

    fn ensure_claude_warm_pool(&mut self, target_size: usize) -> AppResult<()> {
        self.prune_claude_warm_pool();
        let target_size = target_size.min(MAX_CLAUDE_WARM_POOL_SIZE);
        while self.claude_warm_pool_workspaces.len() < target_size {
            let (workspace_id, _) = self.create_claude_warm_workspace()?;
            self.claude_warm_pool_workspaces.push(workspace_id);
        }
        Ok(())
    }

    fn prune_claude_warm_pool(&mut self) {
        let workspaces = &self.workspaces;
        let panes = &self.panes;
        let surfaces = &self.surfaces;
        self.claude_warm_pool_workspaces.retain(|workspace_id| {
            workspaces.get(workspace_id).is_some_and(|workspace| {
                workspace.panes.iter().any(|pane_id| {
                    panes.get(pane_id).is_some_and(|pane| {
                        pane.surfaces.iter().any(|surface_id| {
                            surfaces.get(surface_id).is_some_and(|surface| {
                                surface.kind == SurfaceKind::Terminal
                                    && surface
                                        .terminal_env
                                        .get("CMUX_AGENT_PROVIDER")
                                        .is_some_and(|value| value == "claude")
                                    && surface
                                        .terminal_env
                                        .get("CMUX_CLAUDE_WARM_POOL")
                                        .is_some_and(|value| value == "1")
                            })
                        })
                    })
                })
            })
        });
    }

    fn create_claude_warm_workspace(&mut self) -> AppResult<(String, String)> {
        let mut surface = SurfaceSpec::terminal();
        surface.title = Some("Claude Code".to_string());
        surface.custom_title = true;
        surface.command = Some(claude_warm_pool_command());
        surface
            .env
            .insert("CMUX_AGENT_PROVIDER".to_string(), "claude".to_string());
        surface
            .env
            .insert("CMUX_CLAUDE_WARM_POOL".to_string(), "1".to_string());
        let window_id = self.current_window.clone();
        let workspace_id = self.create_workspace_from_specs(
            &window_id,
            "Claude Code".to_string(),
            None,
            vec![PaneSpec {
                surfaces: vec![surface],
            }],
            false,
        )?;
        if let Some(workspace) = self.workspaces.get_mut(&workspace_id) {
            workspace.custom_title = true;
        }
        let surface_id = self
            .workspace_selected_surface(&workspace_id)
            .ok_or_else(|| AppError::internal("failed to create Claude Code warm surface"))?;
        Ok((workspace_id, surface_id))
    }

    fn claude_warm_pool_rows(&self) -> Vec<Value> {
        self.claude_warm_pool_workspaces
            .iter()
            .filter_map(|workspace_id| {
                let workspace = self.workspaces.get(workspace_id)?;
                let surface_id = self.workspace_selected_surface(workspace_id)?;
                let surface = self.surfaces.get(&surface_id)?;
                Some(json!({
                    "workspace_id": workspace.id,
                    "workspace_ref": self.workspace_ref(&workspace.id),
                    "surface_id": surface.id,
                    "surface_ref": self.surface_ref(&surface.id),
                    "title": workspace.title,
                    "provider": "claude",
                    "command": surface.terminal_command.clone(),
                    "runtime_surface_ready": surface_runtime_ready(surface),
                    "selected": self.workspace_is_selected_in_window(&workspace.id)
                }))
            })
            .collect()
    }

    fn shortcut_help_state(&self, params: &Value) -> AppResult<Value> {
        let window_id = self
            .resolve_window_optional(params.get("window_id").or_else(|| params.get("window")))?
            .unwrap_or_else(|| self.current_window.clone());
        Ok(self.shortcut_help_value(&window_id))
    }

    fn shortcut_help_toggle(&mut self, params: &Value) -> AppResult<Value> {
        let window_id = self
            .resolve_window_optional(params.get("window_id").or_else(|| params.get("window")))?
            .unwrap_or_else(|| self.current_window.clone());
        let visible = params
            .get("visible")
            .and_then(|_| bool_param(params, "visible"))
            .unwrap_or_else(|| {
                !self
                    .shortcut_help_visible_by_window
                    .get(&window_id)
                    .copied()
                    .unwrap_or(false)
            });
        self.shortcut_help_visible_by_window
            .insert(window_id.clone(), visible);
        Ok(self.shortcut_help_value(&window_id))
    }

    fn shortcut_help_value(&self, window_id: &str) -> Value {
        json!({
            "window_id": window_id,
            "visible": self
                .shortcut_help_visible_by_window
                .get(window_id)
                .copied()
                .unwrap_or(false),
            "title": "Keyboard Shortcuts",
            "rows": self.shortcut_help_rows()
        })
    }

    fn shortcut_help_rows(&self) -> Vec<Value> {
        self.shortcut_rows(false)
    }

    fn shortcut_settings_rows(&self) -> Vec<Value> {
        self.shortcut_rows(true)
            .into_iter()
            .filter(|row| row["configurable"] == true)
            .collect()
    }

