fn browser_import_settings_from_host(params: &Value) -> AppResult<BrowserHostSettingsImport> {
    let browser_query = browser_first_string_param(params, &["browser", "from", "source"]);
    let requested_profiles =
        browser_string_list_param(params, &["source_profile", "source_profiles", "profile"]);
    let all_profiles = bool_param(params, "all_profiles").unwrap_or(false);
    let stores = browser_host_settings_stores(browser_query.as_deref());
    if stores.is_empty() {
        return Err(AppError::not_supported(
            browser_host_settings_store_missing_message(browser_query.as_deref()),
        ));
    }
    let selected = browser_select_host_settings_stores(stores, &requested_profiles, all_profiles)?;
    let mut settings = Vec::new();
    let mut source_profiles = Vec::new();
    let mut warnings = Vec::new();
    let mut browser_names = Vec::new();
    for store in selected {
        browser_names.push(store.browser_name.to_string());
        source_profiles.push(store.profile_name.clone());
        match browser_read_host_settings_store(&store) {
            Ok(imported) => {
                if imported == BrowserProfileImportedSettings::default() {
                    warnings.push(format!(
                        "{} profile '{}' did not expose portable browser settings",
                        store.browser_name, store.profile_name
                    ));
                } else {
                    settings.push(imported);
                }
            }
            Err(err) => warnings.push(format!(
                "{} profile '{}' settings could not be read: {}",
                store.browser_name, store.profile_name, err.message
            )),
        }
    }
    browser_names.sort();
    browser_names.dedup();
    source_profiles.sort();
    source_profiles.dedup();
    warnings.sort();
    warnings.dedup();
    Ok(BrowserHostSettingsImport {
        browser_name: browser_query.unwrap_or_else(|| browser_names.join(", ")),
        source_profiles,
        settings,
        warnings,
    })
}

fn browser_host_cookie_store_missing_message(browser_query: Option<&str>) -> String {
    if let Some(browser) = browser_query {
        format!("No supported Linux cookie store was found for {browser}")
    } else {
        "No supported Linux browser cookie stores were found".to_string()
    }
}

