fn browser_host_cookie_stores(browser_query: Option<&str>) -> Vec<BrowserCookieStore> {
    let mut stores = Vec::new();
    if browser_query_allows(browser_query, &["firefox", "mozilla"]) {
        stores.extend(browser_firefox_cookie_stores());
    }
    if browser_query_allows(browser_query, &["chrome", "googlechrome", "google"]) {
        stores.extend(browser_chromium_cookie_stores("Chrome", "google-chrome"));
    }
    if browser_query_allows(browser_query, &["chromium"]) {
        stores.extend(browser_chromium_cookie_stores("Chromium", "chromium"));
    }
    if browser_query_allows(browser_query, &["edge", "microsoftedge", "msedge"]) {
        stores.extend(browser_chromium_cookie_stores(
            "Microsoft Edge",
            "microsoft-edge",
        ));
    }
    if browser_query_allows(browser_query, &["brave", "bravebrowser"]) {
        stores.extend(browser_chromium_cookie_stores(
            "Brave",
            "BraveSoftware/Brave-Browser",
        ));
    }
    stores.sort_by(|lhs, rhs| {
        lhs.browser_name
            .cmp(rhs.browser_name)
            .then_with(|| lhs.profile_name.cmp(&rhs.profile_name))
            .then_with(|| lhs.path.cmp(&rhs.path))
    });
    stores.dedup_by(|lhs, rhs| lhs.path == rhs.path);
    stores
}

