fn browser_query_allows(browser_query: Option<&str>, aliases: &[&str]) -> bool {
    let Some(query) = browser_query else {
        return true;
    };
    let normalized = normalize_browser_source_name(query);
    aliases
        .iter()
        .map(|alias| normalize_browser_source_name(alias))
        .any(|alias| normalized == alias || normalized.contains(&alias))
}

fn normalize_browser_source_name(value: &str) -> String {
    value
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn browser_chromium_cookie_stores(
    browser_name: &'static str,
    config_subdir: &str,
) -> Vec<BrowserCookieStore> {
    let Some(config_home) = browser_xdg_config_home() else {
        return Vec::new();
    };
    let root = config_home.join(config_subdir);
    let Ok(entries) = fs::read_dir(root) else {
        return Vec::new();
    };
    let mut stores = Vec::new();
    for entry in entries.flatten() {
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if !file_type.is_dir() {
            continue;
        }
        let profile_name = entry.file_name().to_string_lossy().to_string();
        let profile = entry.path();
        for path in [profile.join("Network/Cookies"), profile.join("Cookies")] {
            if path.is_file() {
                stores.push(BrowserCookieStore {
                    browser_name,
                    profile_name,
                    path,
                    kind: BrowserCookieStoreKind::Chromium,
                });
                break;
            }
        }
    }
    stores
}

fn browser_chromium_history_stores(
    browser_name: &'static str,
    config_subdir: &str,
) -> Vec<BrowserHistoryStoreFile> {
    let Some(config_home) = browser_xdg_config_home() else {
        return Vec::new();
    };
    let root = config_home.join(config_subdir);
    let Ok(entries) = fs::read_dir(root) else {
        return Vec::new();
    };
    entries
        .flatten()
        .filter_map(|entry| {
            entry
                .file_type()
                .ok()
                .filter(|file_type| file_type.is_dir())?;
            let path = entry.path().join("History");
            path.is_file().then(|| BrowserHistoryStoreFile {
                browser_name,
                profile_name: entry.file_name().to_string_lossy().to_string(),
                path,
                kind: BrowserHistoryStoreKind::Chromium,
            })
        })
        .collect()
}

