fn browser_xdg_config_home() -> Option<PathBuf> {
    if let Some(path) = normalized_env("XDG_CONFIG_HOME") {
        return Some(PathBuf::from(path));
    }
    normalized_env("HOME").map(|home| PathBuf::from(home).join(".config"))
}

fn browser_select_host_cookie_stores(
    stores: Vec<BrowserCookieStore>,
    requested_profiles: &[String],
    all_profiles: bool,
) -> AppResult<Vec<BrowserCookieStore>> {
    if !requested_profiles.is_empty() {
        let selected = stores
            .into_iter()
            .filter(|store| {
                requested_profiles
                    .iter()
                    .any(|profile| browser_cookie_store_profile_matches(store, profile))
            })
            .collect::<Vec<_>>();
        if selected.is_empty() {
            return Err(AppError::not_found(format!(
                "No Linux browser cookie profile matched {}",
                requested_profiles.join(", ")
            )));
        }
        return Ok(selected);
    }

    if all_profiles {
        return Ok(stores);
    }

    let mut selected = stores
        .iter()
        .filter(|store| browser_cookie_store_is_default_profile(store))
        .cloned()
        .collect::<Vec<_>>();
    if selected.is_empty() {
        if let Some(first) = stores.first() {
            selected.push(first.clone());
        }
    }
    Ok(selected)
}

fn browser_select_host_history_stores(
    stores: Vec<BrowserHistoryStoreFile>,
    requested_profiles: &[String],
    all_profiles: bool,
) -> AppResult<Vec<BrowserHistoryStoreFile>> {
    if !requested_profiles.is_empty() {
        let selected = stores
            .into_iter()
            .filter(|store| {
                requested_profiles.iter().any(|profile| {
                    let query = normalize_browser_source_name(profile);
                    let profile_name = normalize_browser_source_name(&store.profile_name);
                    let qualified = normalize_browser_source_name(&format!(
                        "{} {}",
                        store.browser_name, store.profile_name
                    ));
                    query == profile_name || query == qualified || qualified.contains(&query)
                })
            })
            .collect::<Vec<_>>();
        if selected.is_empty() {
            return Err(AppError::not_found(format!(
                "No Linux browser history profile matched {}",
                requested_profiles.join(", ")
            )));
        }
        return Ok(selected);
    }
    if all_profiles {
        return Ok(stores);
    }
    let mut selected = stores
        .iter()
        .filter(|store| {
            let profile = store.profile_name.to_ascii_lowercase();
            match store.kind {
                BrowserHistoryStoreKind::Chromium => profile == "default",
                BrowserHistoryStoreKind::Firefox => profile.contains("default"),
            }
        })
        .cloned()
        .collect::<Vec<_>>();
    if selected.is_empty() {
        if let Some(first) = stores.first() {
            selected.push(first.clone());
        }
    }
    Ok(selected)
}

