fn percent_decode(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' && index + 2 < bytes.len() {
            if let Ok(hex) = std::str::from_utf8(&bytes[index + 1..index + 3]) {
                if let Ok(byte) = u8::from_str_radix(hex, 16) {
                    out.push(byte);
                    index += 3;
                    continue;
                }
            }
        }
        out.push(if bytes[index] == b'+' {
            b' '
        } else {
            bytes[index]
        });
        index += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

fn normalize_dropped_file_path(value: &str) -> String {
    let trimmed = value.trim();
    if let Some(path) = trimmed.strip_prefix("file://localhost/") {
        return format!("/{}", percent_decode(path));
    }
    if let Some(path) = trimmed.strip_prefix("file://") {
        return percent_decode(path);
    }
    trimmed.to_string()
}

fn extract_between(text: &str, start: &str, end: &str) -> Option<String> {
    let start_index = text.find(start)? + start.len();
    let end_index = text[start_index..].find(end)? + start_index;
    Some(strip_tags(&text[start_index..end_index]).trim().to_string())
}

fn extract_ids(html: &str) -> Vec<String> {
    let mut ids = Vec::new();
    for marker in ["id='", "id=\""] {
        let quote = if marker.ends_with('\'') { '\'' } else { '"' };
        let mut rest = html;
        while let Some(index) = rest.find(marker) {
            let value_start = index + marker.len();
            let value_rest = &rest[value_start..];
            if let Some(end) = value_rest.find(quote) {
                ids.push(value_rest[..end].to_string());
                rest = &value_rest[end + 1..];
            } else {
                break;
            }
        }
    }
    ids
}

fn strip_tags(html: &str) -> String {
    let mut out = String::new();
    let mut in_tag = false;
    for ch in html.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => {
                in_tag = false;
                out.push(' ');
            }
            _ if !in_tag => out.push(ch),
            _ => {}
        }
    }
    out.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn parse_layout(value: &Value) -> AppResult<Vec<PaneSpec>> {
    if let Some(pane) = value.get("pane") {
        let surfaces = pane
            .get("surfaces")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                AppError::invalid_params("Invalid layout: pane.surfaces must be an array")
            })?;
        if surfaces.is_empty() {
            return Err(AppError::invalid_params(
                "Invalid layout: pane requires at least one surface",
            ));
        }
        return Ok(vec![PaneSpec {
            surfaces: surfaces.iter().map(surface_spec_from_value).collect(),
        }]);
    }

    if value.get("direction").is_some() {
        let children = value
            .get("children")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                AppError::invalid_params("Invalid layout: split children must be an array")
            })?;
        if children.len() < 2 {
            return Err(AppError::invalid_params(
                "Invalid layout: split requires at least two children",
            ));
        }
        let mut panes = Vec::new();
        for child in children {
            panes.extend(parse_layout(child)?);
        }
        return Ok(panes);
    }

    Err(AppError::invalid_params(
        "Invalid layout: expected pane or split",
    ))
}

fn surface_spec_from_value(value: &Value) -> SurfaceSpec {
    let kind = SurfaceKind::from_value(value.get("type"));
    let title = string_param(value, "name").or_else(|| string_param(value, "title"));
    let custom_title = title.is_some();
    SurfaceSpec {
        kind,
        title,
        custom_title,
        url: string_param(value, "url"),
        browser_profile_id: browser_profile_query(value),
        cwd: string_param(value, "cwd")
            .or_else(|| string_param(value, "working_directory"))
            .or_else(|| string_param(value, "current_directory"))
            .and_then(non_empty_trimmed),
        command: string_param(value, "command"),
        initial_input: initial_input_param(value),
        font_size: terminal_font_size_param(value),
        wait_after_command: terminal_wait_after_command_param(value),
        env: terminal_surface_env_param(value),
        remote_session_active: bool_param(value, "remote_session_active").unwrap_or(false),
        ssh_session_id: string_param(value, "ssh_session_id"),
    }
}

fn terminal_font_size_param(value: &Value) -> Option<f32> {
    ["terminal_font_size", "font_size"]
        .into_iter()
        .find_map(|key| float_param(value, key))
        .filter(|font_size| font_size.is_finite() && *font_size > 0.0)
        .map(|font_size| font_size.clamp(1.0, 255.0) as f32)
}

fn terminal_wait_after_command_param(value: &Value) -> bool {
    [
        "terminal_wait_after_command",
        "wait_after_command",
        "waitAfterCommand",
    ]
    .into_iter()
    .find_map(|key| bool_param(value, key))
    .unwrap_or(false)
}

fn initial_input_param(value: &Value) -> Option<String> {
    [
        "initial_input",
        "terminal_initial_input",
        "initial_terminal_input",
    ]
    .into_iter()
    .find_map(|key| string_param(value, key).filter(|input| !input.is_empty()))
}

fn open_target_kind_from_string(raw: &str) -> String {
    if is_cmux_url(raw) {
        "cmux".to_string()
    } else if raw.contains("://") || raw.starts_with("about:") {
        "url".to_string()
    } else if fs::metadata(raw).is_ok_and(|metadata| metadata.is_dir()) {
        "directory".to_string()
    } else {
        "file".to_string()
    }
}

enum CmuxUrlRoute {
    Settings { target: Option<String> },
    AuthCallback,
}

fn cmux_url_route(url: &str) -> Option<CmuxUrlRoute> {
    let parsed = Url::parse(url).ok()?;
    if !parsed.scheme().eq_ignore_ascii_case("cmux") {
        return None;
    }
    let head = parsed.host_str().unwrap_or_default();
    let mut parts = parsed.path_segments().into_iter().flatten();
    if head.eq_ignore_ascii_case("auth-callback") {
        return parsed
            .path()
            .trim_matches('/')
            .is_empty()
            .then_some(CmuxUrlRoute::AuthCallback);
    }
    if !head.eq_ignore_ascii_case("settings") {
        return None;
    }
    let path_target = match parts.next() {
        Some(segment) => cmux_settings_target_from_segment(segment)?,
        None => None,
    };
    if parts.next().is_some() {
        return None;
    }
    let query_target = match parsed
        .query_pairs()
        .find(|(name, _)| name == "target")
        .map(|(_, value)| value.into_owned())
    {
        Some(segment) => cmux_settings_target_from_segment(&segment)?,
        None => None,
    };
    Some(CmuxUrlRoute::Settings {
        target: path_target.or(query_target),
    })
}

fn cmux_settings_target_from_segment(raw: &str) -> Option<Option<String>> {
    let normalized = raw.trim().to_ascii_lowercase().replace('_', "-");
    let target = match normalized.as_str() {
        "" | "general" | "app" => None,
        "account" => Some("account".to_string()),
        "terminal" => Some("terminal".to_string()),
        "sidebar" | "sidebar-appearance" => Some("sidebarAppearance".to_string()),
        "custom-sidebars" | "custom-sidebar" => Some("customSidebars".to_string()),
        "automation" => Some("automation".to_string()),
        "browser" => Some("browser".to_string()),
        "browser-import" => Some("browserImport".to_string()),
        "global-hotkey" => Some("globalHotkey".to_string()),
        "keyboard" | "keyboard-shortcuts" | "shortcuts" => Some("keyboardShortcuts".to_string()),
        "workspace-colors" => Some("workspaceColors".to_string()),
        "cmux-json" | "settings-json" | "json" => Some("settingsJSON".to_string()),
        "reset" => Some("reset".to_string()),
        _ => return None,
    };
    Some(target)
}

fn is_cmux_url(value: &str) -> bool {
    value
        .get(..7)
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("cmux://"))
}

fn is_auth_callback_url(value: &str) -> bool {
    matches!(cmux_url_route(value), Some(CmuxUrlRoute::AuthCallback))
}

fn optional_custom_sidebar_name(params: &Value) -> AppResult<Option<String>> {
    let Some(name) = string_param(params, "name") else {
        return Ok(None);
    };
    let name = name.trim().to_string();
    if name.is_empty() {
        return Err(AppError::invalid_params("Sidebar name must not be empty."));
    }
    if !custom_sidebar::valid_name(&name) {
        return Err(AppError::invalid_params("Sidebar name is invalid."));
    }
    Ok(Some(name))
}

fn custom_sidebar_report(directory: &Path, name: Option<&str>) -> Value {
    let entries = custom_sidebar::validate(directory, name);
    let valid_count = entries.iter().filter(|entry| entry.ok).count();
    json!({
        "directory": directory.display().to_string(),
        "valid_count": valid_count,
        "error_count": entries.len().saturating_sub(valid_count),
        "sidebars": entries
    })
}

fn collect_custom_sidebar_change_event_ids(
    node: &custom_sidebar::SidebarNode,
    key: &str,
    output: &mut Vec<String>,
) {
    output.extend(
        node.on_change
            .iter()
            .filter(|event| event.key.as_deref() == Some(key))
            .map(|event| event.id.clone()),
    );
    for child in &node.children {
        collect_custom_sidebar_change_event_ids(child, key, output);
    }
}

fn find_custom_sidebar_event<'a>(
    node: &'a custom_sidebar::SidebarNode,
    kind: &str,
    id: &str,
) -> Option<&'a custom_sidebar::SidebarEvent> {
    let events = if kind == "submit" {
        &node.on_submit
    } else {
        &node.on_change
    };
    events.iter().find(|event| event.id == id).or_else(|| {
        node.children
            .iter()
            .find_map(|child| find_custom_sidebar_event(child, kind, id))
    })
}

fn add_custom_sidebar_state_values(current: &Value, operand: &Value) -> AppResult<Value> {
    if let (Some(current), Some(operand)) = (current.as_i64(), operand.as_i64()) {
        return current
            .checked_add(operand)
            .map(|value| json!(value))
            .ok_or_else(|| AppError::invalid_params("custom sidebar integer state overflowed"));
    }
    if let (Some(current), Some(operand)) = (current.as_f64(), operand.as_f64()) {
        let value = current + operand;
        if value.is_finite() {
            return Ok(json!(value));
        }
        return Err(AppError::invalid_params(
            "custom sidebar numeric state must remain finite",
        ));
    }
    if let (Some(current), Some(operand)) = (current.as_str(), operand.as_str()) {
        return Ok(json!(format!("{current}{operand}")));
    }
    Err(AppError::invalid_params(
        "custom sidebar state add requires matching numbers or strings",
    ))
}

fn append_custom_sidebar_state_value(current: &Value, operand: &Value) -> AppResult<Value> {
    if let Some(values) = current.as_array() {
        let mut values = values.clone();
        values.push(operand.clone());
        return Ok(Value::Array(values));
    }
    if let (Some(current), Some(operand)) = (current.as_str(), operand.as_str()) {
        return Ok(json!(format!("{current}{operand}")));
    }
    Err(AppError::invalid_params(
        "custom sidebar state append requires an array or string",
    ))
}

fn append_sidebar_extension_provider(snapshot: &mut Value) {
    let status = crate::sidebar_extension::status_value();
    let installed = status
        .get("extensions")
        .and_then(Value::as_array)
        .is_some_and(|extensions| {
            extensions
                .iter()
                .any(|extension| extension.get("ok").and_then(Value::as_bool) == Some(true))
        });
    let selected_name = crate::sidebar_extension::selected_descriptor()
        .map(|descriptor| descriptor.manifest.display_name)
        .unwrap_or_else(|| "Extension Sidebar".to_string());
    let provider = json!({
        "id": crate::sidebar_extension::HOSTED_PROVIDER_ID,
        "title": selected_name,
        "subtitle": "Sidebar extension",
        "kind": "extension",
        "path": crate::sidebar_extension::extensions_dir().display().to_string(),
        "ok": installed,
        "error": if installed {
            Value::Null
        } else {
            json!("No valid sidebar extension is installed.")
        }
    });
    if let Some(providers) = snapshot.get_mut("providers").and_then(Value::as_array_mut) {
        if !providers.iter().any(|existing| {
            existing.get("id").and_then(Value::as_str)
                == Some(crate::sidebar_extension::HOSTED_PROVIDER_ID)
        }) {
            providers.push(provider);
        }
    } else {
        snapshot["providers"] = json!([provider]);
    }
}

fn extension_bool_param(value: &Value, key: &str) -> Option<bool> {
    value.get(key).and_then(|value| {
        value.as_bool().or_else(|| {
            value.as_str().and_then(|value| match value.trim() {
                "true" | "1" | "yes" | "on" => Some(true),
                "false" | "0" | "no" | "off" => Some(false),
                _ => None,
            })
        })
    })
}

