fn env_map_from_value(value: Option<&Value>) -> HashMap<String, String> {
    let mut env = HashMap::new();
    if let Some(obj) = value.and_then(Value::as_object) {
        for (key, value) in obj {
            if let Some(value) = value_to_string(value) {
                env.insert(key.clone(), value);
            }
        }
    }
    env
}

fn env_map_from_keys(value: &Value, keys: &[&str]) -> HashMap<String, String> {
    let mut env = HashMap::new();
    for key in keys {
        env.extend(env_map_from_value(value.get(*key)));
    }
    env
}

fn terminal_surface_env_param(value: &Value) -> HashMap<String, String> {
    env_map_from_keys(
        value,
        &["env", "initial_env", "surface_env", "terminal_env"],
    )
}

fn explicit_terminal_surface_env_param(value: &Value) -> HashMap<String, String> {
    env_map_from_keys(value, &["initial_env", "surface_env", "terminal_env"])
}

fn terminal_env_value(env: &HashMap<String, String>) -> Value {
    let mut result = Map::new();
    let mut keys = env.keys().collect::<Vec<_>>();
    keys.sort();
    for key in keys {
        let Some(value) = env.get(key) else {
            continue;
        };
        if key.is_empty() || key.contains('\0') || key.contains('=') || value.contains('\0') {
            continue;
        }
        result.insert(key.clone(), json!(value));
    }
    Value::Object(result)
}

fn insert_local_socket_terminal_env_if_missing(
    local_socket_path: Option<&str>,
    env: &mut HashMap<String, String>,
) {
    if env.contains_key("CMUX_SOCKET_PATH") || env.contains_key("CMUX_SOCKET") {
        return;
    }
    if let Some(socket_path) = local_socket_path {
        env.insert("CMUX_SOCKET_PATH".to_string(), socket_path.to_string());
    }
}

fn refresh_restored_local_socket_terminal_env(
    local_socket_path: &str,
    env: &mut HashMap<String, String>,
) {
    match env.get("CMUX_SOCKET_PATH").map(String::as_str) {
        Some(socket_path) if is_remote_socket_path(socket_path) => {}
        Some(_) => {
            env.insert(
                "CMUX_SOCKET_PATH".to_string(),
                local_socket_path.to_string(),
            );
        }
        None if !env.contains_key("CMUX_SOCKET") => {
            env.insert(
                "CMUX_SOCKET_PATH".to_string(),
                local_socket_path.to_string(),
            );
        }
        None => {}
    }
}

