fn cleanup_browser_webkit_profile_storage(profiles: &HashMap<String, BrowserProfileState>) {
    let generations = profiles
        .values()
        .map(|profile| (profile.id.to_ascii_lowercase(), profile.data_generation))
        .collect::<HashMap<_, _>>();
    for root in [
        browser_webkit_storage_root(
            "CMUX_BROWSER_WEBKIT_DATA_DIR",
            "XDG_DATA_HOME",
            ".local/share",
        ),
        browser_webkit_storage_root("CMUX_BROWSER_WEBKIT_CACHE_DIR", "XDG_CACHE_HOME", ".cache"),
    ] {
        cleanup_browser_webkit_storage_root(&root, &generations);
    }
}

fn browser_webkit_storage_root(
    override_variable: &str,
    xdg_variable: &str,
    home_suffix: &str,
) -> PathBuf {
    if let Some(path) = normalized_env(override_variable) {
        return PathBuf::from(path);
    }
    if let Some(path) = normalized_env(xdg_variable) {
        return PathBuf::from(path).join("cmux/browser-profiles");
    }
    if let Some(home) = normalized_env("HOME") {
        return PathBuf::from(home)
            .join(home_suffix)
            .join("cmux/browser-profiles");
    }
    std::env::temp_dir()
        .join(format!("cmux-{}", std::process::id()))
        .join("browser-profiles")
}

fn cleanup_browser_webkit_storage_root(root: &Path, generations: &HashMap<String, u64>) {
    let Ok(profile_directories) = fs::read_dir(root) else {
        return;
    };
    for profile_directory in profile_directories.flatten() {
        let path = profile_directory.path();
        if !path.is_dir() {
            continue;
        }
        let Some(profile_key) = profile_directory.file_name().to_str().map(str::to_string) else {
            continue;
        };
        let Some(generation) = generations.get(&profile_key.to_ascii_lowercase()) else {
            let _ = fs::remove_dir_all(path);
            continue;
        };
        let expected = format!("generation-{generation}");
        let Ok(generation_directories) = fs::read_dir(&path) else {
            continue;
        };
        for generation_directory in generation_directories.flatten() {
            let generation_path = generation_directory.path();
            if generation_path.is_dir()
                && generation_directory.file_name().to_str() != Some(expected.as_str())
            {
                let _ = fs::remove_dir_all(generation_path);
            }
        }
    }
}

