#[cfg(test)]
mod session_snapshot_policy_tests {
    use super::{session_snapshot_io_enabled, write_session_snapshot, LinuxSessionSnapshot};
    use std::fs;
    use std::os::unix::fs::PermissionsExt;

    #[test]
    fn unit_tests_require_an_explicit_session_snapshot_path() {
        assert!(!session_snapshot_io_enabled(false, false, true));
        assert!(session_snapshot_io_enabled(false, true, true));
        assert!(session_snapshot_io_enabled(false, false, false));
        assert!(!session_snapshot_io_enabled(true, true, true));
        assert!(!session_snapshot_io_enabled(true, false, false));
    }

    #[test]
    fn session_snapshot_replaces_public_file_with_private_permissions() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let path = tmp.path().join("session-linux.json");
        fs::write(&path, b"legacy snapshot").expect("legacy snapshot");
        fs::set_permissions(&path, fs::Permissions::from_mode(0o644)).expect("public permissions");
        let snapshot = LinuxSessionSnapshot {
            version: 1,
            saved_at: 0.0,
            current_window_index: 0,
            windows: Vec::new(),
        };

        assert!(write_session_snapshot(&path, &snapshot).expect("write snapshot") > 0);
        assert_eq!(
            fs::metadata(&path)
                .expect("snapshot metadata")
                .permissions()
                .mode()
                & 0o777,
            0o600
        );
    }
}

fn load_reopen_session_snapshot() -> Option<LinuxSessionSnapshot> {
    if !session_snapshot_autoload_enabled() {
        return None;
    }
    let path = session_snapshot_path();
    path.exists()
        .then(|| read_session_snapshot(&path).ok())
        .flatten()
}

fn read_session_snapshot(path: &Path) -> AppResult<LinuxSessionSnapshot> {
    let contents = fs::read_to_string(path).map_err(|err| {
        AppError::internal(format!(
            "failed to read session snapshot {}: {err}",
            path.display()
        ))
    })?;
    serde_json::from_str(&contents).map_err(|err| {
        AppError::internal(format!(
            "failed to decode session snapshot {}: {err}",
            path.display()
        ))
    })
}

fn write_session_snapshot(path: &Path, snapshot: &LinuxSessionSnapshot) -> AppResult<usize> {
    let contents = serde_json::to_vec_pretty(snapshot)
        .map_err(|err| AppError::internal(format!("failed to encode session snapshot: {err}")))?;
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|err| {
            AppError::internal(format!(
                "failed to create session snapshot directory {}: {err}",
                parent.display()
            ))
        })?;
    }
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("session-linux.json");
    let tmp_path = path.with_file_name(format!(
        ".{file_name}.{}.{}.tmp",
        std::process::id(),
        Uuid::new_v4()
    ));
    let write_result = (|| -> std::io::Result<()> {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&tmp_path)?;
        file.write_all(&contents)?;
        file.sync_all()?;
        fs::rename(&tmp_path, path)?;
        fs::set_permissions(path, fs::Permissions::from_mode(0o600))?;
        Ok(())
    })();
    if let Err(err) = write_result {
        let _ = fs::remove_file(&tmp_path);
        return Err(AppError::internal(format!(
            "failed to write session snapshot {}: {err}",
            path.display()
        )));
    }
    Ok(contents.len())
}

fn selected_index(ids: &[String], selected: Option<&str>) -> usize {
    selected
        .and_then(|selected| ids.iter().position(|id| id == selected))
        .unwrap_or(0)
}

fn session_terminal_env(env: &HashMap<String, String>) -> HashMap<String, String> {
    env.iter()
        .filter(|(key, _)| {
            !matches!(
                key.as_str(),
                "CMUX_WORKSPACE_ID"
                    | "CMUX_PANE_ID"
                    | "CMUX_SURFACE_ID"
                    | "CMUX_TAB_ID"
                    | "CMUX_PANEL_ID"
            )
        })
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect()
}

fn bounded_surface_scrollback(surface: &Surface) -> Option<String> {
    if let Some(scrollback) = surface.terminal_scrollback_snapshot.as_deref() {
        return Some(bounded_text_tail(
            scrollback,
            SESSION_SNAPSHOT_SCROLLBACK_CHAR_LIMIT,
        ));
    }
    let buffer = surface.buffer.lock().ok()?;
    if buffer.is_empty() {
        return None;
    }
    let char_count = buffer.chars().count();
    let skip = char_count.saturating_sub(SESSION_SNAPSHOT_SCROLLBACK_CHAR_LIMIT);
    Some(buffer.chars().skip(skip).collect())
}

fn bounded_text_tail(text: &str, limit: usize) -> String {
    let char_count = text.chars().count();
    let skip = char_count.saturating_sub(limit);
    text.chars().skip(skip).collect()
}

fn terminal_scrollback_persist_due(changed_at_ms: Option<u64>, now_ms: u64) -> bool {
    changed_at_ms.is_some_and(|changed_at_ms| {
        now_ms.saturating_sub(changed_at_ms) >= TERMINAL_SCROLLBACK_PERSIST_DEBOUNCE_MS
    })
}

fn terminal_replay_output(scrollback: &str) -> String {
    let mut replay = String::with_capacity(scrollback.len());
    let mut previous_was_carriage_return = false;
    for character in scrollback.chars() {
        if character == '\n' && !previous_was_carriage_return {
            replay.push('\r');
        }
        replay.push(character);
        previous_was_carriage_return = character == '\r';
    }
    if !replay.is_empty() && !replay.ends_with('\n') {
        if !replay.ends_with('\r') {
            replay.push('\r');
        }
        replay.push('\n');
    }
    replay
}

