fn diff_comments_repo_root(params: &Value) -> AppResult<String> {
    let raw = string_param(params, "repoRoot")
        .or_else(|| string_param(params, "repo_root"))
        .or_else(|| string_param(params, "repo"))
        .or_else(|| string_param(params, "cwd"))
        .ok_or_else(|| AppError::invalid_params("repoRoot is required"))?;
    let expanded = expand_tilde_path(raw.trim());
    let absolute = if expanded.is_absolute() {
        expanded
    } else {
        std::env::current_dir()
            .map_err(|err| AppError::internal(format!("failed to resolve current dir: {err}")))?
            .join(expanded)
    };
    let canonical = absolute.canonicalize().unwrap_or(absolute);
    Ok(canonical.to_string_lossy().to_string())
}

fn diff_comment_repo_key(repo_root: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(repo_root.as_bytes());
    let digest = hasher.finalize();
    let mut key = String::new();
    for byte in digest.iter().take(12) {
        key.push_str(&format!("{byte:02x}"));
    }
    key
}

fn diff_comment_object(value: &Value) -> AppResult<&Map<String, Value>> {
    value
        .as_object()
        .ok_or_else(|| AppError::invalid_params("comment must be an object"))
}

fn diff_comment_from_object(
    object: &Map<String, Value>,
    incoming_id: Option<String>,
    existing: Option<&DiffCommentState>,
    now: &str,
) -> AppResult<DiffCommentState> {
    let id = incoming_id.unwrap_or_else(|| new_id().to_uppercase());
    let file_path = diff_comment_required_string(
        object,
        &["filePath", "file_path", "path"],
        "filePath",
        MAX_DIFF_COMMENT_META_CHARS,
        "comment",
    )?;
    let message = diff_comment_required_string(
        object,
        &["message", "body", "text"],
        "message",
        MAX_DIFF_COMMENT_FIELD_CHARS,
        "comment",
    )?;
    let start_line = diff_comment_optional_positive_line(
        object,
        &[
            "startLine",
            "start_line",
            "line",
            "lineNumber",
            "line_number",
            "originalLine",
            "original_line",
            "position",
        ],
        "comment",
    )?
    .ok_or_else(|| AppError::invalid_params("comment.startLine is required"))?;
    let end_line = diff_comment_optional_positive_line(
        object,
        &[
            "endLine",
            "end_line",
            "line",
            "lineNumber",
            "line_number",
            "originalLine",
            "original_line",
            "position",
        ],
        "comment",
    )?
    .unwrap_or(start_line);
    let side = diff_comment_normalize_side(
        diff_comment_optional_string(object, &["side"], MAX_DIFF_COMMENT_META_CHARS, "comment")?
            .as_deref()
            .unwrap_or("additions"),
    );
    let end_side = diff_comment_optional_string(
        object,
        &["endSide", "end_side"],
        MAX_DIFF_COMMENT_META_CHARS,
        "comment",
    )?
    .map(|side| diff_comment_normalize_side(&side));
    let line_text = diff_comment_optional_string(
        object,
        &["lineText", "line_text"],
        MAX_DIFF_COMMENT_FIELD_CHARS,
        "comment",
    )?
    .unwrap_or_default();
    let submission_text = diff_comment_optional_string(
        object,
        &["submissionText", "submission_text"],
        MAX_DIFF_COMMENT_FIELD_CHARS,
        "comment",
    )?;
    let consumed_at = diff_comment_optional_string(
        object,
        &["consumedAt", "consumed_at"],
        MAX_DIFF_COMMENT_META_CHARS,
        "comment",
    )?;
    let created_at = diff_comment_optional_string(
        object,
        &["createdAt", "created_at"],
        MAX_DIFF_COMMENT_META_CHARS,
        "comment",
    )?
    .or_else(|| {
        existing
            .map(|comment| comment.created_at.clone())
            .filter(|value| !value.trim().is_empty())
    })
    .unwrap_or_else(|| now.to_string());
    let updated_at = diff_comment_optional_string(
        object,
        &["updatedAt", "updated_at"],
        MAX_DIFF_COMMENT_META_CHARS,
        "comment",
    )?
    .unwrap_or_else(|| now.to_string());

    Ok(DiffCommentState {
        id,
        file_path,
        side,
        start_line,
        end_line,
        end_side,
        line_text,
        message,
        submission_text,
        consumed_at,
        created_at,
        updated_at,
    })
}

fn diff_comment_id_from_params(params: &Value) -> AppResult<String> {
    if let Some(object) = params.as_object() {
        if let Some(id) = diff_comment_optional_string(
            object,
            &["id", "commentId", "comment_id"],
            MAX_DIFF_COMMENT_META_CHARS,
            "comment",
        )? {
            return Ok(id);
        }
    }
    if let Some(comment) = params.get("comment").filter(|value| !value.is_null()) {
        let object = diff_comment_object(comment)?;
        if let Some(id) = diff_comment_optional_string(
            object,
            &["id", "commentId", "comment_id"],
            MAX_DIFF_COMMENT_META_CHARS,
            "comment",
        )? {
            return Ok(id);
        }
    }
    Err(AppError::invalid_params("comment id is required"))
}

fn diff_comment_required_string(
    object: &Map<String, Value>,
    keys: &[&str],
    field: &str,
    max_chars: usize,
    source: &str,
) -> AppResult<String> {
    diff_comment_optional_string(object, keys, max_chars, source)?.ok_or_else(|| {
        AppError::invalid_params(format!(
            "{source} is missing required {field}; accepted keys: {}",
            keys.join(", ")
        ))
    })
}

fn diff_comment_optional_string(
    object: &Map<String, Value>,
    keys: &[&str],
    max_chars: usize,
    source: &str,
) -> AppResult<Option<String>> {
    for key in keys {
        let Some(value) = object.get(*key) else {
            continue;
        };
        if value.is_null() {
            continue;
        }
        let Some(raw) = value_to_string(value) else {
            return Err(AppError::invalid_params(format!(
                "{source}.{key} must be a string"
            )));
        };
        let trimmed = raw.trim();
        if trimmed.is_empty() {
            return Ok(None);
        }
        if trimmed.chars().count() > max_chars {
            return Err(AppError::invalid_params(format!(
                "{source}.{key} exceeds {max_chars} characters"
            )));
        }
        return Ok(Some(trimmed.to_string()));
    }
    Ok(None)
}

fn diff_comment_optional_positive_line(
    object: &Map<String, Value>,
    keys: &[&str],
    source: &str,
) -> AppResult<Option<u64>> {
    for key in keys {
        let Some(value) = object.get(*key) else {
            continue;
        };
        if value.is_null() {
            continue;
        }
        let parsed = if let Some(raw) = value.as_u64() {
            raw
        } else if let Some(raw) = value.as_i64() {
            u64::try_from(raw).unwrap_or(0)
        } else if let Some(raw) = value.as_str() {
            raw.trim().parse::<u64>().map_err(|_| {
                AppError::invalid_params(format!("{source}.{key} must be a positive integer"))
            })?
        } else {
            return Err(AppError::invalid_params(format!(
                "{source}.{key} must be a positive integer"
            )));
        };
        if parsed == 0 {
            return Err(AppError::invalid_params(format!(
                "{source}.{key} must be a positive integer"
            )));
        }
        return Ok(Some(parsed));
    }
    Ok(None)
}

fn diff_comment_normalize_side(side: &str) -> String {
    match side.trim().to_ascii_lowercase().as_str() {
        "deletions" | "deletion" | "deleted" | "left" | "old" | "base" => "deletions".to_string(),
        _ => "additions".to_string(),
    }
}

fn diff_comment_to_review_comment(comment: &DiffCommentState) -> diff_viewer::DiffReviewComment {
    diff_viewer::DiffReviewComment {
        id: Some(comment.id.clone()),
        file_path: comment.file_path.clone(),
        side: comment.side.clone(),
        start_line: Some(comment.start_line),
        end_line: Some(comment.end_line),
        end_side: comment.end_side.clone(),
        line_text: if comment.line_text.trim().is_empty() {
            None
        } else {
            Some(comment.line_text.clone())
        },
        message: comment.message.clone(),
        submission_text: comment.submission_text.clone(),
        author: None,
        created_at: if comment.created_at.trim().is_empty() {
            None
        } else {
            Some(comment.created_at.clone())
        },
        outdated: false,
        resolved: false,
    }
}

fn message_with_diff_comment_submissions(
    message: Option<String>,
    pending_diff_comments: &[DiffCommentPendingEntry],
) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(message) = message.filter(|message| !message.trim().is_empty()) {
        parts.push(message);
    }
    for comment in pending_diff_comments {
        let trimmed = comment.submission_text.trim();
        if !trimmed.is_empty() {
            parts.push(trimmed.to_string());
        }
    }
    if parts.is_empty() {
        None
    } else {
        Some(parts.join("\n\n"))
    }
}

fn workspace_prompt_message(params: &Value) -> AppResult<Option<String>> {
    let Some(object) = params.as_object() else {
        return Ok(None);
    };
    let keys = ["message", "prompt", "text", "body"];
    for key in keys {
        let Some(raw) = object.get(key) else {
            continue;
        };
        if raw.is_null() {
            continue;
        }
        if !raw.is_string() {
            return Err(AppError::invalid_params(format!("{key} must be a string")));
        }
    }
    Ok(keys
        .iter()
        .filter_map(|key| object.get(*key)?.as_str().map(ToString::to_string))
        .next())
}

fn conversation_message_preview(message: Option<&str>) -> Option<String> {
    const MAX_PREVIEW_CHARS: usize = 240;
    let collapsed = message?
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .trim()
        .to_string();
    if collapsed.is_empty() {
        return None;
    }
    let mut chars = collapsed.chars();
    let preview = chars.by_ref().take(MAX_PREVIEW_CHARS).collect::<String>();
    if chars.next().is_some() {
        Some(format!("{preview}..."))
    } else {
        Some(preview)
    }
}

fn non_empty_trimmed(value: String) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

fn remote_tmux_value_has_hidden_character(value: &str) -> bool {
    value.chars().any(|ch| {
        ch.is_control()
            || ch.is_whitespace()
            || ('\u{200B}'..='\u{200F}').contains(&ch)
            || ('\u{202A}'..='\u{202E}').contains(&ch)
            || ('\u{2060}'..='\u{206F}').contains(&ch)
            || ch == '\u{FEFF}'
    })
}

fn remote_tmux_name_has_hidden_character(value: &str) -> bool {
    value.chars().any(|ch| {
        ch.is_control()
            || ('\u{200B}'..='\u{200F}').contains(&ch)
            || ('\u{202A}'..='\u{202E}').contains(&ch)
            || ('\u{2060}'..='\u{206F}').contains(&ch)
            || ch == '\u{FEFF}'
    })
}

fn normalized_tty_name(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() || trimmed == "not a tty" {
        return None;
    }
    trimmed
        .rsplit('/')
        .next()
        .and_then(|name| non_empty_trimmed(name.to_string()))
}

fn required_raw_id(value: Option<&Value>, message: &'static str) -> AppResult<String> {
    value
        .and_then(value_to_string)
        .and_then(non_empty_trimmed)
        .ok_or_else(|| AppError::invalid_params(message))
}

