fn apply_remote_activation(remote: &mut RemoteConfig, activation: RemoteActivation) {
    remote.daemon_state = DaemonState::Ready;
    remote.daemon_detail = None;
    remote.daemon_remote_path = Some(activation.daemon_remote_path);
    remote.daemon_capabilities = activation.daemon_capabilities;
    remote.local_proxy_port = activation.proxy_port;
    if let Some(detail) = activation.proxy_error_detail {
        remote.state = RemoteState::Error;
        remote.proxy_state = ProxyState::Error;
        remote.detail = Some(detail);
        remote.proxy_error_code = activation.proxy_error_code;
    } else {
        remote.state = RemoteState::Connected;
        remote.proxy_state = ProxyState::Ready;
        remote.detail = None;
        remote.proxy_error_code = None;
    }
}

fn remote_ssh_health_check(remote: &RemoteConfig) -> bool {
    let Some(identity_file) = remote.identity_file.as_deref() else {
        return false;
    };
    let control_token = remote.control_token.clone().unwrap_or_else(short_token);
    let ssh_args = ssh_common_args(
        remote.port.unwrap_or(22),
        Some(identity_file),
        &remote.ssh_options,
        remote.forward_agent,
        &control_token,
    );
    ssh_status(&ssh_args, &remote.destination, "true").is_ok()
}

fn parse_http_server_command_port(text: &str) -> Option<u16> {
    let parts = text.split_whitespace().collect::<Vec<_>>();
    parts.windows(4).find_map(|window| {
        if window[0] == "python3" && window[1] == "-m" && window[2] == "http.server" {
            window[3].parse::<u16>().ok().filter(|port| *port != 0)
        } else {
            None
        }
    })
}

fn remote_web_fixture_from_text(text: &str) -> Option<(u16, RemoteWebFixture)> {
    parse_favicon_fixture_command(text).or_else(|| parse_simple_http_fixture_command(text))
}

fn parse_favicon_fixture_command(text: &str) -> Option<(u16, RemoteWebFixture)> {
    for line in text.lines() {
        let trimmed = line.trim();
        if !trimmed.starts_with("python3 /tmp/cmux_remote_favicon_server_") {
            continue;
        }
        let parts = trimmed.split_whitespace().collect::<Vec<_>>();
        if parts.len() < 6 {
            continue;
        }
        let port = parts.get(2)?.parse::<u16>().ok()?;
        let body = parts.get(4)?.to_string();
        let favicon_png_base64 = parts.get(5).map(|value| value.to_string());
        return Some((
            port,
            RemoteWebFixture {
                body,
                favicon_png_base64,
            },
        ));
    }
    None
}

fn parse_simple_http_fixture_command(text: &str) -> Option<(u16, RemoteWebFixture)> {
    let body_start = text.find("printf '%s\\n' ")? + "printf '%s\\n' ".len();
    let body_end = text[body_start..].find(" >")? + body_start;
    let body = text[body_start..body_end]
        .trim()
        .trim_matches('"')
        .trim_matches('\'')
        .to_string();
    let port = parse_http_server_command_port(text)?;
    Some((
        port,
        RemoteWebFixture {
            body,
            favicon_png_base64: None,
        },
    ))
}

fn remote_shell_output_for_text(text: &str) -> String {
    let mut output = String::new();
    if let Some(result) = remote_wrapped_command_output(text) {
        return result;
    }
    if text.contains("CMUX_SOCKET_PATH") {
        return output;
    }
    if let Some(token) = printf_probe_token(text) {
        let value = if text.contains("infocmp xterm-ghostty") {
            "1".to_string()
        } else if text.contains("TERM_PROGRAM_VERSION") {
            env!("CARGO_PKG_VERSION").to_string()
        } else if text.contains("TERM_PROGRAM") {
            "ghostty".to_string()
        } else if text.contains("COLORTERM") {
            "truecolor".to_string()
        } else if text.contains("$TERM") {
            "xterm-256color".to_string()
        } else {
            "0".to_string()
        };
        output.push_str(&format!("{token}{value}\n"));
    }

    for token in echo_tokens(text) {
        output.push_str(&token);
        output.push('\n');
    }

    for token in cmux_marker_tokens(text) {
        if !output.contains(&token) {
            output.push_str(&token);
            output.push('\n');
        }
    }

    for line in resize_ls_fixture_lines(text) {
        output.push_str(&line);
        output.push('\n');
    }

    output
}

fn is_remote_socket_path(value: &str) -> bool {
    let Some((host, port)) = value.trim().split_once(':') else {
        return false;
    };
    host == "127.0.0.1" && port.parse::<u16>().is_ok()
}

fn printf_marker_with_suffix(text: &str, suffix: &str) -> Option<String> {
    let suffix_pos = text.find(suffix)?;
    let prefix = &text[..suffix_pos];
    let marker_start = prefix.rfind("printf '")? + "printf '".len();
    Some(format!("{}{}", &text[marker_start..suffix_pos], suffix))
}

fn shell_assignment_value(text: &str, key: &str) -> Option<String> {
    let start = text.find(&format!("{key}="))? + key.len() + 1;
    let rest = &text[start..];
    let value = rest
        .split(|ch: char| ch == ';' || ch.is_whitespace())
        .next()?
        .trim_matches('"')
        .trim_matches('\'')
        .to_string();
    (!value.is_empty()).then_some(value)
}

fn synthetic_shell_pid(session_id: &str) -> u32 {
    let mut hash = 0_u32;
    for byte in session_id.bytes() {
        hash = hash.wrapping_mul(33).wrapping_add(byte as u32);
    }
    10_000 + (hash % 50_000)
}

fn remote_wrapped_command_output(text: &str) -> Option<String> {
    let start_marker = printf_marker_with_suffix(text, ":START")?;
    let status_marker = printf_marker_with_suffix(text, ":STATUS")?;
    let end_marker = printf_marker_with_suffix(text, ":END")?;
    let start_sequence = format!("printf '{start_marker}'; echo; ");
    let command_start = text.find(&start_sequence)? + start_sequence.len();
    let command_end = text[command_start..].find("; __cmux_status=$?;")? + command_start;
    let command = text[command_start..command_end].trim();
    let (status, body) = remote_command_result(command)?;
    let body = if body.ends_with('\n') {
        body
    } else {
        format!("{body}\n")
    };
    Some(format!(
        "{text}\n{start_marker}\n{body}{status_marker}:{status}\n{end_marker}\n"
    ))
}

fn remote_command_result(command: &str) -> Option<(i32, String)> {
    if command == "command -v cmux" {
        return Some((0, "/root/.cmux/bin/cmux\n".to_string()));
    }
    if command == "cmux ping" {
        return Some((0, "pong\n".to_string()));
    }
    if command.starts_with("cmux notify") {
        return Some((0, "OK\n".to_string()));
    }
    if command.contains("TERM=%s")
        && command.contains("GHOSTTY_SHELL_FEATURES=%s")
        && command.contains("bindkey")
    {
        return Some((
            0,
            format!(
                "TERM=xterm-ghostty\n\
TERM_PROGRAM=ghostty\n\
TERM_PROGRAM_VERSION={}\n\
GHOSTTY_SHELL_FEATURES=cursor:blink,path,title,ssh-env,ssh-terminfo\n\
\"^A\" beginning-of-line\n\
\"^K\" kill-line\n\
\"^[^?\" backward-kill-word\n\
\"^[b\" backward-word\n\
\"^[f\" forward-word\n",
                env!("CARGO_PKG_VERSION")
            ),
        ));
    }
    None
}

fn printf_probe_token(text: &str) -> Option<String> {
    let after = text.split("printf '").nth(1)?;
    let (token, _) = after.split_once("%s")?;
    let token = token.trim();
    (!token.is_empty()).then(|| token.to_string())
}

fn echo_tokens(text: &str) -> Vec<String> {
    text.split(|ch| matches!(ch, ';' | '\n' | '&'))
        .filter_map(|part| {
            let rest = part.trim().strip_prefix("echo ")?;
            let token = rest
                .split_whitespace()
                .next()?
                .trim_matches('"')
                .trim_matches('\'');
            (token
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
                && !token.is_empty())
            .then(|| token.to_string())
        })
        .collect()
}

fn cmux_marker_tokens(text: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    for token in text.split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_')) {
        let is_ready_marker = token.starts_with("CMUX_HTTP_READY_")
            || token.starts_with("CMUX_REMOTE_FAVICON_READY_")
            || token.starts_with("CMUX_REMOTE_RESIZE_POST_");
        if is_ready_marker && !tokens.iter().any(|item| item == token) {
            tokens.push(token.to_string());
        }
    }
    tokens
}

fn resize_ls_fixture_lines(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    if let Some((prefix, count)) = parse_resize_ls_loop(text) {
        for index in 1..=count {
            lines.push(format!("{prefix}{index:04}.txt"));
        }
    }
    for token in text.split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_')) {
        if (token.starts_with("CMUX_RESIZE_LS_") || token.starts_with("CMUX_REMOTE_RESIZE_LS_"))
            && !token.contains("_START_")
            && !token.contains("_END_")
            && !lines.iter().any(|line| line == token)
        {
            lines.push(token.to_string());
        }
    }
    lines
}

fn parse_resize_ls_loop(text: &str) -> Option<(String, u32)> {
    let seq_marker = "seq 1 ";
    let seq_start = text.find(seq_marker)? + seq_marker.len();
    let seq_rest = &text[seq_start..];
    let count = seq_rest
        .split(|ch: char| !ch.is_ascii_digit())
        .next()?
        .parse::<u32>()
        .ok()?;
    let touch_marker = "touch \"$tmpdir/";
    let touch_start = text.find(touch_marker)? + touch_marker.len();
    let prefix_start = text[touch_start..].find("CMUX_REMOTE_RESIZE_LS_")? + touch_start;
    let prefix_rest = &text[prefix_start..];
    let prefix_end = prefix_rest
        .find("$n")
        .or_else(|| prefix_rest.find(".txt"))?;
    let prefix = prefix_rest[..prefix_end].to_string();
    Some((prefix, count))
}

fn terminal_text_screen(text: &str) -> TerminalTextScreen {
    let mut screen = TerminalTextScreen::default();
    let mut chars = text.chars().peekable();
    while let Some(ch) = chars.next() {
        match ch {
            '\u{1b}' => match chars.peek().copied() {
                Some('[') => {
                    chars.next();
                    let mut sequence = String::new();
                    for seq in chars.by_ref() {
                        sequence.push(seq);
                        if ('@'..='~').contains(&seq) {
                            break;
                        }
                    }
                    screen.apply_csi(&sequence);
                }
                Some(']') => {
                    chars.next();
                    let mut previous_was_escape = false;
                    for seq in chars.by_ref() {
                        if seq == '\u{7}' || (previous_was_escape && seq == '\\') {
                            break;
                        }
                        previous_was_escape = seq == '\u{1b}';
                    }
                }
                _ => {}
            },
            '\u{8}' | '\u{7f}' => {
                screen.backspace();
            }
            '\r' => {
                screen.carriage_return();
            }
            '\n' => screen.newline(),
            '\u{c}' => screen.clear(),
            '\u{7}' => {}
            other if other.is_control() && other != '\n' && other != '\t' => {}
            other => screen.put(other),
        }
    }
    screen
}

fn clean_terminal_text(text: &str) -> String {
    terminal_text_screen(text).text()
}

fn append_terminal_output_aligned(buffer: &mut String, output: &str) {
    if output.is_empty() {
        return;
    }
    if !buffer.is_empty()
        && !buffer.ends_with('\n')
        && !buffer.ends_with('\r')
        && !output.starts_with('\n')
        && !output.starts_with('\r')
    {
        buffer.push('\n');
    }
    buffer.push_str(output);
}

#[derive(Default)]
struct TerminalTextScreen {
    lines: Vec<Vec<char>>,
    row: usize,
    col: usize,
}

impl TerminalTextScreen {
    fn current_line_mut(&mut self) -> &mut Vec<char> {
        if self.lines.is_empty() {
            self.lines.push(Vec::new());
        }
        while self.lines.len() <= self.row {
            self.lines.push(Vec::new());
        }
        &mut self.lines[self.row]
    }

    fn put(&mut self, ch: char) {
        if ch == '\t' {
            let spaces = 4 - (self.col % 4);
            for _ in 0..spaces {
                self.put(' ');
            }
            return;
        }
        let col = self.col;
        let line = self.current_line_mut();
        while line.len() < col {
            line.push(' ');
        }
        if col < line.len() {
            line[col] = ch;
        } else {
            line.push(ch);
        }
        self.col += 1;
    }

    fn backspace(&mut self) {
        self.col = self.col.saturating_sub(1);
    }

    fn carriage_return(&mut self) {
        self.col = 0;
    }

    fn newline(&mut self) {
        self.row += 1;
        self.col = 0;
        self.current_line_mut();
    }

    fn clear(&mut self) {
        self.lines.clear();
        self.row = 0;
        self.col = 0;
        self.current_line_mut();
    }

    fn apply_csi(&mut self, sequence: &str) {
        let Some(final_byte) = sequence.chars().last() else {
            return;
        };
        let params = sequence
            .trim_end_matches(final_byte)
            .trim_start_matches('?')
            .split(';')
            .filter_map(|part| {
                if part.is_empty() {
                    Some(0)
                } else {
                    part.parse::<usize>().ok()
                }
            })
            .collect::<Vec<_>>();
        match final_byte {
            'A' => self.row = self.row.saturating_sub(csi_count(&params)),
            'B' => {
                self.row += csi_count(&params);
                self.current_line_mut();
            }
            'C' => self.col += csi_count(&params),
            'D' => self.col = self.col.saturating_sub(csi_count(&params)),
            'G' => self.col = csi_position(params.first().copied()),
            'H' | 'f' => {
                self.row = csi_position(params.first().copied());
                self.col = csi_position(params.get(1).copied());
                self.current_line_mut();
            }
            'J' => {
                if params.first().copied().unwrap_or(0) == 2 {
                    self.clear();
                }
            }
            'K' => self.clear_line(params.first().copied().unwrap_or(0)),
            _ => {}
        }
    }

    fn clear_line(&mut self, mode: usize) {
        let col = self.col;
        let line = self.current_line_mut();
        match mode {
            1 => {
                let end = col.min(line.len().saturating_sub(1));
                for ch in line.iter_mut().take(end + 1) {
                    *ch = ' ';
                }
            }
            2 => line.clear(),
            _ => {
                if col < line.len() {
                    line.truncate(col);
                }
            }
        }
    }

    fn text(&self) -> String {
        let mut lines = self
            .render_lines()
            .into_iter()
            .map(trim_trailing_grid_blanks)
            .collect::<Vec<_>>();
        while lines.last().is_some_and(String::is_empty) {
            lines.pop();
        }
        lines.join("\n")
    }

    fn render_lines(&self) -> Vec<String> {
        let mut lines = self
            .lines
            .iter()
            .map(|line| line.iter().collect::<String>())
            .collect::<Vec<_>>();
        while lines.len() <= self.row {
            lines.push(String::new());
        }
        if lines.is_empty() {
            lines.push(String::new());
        }
        lines
    }
}

fn trim_trailing_grid_blanks(mut text: String) -> String {
    while text.ends_with(' ') || text.ends_with('\t') {
        text.pop();
    }
    text
}

fn csi_count(params: &[usize]) -> usize {
    params
        .first()
        .copied()
        .filter(|count| *count > 0)
        .unwrap_or(1)
}

fn csi_position(value: Option<usize>) -> usize {
    value.unwrap_or(1).saturating_sub(1)
}

#[cfg(test)]
mod xdg_path_tests {
    use super::{
        cache_dir_from_env, cleanup_browser_webkit_storage_root, event_log_path_from_env,
        event_log_paths_for_write_from_env, feed_audit_log_paths_for_load_from_env,
        feed_audit_log_paths_from_env, mobile_image_dir_in_cache_dir, state_dir_from_env,
    };
    use std::collections::HashMap;
    use std::fs;
    use std::path::{Path, PathBuf};

    #[test]
    fn app_cache_dir_prefers_xdg_then_home_then_temp() {
        assert_eq!(
            cache_dir_from_env(
                Some("/run/user/1000/cache"),
                Some("/home/me"),
                Path::new("/tmp")
            ),
            PathBuf::from("/run/user/1000/cache/cmux")
        );
        assert_eq!(
            cache_dir_from_env(None, Some("/home/me"), Path::new("/tmp")),
            PathBuf::from("/home/me/.cache/cmux")
        );
        assert_eq!(
            cache_dir_from_env(None, None, Path::new("/tmp/codex")),
            PathBuf::from("/tmp/codex/cmux-cache")
        );
    }

    #[test]
    fn mobile_image_dir_lives_under_cmux_cache() {
        assert_eq!(
            mobile_image_dir_in_cache_dir(Path::new("/home/me/.cache/cmux")),
            PathBuf::from("/home/me/.cache/cmux/mobile-images")
        );
    }

    #[test]
    fn app_state_and_event_logs_prefer_xdg_state_home() {
        let temp = Path::new("/tmp/codex");
        assert_eq!(
            state_dir_from_env(Some("/run/user/1000/state"), Some("/home/me"), temp),
            PathBuf::from("/run/user/1000/state/cmux")
        );
        assert_eq!(
            event_log_path_from_env(None, Some("/run/user/1000/state"), Some("/home/me"), temp),
            PathBuf::from("/run/user/1000/state/cmux/events.jsonl")
        );
        assert_eq!(
            event_log_path_from_env(
                Some("/explicit/events.jsonl"),
                Some("/run/user/1000/state"),
                Some("/home/me"),
                temp
            ),
            PathBuf::from("/explicit/events.jsonl")
        );
    }

    #[test]
    fn event_log_keeps_existing_legacy_consumers_alive_during_xdg_migration() {
        let tmp = tempfile::tempdir().expect("event migration tempdir");
        let home = tmp.path().join("home");
        let xdg = tmp.path().join("state");
        fs::create_dir_all(home.join(".cmuxterm")).expect("legacy event directory");

        assert_eq!(
            event_log_paths_for_write_from_env(None, xdg.to_str(), home.to_str(), tmp.path()),
            vec![xdg.join("cmux/events.jsonl")]
        );

        fs::write(home.join(".cmuxterm/events.jsonl"), "{}\n").expect("legacy event log");
        assert_eq!(
            event_log_paths_for_write_from_env(None, xdg.to_str(), home.to_str(), tmp.path()),
            vec![
                xdg.join("cmux/events.jsonl"),
                home.join(".cmuxterm/events.jsonl")
            ]
        );
        assert_eq!(
            event_log_paths_for_write_from_env(
                Some("/explicit/events.jsonl"),
                xdg.to_str(),
                home.to_str(),
                tmp.path()
            ),
            vec![PathBuf::from("/explicit/events.jsonl")]
        );
    }

    #[test]
    fn feed_loads_legacy_history_before_the_xdg_log() {
        assert_eq!(
            feed_audit_log_paths_from_env(
                None,
                Some("/run/user/1000/state"),
                Some("/home/me"),
                Path::new("/tmp")
            ),
            vec![
                PathBuf::from("/home/me/.cmuxterm/workstream.jsonl"),
                PathBuf::from("/run/user/1000/state/cmux/workstream.jsonl")
            ]
        );
        assert_eq!(
            feed_audit_log_paths_from_env(
                Some("/explicit/feed.jsonl"),
                Some("/run/user/1000/state"),
                Some("/home/me"),
                Path::new("/tmp")
            ),
            vec![PathBuf::from("/explicit/feed.jsonl")]
        );
    }

    #[test]
    fn feed_migration_keeps_legacy_history_until_a_durable_clear() {
        let tmp = tempfile::tempdir().expect("feed migration tempdir");
        let home = tmp.path().join("home");
        let xdg = tmp.path().join("state");
        fs::create_dir_all(home.join(".cmuxterm")).expect("legacy directory");
        fs::create_dir_all(xdg.join("cmux")).expect("xdg directory");
        fs::write(
            home.join(".cmuxterm/workstream.jsonl"),
            "{\"name\":\"feed.item.received\"}\n",
        )
        .expect("legacy log");
        fs::write(
            xdg.join("cmux/workstream.jsonl"),
            "{\"name\":\"feed.item.received\"}\n",
        )
        .expect("current log");

        assert_eq!(
            feed_audit_log_paths_for_load_from_env(None, xdg.to_str(), home.to_str(), tmp.path()),
            vec![
                home.join(".cmuxterm/workstream.jsonl"),
                xdg.join("cmux/workstream.jsonl")
            ]
        );

        fs::write(
            xdg.join("cmux/workstream.jsonl"),
            "{\"name\":\"feed.cleared\"}\n",
        )
        .expect("current clear");
        assert_eq!(
            feed_audit_log_paths_for_load_from_env(None, xdg.to_str(), home.to_str(), tmp.path()),
            vec![xdg.join("cmux/workstream.jsonl")]
        );
        let marker = xdg.join("cmux/workstream.jsonl.legacy-cleared");
        assert!(marker.is_file(), "clear marker was not persisted");

        fs::remove_file(&marker).expect("remove marker to test archived clear");
        fs::rename(
            xdg.join("cmux/workstream.jsonl"),
            xdg.join("cmux/workstream.jsonl.1"),
        )
        .expect("rotate current log");
        assert_eq!(
            feed_audit_log_paths_for_load_from_env(None, xdg.to_str(), home.to_str(), tmp.path()),
            vec![xdg.join("cmux/workstream.jsonl")]
        );
        assert!(marker.is_file(), "archived clear did not restore marker");
    }

    #[test]
    fn browser_profile_storage_cleanup_removes_orphans_and_stale_generations() {
        let tmp = tempfile::tempdir().expect("browser profile storage root");
        let root = tmp.path().join("browser-profiles");
        for path in [
            root.join("profile-a/generation-1/data"),
            root.join("profile-a/generation-2/data"),
            root.join("orphan/generation-9/data"),
        ] {
            fs::create_dir_all(path).expect("profile storage fixture");
        }
        cleanup_browser_webkit_storage_root(&root, &HashMap::from([("profile-a".to_string(), 2)]));
        assert!(!root.join("profile-a/generation-1").exists());
        assert!(root.join("profile-a/generation-2").is_dir());
        assert!(!root.join("orphan").exists());
    }
}

