#[cfg(test)]
mod remote_ssh_command_tests {
    use super::{
        build_remote_bootstrap, build_ssh_command, build_ssh_terminal_command,
        remote_cmux_wrapper_script, ssh_control_path_in_dir,
    };
    use std::path::Path;

    #[test]
    fn ssh_terminal_command_streams_startup_script_before_running_remote_shell() {
        let command = build_ssh_terminal_command(
            "ssh -p 2200 -o ControlMaster=auto example.test",
            43123,
            "/tmp/cmux startup.sh",
        );

        assert!(
            command.starts_with("ssh -tt -p 2200 -o ControlMaster=auto example.test "),
            "command was {command}"
        );
        assert!(
            command.contains("cat > \"$cmux_tmp\";"),
            "command was {command}"
        );
        assert!(
            command.contains("sh \"$cmux_tmp\" </dev/tty"),
            "command was {command}"
        );
        assert!(
            command.contains("$HOME/.cmux/relay/43123.tty"),
            "command was {command}"
        );
        assert!(
            command.ends_with("< '/tmp/cmux startup.sh'"),
            "command was {command}"
        );
        assert!(
            !command.contains("mktemp /tmp/cmux-ssh-startup-"),
            "command was {command}"
        );
    }

    #[test]
    fn remote_bootstrap_exports_surface_scoped_tab_context() {
        let script = build_remote_bootstrap(43123);

        assert!(
            script.contains("export CMUX_WORKSPACE_ID='__CMUX_WORKSPACE_ID__'"),
            "script was {script}"
        );
        assert!(
            script.contains("export CMUX_TAB_ID='__CMUX_SURFACE_ID__'"),
            "script was {script}"
        );
        assert!(
            script.contains("export CMUX_SURFACE_ID='__CMUX_SURFACE_ID__'"),
            "script was {script}"
        );
        assert!(
            script.contains("export CMUX_PANEL_ID='__CMUX_SURFACE_ID__'"),
            "script was {script}"
        );
        assert!(
            !script.contains("export CMUX_TAB_ID='__CMUX_WORKSPACE_ID__'"),
            "script was {script}"
        );
        assert!(
            script.contains("cat > \"$cmux_shell_dir/.zshrc\""),
            "script was {script}"
        );
        assert!(
            script.contains("export ZDOTDIR=\"$cmux_shell_dir\""),
            "script was {script}"
        );
        assert!(
            script.contains("cat > \"$cmux_shell_dir/.bashrc\""),
            "script was {script}"
        );
        assert!(
            script.contains(
                "bash) exec \"$CMUX_LOGIN_SHELL\" --rcfile \"$cmux_shell_dir/.bashrc\" -i ;;"
            ),
            "script was {script}"
        );
    }

    #[test]
    fn remote_wrapper_forwards_terminal_context_env_as_socket_params() {
        let script = remote_cmux_wrapper_script();

        for snippet in [
            r#"if "CMUX_WORKSPACE_ID" in os.environ and "workspace_id" not in params:"#,
            r#"if "CMUX_SURFACE_ID" in os.environ and "surface_id" not in params:"#,
            r#"if "CMUX_PANEL_ID" in os.environ and "surface_id" not in params:"#,
            r#"if "CMUX_TAB_ID" in os.environ and "tab_id" not in params:"#,
            r#"if "CMUX_PANEL_ID" in os.environ and "panel_id" not in params:"#,
            r#"if "CMUX_PANE_ID" in os.environ and "pane_id" not in params:"#,
        ] {
            assert!(script.contains(snippet), "script was {script}");
        }
    }

    #[test]
    fn ssh_command_uses_cmux_control_socket_directory() {
        let control_path = ssh_control_path_in_dir(
            Path::new("/run/user/1000/cmux/ssh-control"),
            "cmux-ssh-token-%C",
        );
        let command = build_ssh_command(
            "example.test",
            Some(2200),
            Some("/home/me/key"),
            &[format!("ControlPath={control_path}")],
            Some(false),
            "fallback-token",
        );

        assert!(
            command.contains("ControlPath=/run/user/1000/cmux/ssh-control/cmux-ssh-token-%C"),
            "command was {command}"
        );
        assert!(
            !command.contains("/tmp/cmux-ssh-fallback-token"),
            "command was {command}"
        );
    }
}

