    fn configure_hibernation_candidate(
        app: &mut AppState,
        surface_id: &str,
        command: &str,
        activity_ms: u64,
    ) {
        let surface = app.surfaces.get_mut(surface_id).expect("surface");
        surface.resume_binding = Some(super::ResumeBinding {
            name: Some("Codex".to_string()),
            kind: Some("codex".to_string()),
            command: command.to_string(),
            cwd: None,
            checkpoint_id: Some(format!("checkpoint-{surface_id}")),
            source: Some("agent-hook".to_string()),
            environment: HashMap::new(),
            auto_resume: true,
            approval_policy: Some("auto".to_string()),
            approval_record_id: None,
            updated_at: 1.0,
        });
        surface
            .agent_lifecycle
            .insert("codex".to_string(), super::AgentLifecycleState::Idle);
        surface.agent_hibernation_last_activity_ms = activity_ms;
        surface.agent_hibernation_last_input_ms = 0;
        surface.agent_hibernation_last_lifecycle_change_ms = activity_ms;
        surface.agent_hibernation_tail_stable_since_ms = activity_ms;
    }

    #[test]
    fn agent_hibernation_settles_hibernates_restores_and_resumes_renderer_owned_surfaces() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let protected_surface = app.current_surface_id().expect("protected surface");
        let background_workspace_a = app
            .workspace_create(&json!({"title": "Background A", "focus": false}))
            .expect("workspace a")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let background_workspace_b = app
            .workspace_create(&json!({"title": "Background B", "focus": false}))
            .expect("workspace b")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let background_surface_a = app.workspace_surface_ids(&background_workspace_a)[0].clone();
        let background_surface_b = app.workspace_surface_ids(&background_workspace_b)[0].clone();

        for surface_id in [
            protected_surface.as_str(),
            background_surface_a.as_str(),
            background_surface_b.as_str(),
        ] {
            configure_hibernation_candidate(
                &mut app,
                surface_id,
                "printf 'CMUX_HIBERNATION_RESUMED\\n'",
                1_000,
            );
            app.surfaces
                .get_mut(surface_id)
                .expect("surface")
                .embedded_terminal_ready = true;
        }
        app.agent_hibernation_settings = crate::agent_hibernation_settings::Settings {
            enabled: true,
            idle_seconds: 5,
            max_live_terminals: 1,
            confirmation_seconds: 1,
        };

        assert_eq!(app.evaluate_agent_hibernation(10_000), 0);
        assert_eq!(app.evaluate_agent_hibernation(16_000), 0);
        assert_eq!(app.agent_hibernation_confirmations.len(), 2);
        assert_eq!(app.evaluate_agent_hibernation(17_000), 2);
        assert!(app.surfaces[&protected_surface].agent_hibernation.is_none());
        assert!(app.surfaces[&background_surface_a]
            .agent_hibernation
            .is_some());
        assert!(app.surfaces[&background_surface_b]
            .agent_hibernation
            .is_some());

        let snapshot = app.session_snapshot(false);
        let persisted = snapshot
            .windows
            .iter()
            .flat_map(|window| window.workspaces.iter())
            .flat_map(|workspace| workspace.panes.iter())
            .flat_map(|pane| pane.surfaces.iter())
            .filter(|surface| surface.agent_hibernation.is_some())
            .count();
        assert_eq!(persisted, 2);

        assert!(app
            .resume_agent_hibernated_surface(&background_surface_a)
            .expect("resume"));
        let resumed = &app.surfaces[&background_surface_a];
        assert!(resumed.agent_hibernation.is_none());
        assert_eq!(
            resumed.terminal_initial_input.as_deref(),
            Some("printf 'CMUX_HIBERNATION_RESUMED\\n'\r")
        );
        assert!(resumed.terminal.is_none());

        let resumed_snapshot = app.session_snapshot(false);
        let mut restored = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("restored app");
        restored
            .restore_session_snapshot(resumed_snapshot)
            .expect("restore hibernation snapshot");
        let restored_background_b = restored
            .workspaces
            .values()
            .find(|workspace| workspace.title == "Background B")
            .expect("restored background workspace");
        let restored_background_b_surface =
            restored.workspace_surface_ids(&restored_background_b.id)[0].clone();
        assert!(restored.surfaces[&restored_background_b_surface]
            .agent_hibernation
            .is_some());

        let status = app.agent_hibernation_status();
        assert_eq!(status["runtime_supported"], true);
        assert_eq!(status["hibernated_surface_count"], 1);
    }

    #[test]
    fn agent_hibernation_output_change_cancels_confirmation() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let protected_surface = app.current_surface_id().expect("protected");
        let background_workspace = app
            .workspace_create(&json!({"title": "Background", "focus": false}))
            .expect("background")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let background_surface = app.workspace_surface_ids(&background_workspace)[0].clone();
        for surface_id in [protected_surface.as_str(), background_surface.as_str()] {
            configure_hibernation_candidate(&mut app, surface_id, "printf resumed", 1_000);
            app.surfaces
                .get_mut(surface_id)
                .expect("surface")
                .embedded_terminal_ready = true;
        }
        app.agent_hibernation_settings = crate::agent_hibernation_settings::Settings {
            enabled: true,
            idle_seconds: 5,
            max_live_terminals: 1,
            confirmation_seconds: 1,
        };

        assert_eq!(app.evaluate_agent_hibernation(10_000), 0);
        assert_eq!(app.evaluate_agent_hibernation(16_000), 0);
        assert!(app
            .agent_hibernation_confirmations
            .contains_key(&background_surface));
        app.surfaces[&background_surface]
            .buffer
            .lock()
            .expect("buffer")
            .push_str("new output");
        assert_eq!(app.evaluate_agent_hibernation(17_000), 0);
        assert!(!app
            .agent_hibernation_confirmations
            .contains_key(&background_surface));
        assert!(app.surfaces[&background_surface]
            .agent_hibernation
            .is_none());
        assert_eq!(app.evaluate_agent_hibernation(23_000), 0);
        assert_eq!(app.evaluate_agent_hibernation(24_000), 1);
    }

    #[test]
    fn agent_hibernation_terminates_and_respawns_a_core_pty() {
        let mut app = AppState::with_paths(None, None).expect("app state");
        let background_surface = app.current_surface_id().expect("background surface");
        let old_pid = app.surfaces[&background_surface]
            .terminal
            .as_ref()
            .and_then(|terminal| terminal.pid())
            .expect("old terminal pid");
        configure_hibernation_candidate(
            &mut app,
            &background_surface,
            "printf 'CMUX_HIBERNATION_CORE_RESUMED\\n'",
            1_000,
        );
        let foreground_workspace = app
            .workspace_create(&json!({"title": "Foreground", "focus": true}))
            .expect("foreground workspace")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let foreground_surface = app.workspace_surface_ids(&foreground_workspace)[0].clone();
        configure_hibernation_candidate(&mut app, &foreground_surface, "printf foreground", 1_000);
        app.agent_hibernation_settings = crate::agent_hibernation_settings::Settings {
            enabled: true,
            idle_seconds: 5,
            max_live_terminals: 1,
            confirmation_seconds: 1,
        };

        assert_eq!(app.evaluate_agent_hibernation(10_000), 0);
        assert_eq!(app.evaluate_agent_hibernation(16_000), 0);
        assert_eq!(app.evaluate_agent_hibernation(17_000), 1);
        assert!(app.surfaces[&background_surface]
            .agent_hibernation
            .is_some());
        for _ in 0..50 {
            if !std::path::Path::new(&format!("/proc/{old_pid}")).exists() {
                break;
            }
            thread::sleep(Duration::from_millis(20));
        }
        assert!(
            !std::path::Path::new(&format!("/proc/{old_pid}")).exists(),
            "hibernated PTY process {old_pid} is still alive"
        );

        assert!(app
            .resume_agent_hibernated_surface(&background_surface)
            .expect("resume core PTY"));
        let new_pid = app.surfaces[&background_surface]
            .terminal
            .as_ref()
            .and_then(|terminal| terminal.pid())
            .expect("new terminal pid");
        assert_ne!(new_pid, old_pid);
        for _ in 0..50 {
            let output = app.surfaces[&background_surface]
                .buffer
                .lock()
                .map(|buffer| buffer.clone())
                .unwrap_or_default();
            if output.contains("CMUX_HIBERNATION_CORE_RESUMED") {
                break;
            }
            thread::sleep(Duration::from_millis(20));
        }
        assert!(app.surfaces[&background_surface]
            .buffer
            .lock()
            .expect("buffer")
            .contains("CMUX_HIBERNATION_CORE_RESUMED"));
        if let Some(terminal) = app.surfaces[&background_surface].terminal.as_ref() {
            let _ = terminal.kill();
        }
    }

    #[test]
    fn remote_tmux_manual_surface_queues_output_without_starting_local_pty() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let host = RemoteTmuxHostSpec {
            destination: "remote.example".to_string(),
            port: None,
            identity_file: None,
        };
        app.ensure_remote_tmux_session(&host, "work");
        let window_id = app.current_window.clone();
        let mirrored = app
            .remote_tmux_mirror_session_in_window(&host, "work", &window_id, false, None)
            .expect("mirror");
        let surface_id = mirrored["surface_id"]
            .as_str()
            .expect("surface id")
            .to_string();
        let key = AppState::remote_tmux_connection_key(&host, "work");
        let layout = parse_remote_tmux_layout("80x24,0,0,7").expect("layout");
        let connection = app
            .remote_tmux_connections
            .get_mut(&key)
            .expect("connection");
        connection.window_count = 1;
        connection.window_ids = vec![3];
        connection.active_window_id = Some(3);
        connection.windows.insert(
            3,
            RemoteTmuxWindowState {
                id: 3,
                index: 0,
                name: "main".to_string(),
                active: true,
                layout: Some(layout),
                active_pane_id: Some(7),
            },
        );
        app.reconcile_remote_tmux_surfaces(&key);

        assert!(app.surfaces[&surface_id].terminal.is_none());
        assert!(!app
            .ensure_surface_terminal_started(&surface_id)
            .expect("ensure terminal"));
        app.apply_remote_tmux_output(&key, 7, b"remote output\r\n");
        assert!(app.surfaces[&surface_id]
            .buffer
            .lock()
            .expect("buffer")
            .contains("remote output"));
        assert_eq!(
            app.drain_embedded_terminal_input(&surface_id)
                .expect("drain"),
            vec![EmbeddedTerminalInput::ProcessOutput(
                b"remote output\r\n".to_vec()
            )]
        );
    }

    #[test]
    fn remote_tmux_nested_layout_projects_independent_panes_and_output() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let host = RemoteTmuxHostSpec {
            destination: "remote.example".to_string(),
            port: None,
            identity_file: None,
        };
        app.ensure_remote_tmux_session(&host, "work");
        let window_id = app.current_window.clone();
        let mirrored = app
            .remote_tmux_mirror_session_in_window(&host, "work", &window_id, false, None)
            .expect("mirror");
        let workspace_id = mirrored["workspace_id"]
            .as_str()
            .expect("workspace id")
            .to_string();
        let key = AppState::remote_tmux_connection_key(&host, "work");
        let layout = parse_remote_tmux_layout(
            "120x40,0,0{60x40,0,0,4,59x40,61,0[59x20,61,0,5,59x19,61,21,8]}",
        )
        .expect("nested layout");
        let connection = app
            .remote_tmux_connections
            .get_mut(&key)
            .expect("connection");
        connection.window_count = 1;
        connection.window_ids = vec![3];
        connection.active_window_id = Some(3);
        connection.windows.insert(
            3,
            RemoteTmuxWindowState {
                id: 3,
                index: 0,
                name: "main".to_string(),
                active: true,
                layout: Some(layout),
                active_pane_id: Some(8),
            },
        );
        app.reconcile_remote_tmux_surfaces(&key);

        assert_eq!(app.workspaces[&workspace_id].panes.len(), 3);
        let connection = &app.remote_tmux_connections[&key];
        assert_eq!(connection.surface_id_by_pane.len(), 3);
        assert_eq!(connection.local_pane_id_by_tmux_pane.len(), 3);
        let left_local = &connection.local_pane_id_by_tmux_pane[&4];
        let top_right_local = &connection.local_pane_id_by_tmux_pane[&5];
        let bottom_right_local = &connection.local_pane_id_by_tmux_pane[&8];
        assert_eq!(
            app.workspaces[&workspace_id].selected_pane.as_deref(),
            Some(bottom_right_local.as_str())
        );

        let frames = app
            .workspace_debug_frames(&workspace_id)
            .expect("workspace frames");
        let left = frames[left_local];
        let top_right = frames[top_right_local];
        let bottom_right = frames[bottom_right_local];
        assert_eq!(left.x, 0.0);
        assert_eq!(top_right.y, 0.0);
        assert!(top_right.x > left.x + left.width);
        assert_eq!(top_right.x, bottom_right.x);
        assert!(bottom_right.y > top_right.y + top_right.height);
        assert_eq!(left.height, debug_container_frame().height);

        let top_right_surface = connection.surface_id_by_pane[&5].clone();
        app.apply_remote_tmux_output(&key, 5, b"pane five\r\n");
        assert!(app.surfaces[&top_right_surface]
            .buffer
            .lock()
            .expect("buffer")
            .contains("pane five"));
        assert_eq!(
            app.drain_embedded_terminal_input(&top_right_surface)
                .expect("drain input"),
            vec![EmbeddedTerminalInput::ProcessOutput(
                b"pane five\r\n".to_vec()
            )]
        );
    }

