    #[test]
    fn embedded_terminal_app_config_and_readonly_actions_update_model() {
        let (mut app, surface_id, surface_ref, workspace_id) = app_with_current_surface();
        let window_id = app.workspaces[&workspace_id].window_id.clone();

        let palette = app
            .toggle_embedded_terminal_command_palette(&surface_ref)
            .expect("toggle palette");
        assert_eq!(palette["visible"], true);
        assert_eq!(palette["mode"], "commands");
        let visible = app
            .handle(
                "debug.command_palette.visible",
                &json!({"window_id": window_id}),
            )
            .expect("palette visible");
        assert_eq!(visible["visible"], true);

        let overview = app
            .toggle_embedded_terminal_tab_overview(&surface_ref)
            .expect("toggle tab overview");
        assert_eq!(overview["visible"], true);
        assert_eq!(overview["mode"], "switcher");

        let opened = app
            .open_embedded_terminal_config(&surface_ref)
            .expect("open config");
        let opened_surface_id = opened["surface_id"].as_str().expect("opened surface");
        assert_ne!(opened_surface_id, surface_id);
        assert!(matches!(
            app.surfaces[opened_surface_id].kind,
            SurfaceKind::FilePreview | SurfaceKind::Settings
        ));

        assert!(app
            .reload_embedded_terminal_config(&surface_ref, true)
            .expect("reload config"));
        assert_eq!(
            app.surfaces[&surface_id].embedded_terminal_config_reload_count,
            1
        );
        assert_eq!(
            app.surfaces[&surface_id].embedded_terminal_last_config_reload_soft,
            Some(true)
        );

        assert!(app
            .set_embedded_terminal_readonly(&surface_ref, true)
            .expect("readonly on"));
        assert!(!app
            .set_embedded_terminal_readonly(&surface_ref, true)
            .expect("readonly unchanged"));

        let surfaces = app
            .handle(
                "surface.list",
                &json!({"workspace_id": workspace_id.clone()}),
            )
            .expect("surface list");
        let terminal = surfaces["surfaces"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["surface_id"] == surface_id)
            .expect("surface row");
        assert_eq!(terminal["terminal_readonly"], true);
        assert_eq!(terminal["terminal_config_reload_count"], 1);
        assert_eq!(terminal["terminal_last_config_reload_soft"], true);

        let terminals = app
            .handle("debug.terminals", &json!({}))
            .expect("debug terminals");
        let terminal = terminals["terminals"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["surface_id"] == surface_id)
            .expect("terminal row");
        assert_eq!(terminal["readonly"], true);
        assert_eq!(terminal["terminal_config_reload_count"], 1);
    }

    #[test]
    fn config_reload_advances_renderer_snapshot_generation() {
        let (mut app, _surface_id, _surface_ref, _workspace_id) = app_with_current_surface();
        assert_eq!(app.config_reload_generation(), 0);

        let reloaded = app
            .handle("config.reload", &json!({}))
            .expect("config reload");
        assert_eq!(reloaded["text"], "OK Reloaded config");
        assert_eq!(reloaded["reload_generation"], 1);
        assert_eq!(reloaded["config_reload_generation"], 1);
        assert_eq!(app.config_reload_generation(), 1);

        let snapshot =
            crate::renderer::snapshot_value(&mut app, &json!({})).expect("renderer snapshot");
        assert_eq!(snapshot["config"]["reload_generation"], 1);
        assert_eq!(snapshot["config"]["config_reload_generation"], 1);

        let legacy = app
            .handle_legacy_v1("reload_config")
            .expect("legacy reload");
        assert_eq!(legacy, "OK Reloaded config");
        assert_eq!(app.config_reload_generation(), 2);
    }

    #[test]
    fn feed_list_limit_returns_latest_filtered_items_in_chronological_order() {
        let (mut app, _surface_id, _surface_ref, _workspace_id) = app_with_current_surface();
        app.feed_items = vec![
            json!({"id": "one", "status": "pending"}),
            json!({"id": "two", "status": "resolved"}),
            json!({"id": "three", "status": "pending"}),
            json!({"id": "four", "status": "pending"}),
        ];

        let latest = app
            .handle("feed.list", &json!({"limit": 2}))
            .expect("latest feed items");
        assert_eq!(latest["items"][0]["id"], "three");
        assert_eq!(latest["items"][1]["id"], "four");

        let latest_pending = app
            .handle("feed.list", &json!({"pending_only": true, "limit": 2}))
            .expect("latest pending feed items");
        assert_eq!(latest_pending["items"][0]["id"], "three");
        assert_eq!(latest_pending["items"][1]["id"], "four");

        let empty = app
            .handle("feed.list", &json!({"limit": 0}))
            .expect("empty feed limit");
        assert_eq!(empty["items"], json!([]));
    }

    #[test]
    fn beta_feature_runtime_normalizes_modes_and_suppresses_custom_provider() {
        let (mut app, _surface_id, _surface_ref, _workspace_id) = app_with_current_surface();
        let window_id = app.current_window.clone();
        app.sidebar_mode_by_window
            .insert(window_id.clone(), "feed".to_string());
        app.custom_sidebar_selected_provider_id = "cmux.sidebar.custom.saved".to_string();
        app.set_beta_feature_settings_for_test(crate::config::BetaFeatureSettings {
            custom_sidebars: false,
            ..crate::config::BetaFeatureSettings::default()
        });

        assert_eq!(app.sidebar_mode_by_window[&window_id], "files");
        let disabled = app
            .handle("sidebar.right", &json!({"action": "set", "mode": "feed"}))
            .expect_err("disabled feed");
        assert_eq!(disabled.code, "unavailable");

        let custom = app.custom_sidebar_snapshot();
        assert_eq!(custom["enabled"], false);
        assert_eq!(custom["providers"], json!([]));
        assert_eq!(
            custom["configured_selected_provider_id"],
            "cmux.sidebar.custom.saved"
        );
        assert_eq!(
            app.custom_sidebar_selected_provider_id,
            "cmux.sidebar.custom.saved"
        );

        app.custom_sidebar_selected_provider_id =
            crate::sidebar_extension::HOSTED_PROVIDER_ID.to_string();
        app.set_beta_feature_settings_for_test(crate::config::BetaFeatureSettings {
            extensions: false,
            custom_sidebars: true,
            ..crate::config::BetaFeatureSettings::default()
        });
        let unavailable_extension = app.custom_sidebar_snapshot();
        assert_eq!(
            unavailable_extension["selected_provider_id"],
            crate::custom_sidebar::DEFAULT_PROVIDER_ID
        );
        assert_eq!(
            unavailable_extension["configured_selected_provider_id"],
            crate::sidebar_extension::HOSTED_PROVIDER_ID
        );
        assert_eq!(
            app.custom_sidebar_selected_provider_id,
            crate::sidebar_extension::HOSTED_PROVIDER_ID
        );
    }

