    #[test]
    fn native_window_close_request_quits_last_window_and_closes_additional_windows() {
        let (mut app, _surface_id, surface_ref, workspace_id) = app_with_current_surface();
        let first_window_id = app.workspaces[&workspace_id].window_id.clone();
        app.app_workspace_settings.confirm_quit = ConfirmQuitPolicy::Never;

        let last = app
            .handle(
                "debug.window.close_request",
                &json!({"window_id": first_window_id}),
            )
            .expect("last window close request");
        assert_eq!(last["closed"], true);
        assert_eq!(last["quit"], true);
        assert_eq!(app.windows.len(), 1);

        app.update_embedded_terminal_close_confirmation(&surface_ref, true)
            .expect("set close confirmation");
        app.app_workspace_settings.confirm_quit = ConfirmQuitPolicy::DirtyOnly;
        let blocked = app
            .handle(
                "debug.window.close_request",
                &json!({"window_id": first_window_id}),
            )
            .expect("blocked native close request");
        assert_eq!(blocked["blocked"], true);
        assert_eq!(blocked["reason"], "needs_confirm");

        app.update_embedded_terminal_close_confirmation(&surface_ref, false)
            .expect("clear close confirmation");
        app.handle("window.create", &json!({"title": "Second"}))
            .expect("create second window");
        let closed = app
            .handle(
                "debug.window.close_request",
                &json!({"window_id": first_window_id}),
            )
            .expect("close first window");
        assert_eq!(closed["closed"], true);
        assert_eq!(closed["quit"], false);
        assert_eq!(app.windows.len(), 1);
        assert!(!app
            .windows
            .iter()
            .any(|window| window.id == first_window_id));
    }

    #[test]
    fn fullscreen_is_per_window_and_quit_checks_all_terminal_confirmations() {
        let (mut app, surface_id, _surface_ref, _) = app_with_current_surface();
        let first_window_id = app.current_window.clone();
        let entered = app
            .execute_shortcut_name("toggle_full_screen")
            .expect("enter fullscreen");
        assert_eq!(entered["fullscreen"], true);
        assert!(
            app.windows
                .iter()
                .find(|window| window.id == first_window_id)
                .unwrap()
                .fullscreen
        );

        let second = app
            .handle("window.create", &json!({"title": "Second"}))
            .expect("second window");
        let second_window_id = second["window_id"].as_str().unwrap().to_string();
        assert!(
            !app.windows
                .iter()
                .find(|window| window.id == second_window_id)
                .unwrap()
                .fullscreen
        );
        app.handle(
            "window.fullscreen.set",
            &json!({"window_id": second_window_id, "fullscreen": true}),
        )
        .expect("set second fullscreen");
        assert!(
            app.windows
                .iter()
                .find(|window| window.id == second_window_id)
                .unwrap()
                .fullscreen
        );

        let quit = app.execute_shortcut_name("quit").expect("quit request");
        assert_eq!(quit["quit"], false);
        assert_eq!(quit["blocked"], true);
        let confirmation_id = quit["confirmation"]["id"]
            .as_str()
            .expect("quit confirmation")
            .to_string();
        let confirmed = app
            .handle(
                "app.close_confirmation.reply",
                &json!({"id": confirmation_id, "confirmed": true}),
            )
            .expect("confirm quit");
        assert_eq!(confirmed["quit"], true);
        assert_eq!(
            app.drain_global_window_commands(),
            vec![GlobalWindowCommand::Quit]
        );
        assert_eq!(
            app.windows.len(),
            2,
            "quit request must not mutate socket state"
        );

        app.update_embedded_terminal_close_confirmation(&surface_id, true)
            .expect("set confirmation");
        app.app_workspace_settings.confirm_quit = ConfirmQuitPolicy::DirtyOnly;
        let blocked = app.execute_shortcut_name("quit").expect("blocked quit");
        assert_eq!(blocked["quit"], false);
        assert_eq!(blocked["blocked"], true);
        assert_eq!(blocked["reason"], "needs_confirm");
        assert!(app.drain_global_window_commands().is_empty());
        assert!(
            blocked["blocked_window_ids"]
                .as_array()
                .unwrap()
                .iter()
                .any(|id| id.as_str() == Some(first_window_id.as_str())),
            "blocked response was {blocked}"
        );
        assert!(app.surfaces.contains_key(&surface_id));
    }

