    #[test]
    fn embedded_terminal_search_updates_metadata() {
        let (mut app, surface_id, surface_ref, workspace_id) = app_with_current_surface();

        assert!(!app
            .update_embedded_terminal_search_total(&surface_ref, None)
            .expect("empty search total without active search"));
        assert_eq!(app.surfaces[&surface_id].embedded_terminal_search, None);

        assert!(app
            .start_embedded_terminal_search(&surface_ref, "needle")
            .expect("start search"));
        assert!(app
            .update_embedded_terminal_search_total(&surface_ref, Some(3))
            .expect("search total"));
        assert!(app
            .update_embedded_terminal_search_selected(&surface_ref, Some(1))
            .expect("search selected"));
        assert_eq!(
            app.surfaces[&surface_id].embedded_terminal_search,
            Some(EmbeddedTerminalSearch {
                needle: "needle".to_string(),
                total: Some(3),
                selected: Some(1)
            })
        );

        let surfaces = app
            .handle("surface.list", &json!({"workspace_id": workspace_id}))
            .expect("surface list");
        let terminal = surfaces["surfaces"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["surface_id"] == surface_id)
            .expect("surface row");
        assert_eq!(terminal["terminal_search"]["active"], true);
        assert_eq!(terminal["terminal_search"]["query"], "needle");
        assert_eq!(terminal["terminal_search"]["total"], 3);
        assert_eq!(terminal["terminal_search"]["selected"], 1);

        assert!(app
            .update_embedded_terminal_search_total(&surface_ref, None)
            .expect("clear search total"));
        let terminals = app
            .handle("debug.terminals", &json!({}))
            .expect("debug terminals");
        let terminal = terminals["terminals"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["surface_id"] == surface_id)
            .expect("terminal row");
        assert_eq!(terminal["terminal_search"]["total"], json!(null));
        assert_eq!(terminal["terminal_search"]["selected"], 1);

        assert!(app
            .end_embedded_terminal_search(&surface_ref)
            .expect("end search"));
        assert_eq!(app.surfaces[&surface_id].embedded_terminal_search, None);
    }

