    #[test]
    fn embedded_terminal_layout_actions_create_and_focus_surfaces() {
        let (mut app, surface_id, surface_ref, workspace_id) = app_with_current_surface();
        let source_pane_id = app.surfaces[&surface_id].pane_id.clone();

        let created_tab = app
            .perform_embedded_terminal_layout_action(&surface_ref, "new_tab", None, None)
            .expect("new tab")
            .expect("created tab");
        let tab_surface_id = created_tab["surface_id"].as_str().expect("tab surface");
        assert_ne!(tab_surface_id, surface_id);
        assert_eq!(app.surfaces[tab_surface_id].pane_id, source_pane_id);
        assert_eq!(
            app.workspace_selected_surface(&workspace_id).as_deref(),
            Some(tab_surface_id)
        );

        let presented = app
            .perform_embedded_terminal_layout_action(&surface_ref, "present_terminal", None, None)
            .expect("present")
            .expect("presented");
        assert_eq!(presented["surface_id"], surface_id);
        assert_eq!(
            app.workspace_selected_surface(&workspace_id).as_deref(),
            Some(surface_id.as_str())
        );

        let split = app
            .perform_embedded_terminal_layout_action(&surface_ref, "new_split", Some("down"), None)
            .expect("new split")
            .expect("created split");
        let split_surface_id = split["surface_id"].as_str().expect("split surface");
        let split_pane_id = split["pane_id"].as_str().expect("split pane");
        assert_ne!(split_surface_id, surface_id);
        assert_ne!(split_pane_id, source_pane_id);
        assert_eq!(app.surfaces[split_surface_id].pane_id, split_pane_id);
        assert_eq!(
            app.workspace_selected_surface(&workspace_id).as_deref(),
            Some(split_surface_id)
        );
    }

