    #[test]
    fn closing_nested_split_restores_its_parent_branch_width() {
        let (mut app, surface_id, _surface_ref, workspace_id) = app_with_current_surface();
        let source_pane_id = app.surfaces[&surface_id].pane_id.clone();
        let outer = app
            .handle(
                "surface.split",
                &json!({"surface_id": surface_id, "direction": "right", "focus": false}),
            )
            .expect("outer split");
        let outer_pane_id = outer["pane_id"].as_str().expect("outer pane").to_string();
        let nested = app
            .handle(
                "surface.split",
                &json!({"surface_id": surface_id, "direction": "right", "focus": false}),
            )
            .expect("nested split");
        let nested_surface_id = nested["surface_id"]
            .as_str()
            .expect("nested surface")
            .to_string();
        let nested_pane_id = nested["pane_id"].as_str().expect("nested pane").to_string();

        app.resize_pane(&json!({
            "pane_id": source_pane_id,
            "direction": "right",
            "amount": 80
        }))
        .expect("resize nested split");
        let resized = app
            .workspace_debug_frames(&workspace_id)
            .expect("resized frames");
        assert_eq!(resized[&source_pane_id].width, 280.0);
        let parent_branch_width = resized[&source_pane_id].width + resized[&nested_pane_id].width;
        let outer_frame = resized[&outer_pane_id];
        assert_eq!(outer_frame.x, parent_branch_width);

        app.handle("surface.close", &json!({"surface_id": nested_surface_id}))
            .expect("close nested split");
        let collapsed = app
            .workspace_debug_frames(&workspace_id)
            .expect("collapsed frames");
        assert!(!collapsed.contains_key(&nested_pane_id));
        assert_eq!(collapsed[&source_pane_id].x, 0.0);
        assert_eq!(collapsed[&source_pane_id].width, parent_branch_width);
        let collapsed_outer = collapsed[&outer_pane_id];
        assert!((collapsed_outer.x - outer_frame.x).abs() < 1e-9);
        assert!((collapsed_outer.width - outer_frame.width).abs() < 1e-9);
        assert_eq!(collapsed_outer.y, outer_frame.y);
        assert_eq!(collapsed_outer.height, outer_frame.height);
    }

    #[test]
    fn embedded_terminal_layout_actions_close_focus_resize_and_equalize() {
        let (mut app, surface_id, surface_ref, workspace_id) = app_with_current_surface();
        let source_pane_id = app.surfaces[&surface_id].pane_id.clone();

        let tab = app
            .perform_embedded_terminal_layout_action(&surface_ref, "new_tab", None, None)
            .expect("new tab")
            .expect("created tab");
        let tab_surface_id = tab["surface_id"].as_str().expect("tab surface").to_string();
        let split = app
            .perform_embedded_terminal_layout_action(&surface_ref, "new_split", Some("right"), None)
            .expect("new split")
            .expect("created split");
        let split_surface_id = split["surface_id"]
            .as_str()
            .expect("split surface")
            .to_string();
        let split_ref = app.surface_ref(&split_surface_id);
        let split_pane_id = app.surfaces[&split_surface_id].pane_id.clone();

        let focused = app
            .perform_embedded_terminal_layout_action(&surface_ref, "goto_split", Some("next"), None)
            .expect("goto split")
            .expect("focused split");
        assert_eq!(focused["pane_id"], split_pane_id);
        assert_eq!(
            app.workspace_selected_surface(&workspace_id).as_deref(),
            Some(split_surface_id.as_str())
        );

        let focused = app
            .perform_embedded_terminal_layout_action(
                &split_ref,
                "goto_split",
                Some("previous"),
                None,
            )
            .expect("goto previous")
            .expect("focused source");
        assert_eq!(focused["pane_id"], source_pane_id);
        assert_eq!(
            app.workspace_selected_surface(&workspace_id).as_deref(),
            Some(tab_surface_id.as_str())
        );

        let resized = app
            .perform_embedded_terminal_layout_action(
                &surface_ref,
                "resize_split",
                Some("right"),
                Some(40),
            )
            .expect("resize split")
            .expect("resized split");
        assert_eq!(resized["pane_id"], source_pane_id);
        assert_eq!(resized["amount"], 40.0);
        assert_eq!(
            app.surfaces[&surface_id]
                .embedded_terminal_last_layout_action
                .as_ref()
                .map(|record| (
                    record.action.as_str(),
                    record.value.as_deref(),
                    record.amount
                )),
            Some(("resize_split", Some("right"), Some(40)))
        );
        let resized_frames = app
            .workspace_debug_frames(&workspace_id)
            .expect("resized frames");
        let source_frame = resized_frames[&source_pane_id];
        let split_frame = resized_frames[&split_pane_id];
        assert!(source_frame.width > 400.0, "source pane should grow");
        assert_eq!(source_frame.x + source_frame.width, split_frame.x);
        assert_eq!(split_frame.x + split_frame.width, 800.0);

        let equalized = app
            .perform_embedded_terminal_layout_action(&surface_ref, "equalize_splits", None, None)
            .expect("equalize")
            .expect("equalized splits");
        assert_eq!(equalized["workspace_id"], workspace_id);
        assert_eq!(equalized["equalized"], true);
        assert!(app.workspaces[&workspace_id].debug_column_sizes.is_empty());

        let close_right_request = app
            .perform_embedded_terminal_layout_action(&surface_ref, "close_tab", Some("right"), None)
            .expect("close right")
            .expect("close right request");
        assert_eq!(close_right_request["blocked"], true);
        let confirmation_id = close_right_request["confirmation"]["id"]
            .as_str()
            .expect("batch close confirmation")
            .to_string();
        let closed_right = app
            .handle(
                "app.close_confirmation.reply",
                &json!({"id": confirmation_id, "confirmed": true}),
            )
            .expect("confirm close right");
        assert_eq!(closed_right["closed"], 1);
        assert!(!app.surfaces.contains_key(&tab_surface_id));
        assert_eq!(
            app.panes[&source_pane_id].surfaces,
            vec![surface_id.clone()]
        );

        let closed_split = app
            .perform_embedded_terminal_layout_action(
                &split_surface_id,
                "close_tab",
                Some("this"),
                None,
            )
            .expect("close split")
            .expect("closed split");
        assert_eq!(closed_split["surface_id"], split_surface_id);
        assert!(!app.surfaces.contains_key(&split_surface_id));
        assert!(!app.panes.contains_key(&split_pane_id));
    }

    #[test]
    fn embedded_terminal_layout_actions_toggle_split_zoom_updates_layout() {
        let (mut app, surface_id, surface_ref, workspace_id) = app_with_current_surface();
        let source_pane_id = app.surfaces[&surface_id].pane_id.clone();
        let split = app
            .perform_embedded_terminal_layout_action(&surface_ref, "new_split", Some("right"), None)
            .expect("new split")
            .expect("created split");
        let split_surface_id = split["surface_id"]
            .as_str()
            .expect("split surface")
            .to_string();
        let split_pane_id = app.surfaces[&split_surface_id].pane_id.clone();

        let zoomed = app
            .perform_embedded_terminal_layout_action(&surface_ref, "toggle_split_zoom", None, None)
            .expect("toggle split zoom")
            .expect("zoom payload");
        assert_eq!(zoomed["zoomed"], true);
        assert_eq!(zoomed["pane_id"], source_pane_id);
        assert_eq!(
            app.workspaces[&workspace_id].zoomed_pane.as_deref(),
            Some(source_pane_id.as_str())
        );

        let layout = app.layout_debug().expect("layout");
        assert_eq!(layout["layout"]["zoomed_pane_id"], source_pane_id);
        let panels = layout["selectedPanels"].as_array().expect("panels");
        let source_panel = panels
            .iter()
            .find(|panel| panel["pane_id"] == source_pane_id)
            .expect("source panel");
        assert_eq!(source_panel["hidden"], false);
        assert_eq!(source_panel["zoomed"], true);
        assert_eq!(
            source_panel["viewFrame"]["width"],
            json!(debug_container_frame().width)
        );
        let split_panel = panels
            .iter()
            .find(|panel| panel["pane_id"] == split_pane_id)
            .expect("split panel");
        assert_eq!(split_panel["hidden"], true);
        assert_eq!(split_panel["zoomed"], false);

        let unzoomed = app
            .perform_embedded_terminal_layout_action(&surface_ref, "toggle_split_zoom", None, None)
            .expect("toggle split zoom off")
            .expect("unzoom payload");
        assert_eq!(unzoomed["zoomed"], false);
        assert_eq!(app.workspaces[&workspace_id].zoomed_pane, None);
    }

