    #[test]
    fn browser_profile_history_stays_bounded_after_import_merge() {
        let (mut profiles, profile_id) = default_browser_profiles();
        let profile = profiles.get_mut(&profile_id).expect("default profile");
        profile.history = (0..MAX_BROWSER_HISTORY_ENTRIES)
            .map(|index| BrowserHistoryEntry {
                id: Uuid::new_v4().to_string(),
                url: format!("https://history-{index}.example.test/page"),
                title: Some(format!("History {index}")),
                last_visited_ms: index as i64,
                visit_count: 1,
            })
            .collect();

        let merged = merge_browser_history_entries(
            profile,
            vec![BrowserImportHistoryEntry {
                url: "https://newest.example.test/page".to_string(),
                title: Some("Newest".to_string()),
                last_visited_ms: i64::MAX,
                visit_count: 9,
            }],
            false,
        );

        assert_eq!(merged, 1);
        assert_eq!(profile.history.len(), MAX_BROWSER_HISTORY_ENTRIES);
        assert_eq!(profile.history[0].title.as_deref(), Some("Newest"));
        assert!(!profile
            .history
            .iter()
            .any(|entry| entry.url == "https://history-0.example.test/page"));
    }

