    #[test]
    fn browser_automation_queues_native_webkit_actions_and_preserves_sequence_on_navigation() {
        let (mut app, _surface_id, surface_ref, _workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&surface_ref, "https://example.test/form")
            .expect("open url")
            .expect("opened browser");
        let browser_id = opened["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();

        app.handle(
            "browser.fill",
            &json!({
                "surface_id": browser_id,
                "selector": "#field[data-name=\"quoted\"]",
                "text": "native value"
            }),
        )
        .expect("queue native fill");
        app.handle(
            "browser.addstyle",
            &json!({"surface_id": browser_id, "css": "body { background: rgb(0, 128, 0); }"}),
        )
        .expect("queue native style");

        let preview = browser_surface_preview_value(&app.surfaces[&browser_id]);
        let actions = preview["runtime_actions"]
            .as_array()
            .expect("runtime actions");
        assert_eq!(actions.len(), 2);
        assert_eq!(actions[0]["sequence"], 1);
        assert_eq!(actions[1]["sequence"], 2);
        assert!(actions[0]["script"]
            .as_str()
            .expect("fill script")
            .contains("native value"));
        assert!(actions[1]["script"]
            .as_str()
            .expect("style script")
            .contains("rgb(0, 128, 0)"));

        app.handle(
            "browser.navigate",
            &json!({"surface_id": browser_id, "url": "https://example.test/next"}),
        )
        .expect("navigate browser");
        assert!(app.surfaces[&browser_id].browser.runtime_actions.is_empty());
        app.handle("browser.focus_webview", &json!({"surface_id": browser_id}))
            .expect("queue native focus");
        let action = app.surfaces[&browser_id]
            .browser
            .runtime_actions
            .back()
            .expect("focus action");
        assert_eq!(action.sequence, 3);
        assert!(action.focus_webview);
    }

    #[test]
    fn browser_drag_queues_native_source_target_and_data_transfer_events() {
        let (mut app, _surface_id, surface_ref, _workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&surface_ref, "about:blank")
            .expect("open url")
            .expect("opened browser");
        let browser_id = opened["surface_id"].as_str().expect("browser id");
        app.handle(
            "browser.setcontent",
            &json!({
                "surface_id": browser_id,
                "html": "<div id='source' draggable='true'>source</div><div id='target'>target</div>"
            }),
        )
        .expect("set drag content");
        app.handle(
            "browser.drag",
            &json!({
                "surface_id": browser_id,
                "source": "#source",
                "to": "#target",
                "start_x": 4,
                "start_y": 5,
                "end_x": 40,
                "end_y": 50
            }),
        )
        .expect("queue native drag");

        let action = app.surfaces[browser_id]
            .browser
            .runtime_actions
            .back()
            .expect("drag action");
        assert!(action.script.contains("\"selector\":\"#source\""));
        assert!(action.script.contains("\"targetSelector\":\"#target\""));
        assert!(action.script.contains("new DataTransfer()"));
        for event_type in ["dragstart", "dragenter", "dragover", "drop", "dragend"] {
            assert!(action.script.contains(event_type), "missing {event_type}");
        }
    }

    #[test]
    fn browser_upload_queues_native_file_selection_before_input_click() {
        let (mut app, _surface_id, surface_ref, _workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&surface_ref, "about:blank")
            .expect("open url")
            .expect("opened browser");
        let browser_id = opened["surface_id"].as_str().expect("browser id");
        app.handle(
            "browser.setcontent",
            &json!({
                "surface_id": browser_id,
                "html": "<input id='file' type='file' multiple>"
            }),
        )
        .expect("set upload content");
        let temp = tempfile::tempdir().expect("upload tempdir");
        let first = temp.path().join("first upload.txt");
        let second = temp.path().join("second upload.txt");
        std::fs::write(&first, "first").expect("write first upload");
        std::fs::write(&second, "second").expect("write second upload");

        app.handle(
            "browser.upload",
            &json!({
                "surface_id": browser_id,
                "selector": "#file",
                "files": [first, second]
            }),
        )
        .expect("queue native upload");

        let action = app.surfaces[browser_id]
            .browser
            .runtime_actions
            .back()
            .expect("upload action");
        assert!(action.script.contains("case 'browser.upload'"));
        assert!(action.script.contains("el.click()"));
        assert_eq!(
            action.upload.as_ref().expect("native upload").files,
            vec![
                first.to_string_lossy().into_owned(),
                second.to_string_lossy().into_owned()
            ]
        );
    }

    #[test]
    fn browser_native_configuration_preserves_user_agent_and_init_scripts_on_navigation() {
        let (mut app, _surface_id, surface_ref, _workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&surface_ref, "https://example.test/start")
            .expect("open url")
            .expect("opened browser");
        let browser_id = opened["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();

        app.handle(
            "browser.useragent.set",
            &json!({"surface_id": browser_id, "user_agent": "cmux-native/1.0"}),
        )
        .expect("set user agent");
        app.handle(
            "browser.locale.set",
            &json!({"surface_id": browser_id, "locale": "nl-NL"}),
        )
        .expect("set locale");
        app.handle(
            "browser.timezone.set",
            &json!({"surface_id": browser_id, "timezone": "Europe/Amsterdam"}),
        )
        .expect("set timezone");
        app.handle(
            "browser.media.set",
            &json!({
                "surface_id": browser_id,
                "media_type": "print",
                "color_scheme": "dark",
                "reduced_motion": "reduce"
            }),
        )
        .expect("set media");
        app.handle(
            "browser.offline.set",
            &json!({"surface_id": browser_id, "enabled": true}),
        )
        .expect("set offline");
        app.handle(
            "browser.geolocation.set",
            &json!({
                "surface_id": browser_id,
                "latitude": 52.37,
                "longitude": 4.90,
                "accuracy": 8.0
            }),
        )
        .expect("set geolocation");
        app.handle(
            "browser.device.set",
            &json!({
                "surface_id": browser_id,
                "device_scale_factor": 2.0,
                "mobile": true,
                "touch": true
            }),
        )
        .expect("set device environment");
        app.handle(
            "browser.permissions.set",
            &json!({
                "surface_id": browser_id,
                "permission": "geolocation",
                "state": "granted"
            }),
        )
        .expect("set permission");
        let init = app
            .handle(
                "browser.addinitscript",
                &json!({
                    "surface_id": browser_id,
                    "script": "window.__cmuxNativeInit = 'ready';"
                }),
            )
            .expect("add init script");
        assert_eq!(init["script_count"], 1);

        let preview = browser_surface_preview_value(&app.surfaces[&browser_id]);
        assert_eq!(preview["user_agent"], "cmux-native/1.0");
        assert_eq!(
            preview["init_scripts"],
            json!(["window.__cmuxNativeInit = 'ready';"])
        );
        assert_eq!(preview["environment"]["locale"], "nl-NL");
        assert_eq!(preview["environment"]["timezone"], "Europe/Amsterdam");
        assert_eq!(preview["environment"]["media_type"], "print");
        assert_eq!(preview["environment"]["color_scheme"], "dark");
        assert_eq!(preview["environment"]["reduced_motion"], "reduce");
        assert_eq!(preview["environment"]["offline"], true);
        assert_eq!(preview["environment"]["geolocation"]["latitude"], 52.37);
        assert_eq!(preview["environment"]["mobile"], true);
        assert_eq!(preview["environment"]["touch"], true);
        assert_eq!(preview["environment"]["device_scale_factor"], 2.0);
        assert_eq!(
            preview["environment"]["permissions"]["geolocation"],
            "granted"
        );
        assert_eq!(preview["runtime_actions"].as_array().map(Vec::len), Some(1));

        app.handle(
            "browser.navigate",
            &json!({"surface_id": browser_id, "url": "https://example.test/next"}),
        )
        .expect("navigate browser");
        let preview = browser_surface_preview_value(&app.surfaces[&browser_id]);
        assert_eq!(preview["user_agent"], "cmux-native/1.0");
        assert_eq!(
            preview["init_scripts"],
            json!(["window.__cmuxNativeInit = 'ready';"])
        );
        assert_eq!(preview["environment"]["locale"], "nl-NL");
        assert_eq!(preview["environment"]["offline"], true);
        assert_eq!(
            preview["environment"]["permissions"]["geolocation"],
            "granted"
        );
        assert!(preview["runtime_actions"]
            .as_array()
            .is_some_and(Vec::is_empty));
    }

    #[test]
    fn browser_native_request_configuration_tracks_headers_credentials_and_navigation() {
        let (mut app, _surface_id, surface_ref, _workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&surface_ref, "https://example.test/start")
            .expect("open url")
            .expect("opened browser");
        let browser_id = opened["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();

        app.handle(
            "browser.headers.set",
            &json!({
                "surface_id": browser_id,
                "headers": {"X-Cmux-Native": "header-value"}
            }),
        )
        .expect("set headers");
        app.handle(
            "browser.credentials.set",
            &json!({
                "surface_id": browser_id,
                "username": "runtime-agent",
                "password": "runtime-secret"
            }),
        )
        .expect("set credentials");

        let preview = browser_surface_preview_value(&app.surfaces[&browser_id]);
        assert_eq!(preview["request_configuration_generation"], 2);
        let serialized = preview.to_string();
        assert!(!serialized.contains("runtime-agent"));
        assert!(!serialized.contains("runtime-secret"));
        assert!(!serialized.contains("header-value"));

        let (headers, credentials) = app
            .browser_native_request_configuration(&browser_id)
            .expect("native request configuration");
        assert_eq!(
            headers,
            vec![
                ("X-Cmux-Native".to_string(), "header-value".to_string()),
                (
                    "Authorization".to_string(),
                    "Basic cnVudGltZS1hZ2VudDpydW50aW1lLXNlY3JldA==".to_string()
                )
            ]
        );
        assert_eq!(
            credentials,
            Some(("runtime-agent".to_string(), "runtime-secret".to_string()))
        );

        app.handle(
            "browser.navigate",
            &json!({"surface_id": browser_id, "url": "https://example.test/next"}),
        )
        .expect("navigate browser");
        assert_eq!(
            app.surfaces[&browser_id]
                .browser
                .request_configuration_generation,
            2
        );
        assert_eq!(
            app.browser_native_request_configuration(&browser_id),
            Some((headers, credentials))
        );

        app.handle(
            "browser.headers.set",
            &json!({"surface_id": browser_id, "clear": true}),
        )
        .expect("clear headers");
        app.handle(
            "browser.credentials.set",
            &json!({"surface_id": browser_id, "clear": true}),
        )
        .expect("clear credentials");
        assert_eq!(
            app.browser_native_request_configuration(&browser_id),
            Some((Vec::new(), None))
        );
        assert_eq!(
            app.surfaces[&browser_id]
                .browser
                .request_configuration_generation,
            4
        );
    }

    #[test]
    fn browser_state_file_round_trips_native_schema_and_accepts_legacy_storage_map() {
        let (mut app, _surface_id, surface_ref, _workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&surface_ref, "https://example.test/account")
            .expect("open url")
            .expect("opened browser");
        let browser_id = opened["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();
        app.handle(
            "browser.cookies.set",
            &json!({"surface_id": browser_id, "name": "session", "value": "native"}),
        )
        .expect("set cookie");
        app.handle(
            "browser.storage.set",
            &json!({"surface_id": browser_id, "type": "local", "key": "alpha", "value": "one"}),
        )
        .expect("set local storage");
        app.handle(
            "browser.storage.set",
            &json!({"surface_id": browser_id, "type": "session", "key": "beta", "value": "two"}),
        )
        .expect("set session storage");

        let directory = tempfile::tempdir().expect("tempdir");
        let path = directory.path().join("state.json");
        app.handle(
            "browser.state.save",
            &json!({"surface_id": browser_id, "path": path}),
        )
        .expect("save state");
        let saved: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&path).expect("read state"))
                .expect("parse state");
        assert_eq!(saved["profile_id"], BROWSER_BUILT_IN_DEFAULT_PROFILE_ID);
        assert_eq!(saved["profile_data_generation"], 0);
        assert_eq!(saved["url"], "https://example.test/account");
        assert_eq!(saved["cookies"][0]["name"], "session");
        assert_eq!(saved["storage"]["local"]["alpha"], "one");
        assert_eq!(saved["storage"]["session"]["beta"], "two");
        assert!(saved["frame_selector"].is_null());

        app.handle(
            "browser.navigate",
            &json!({"surface_id": browser_id, "url": "https://example.test/other"}),
        )
        .expect("navigate away");
        let loaded = app
            .handle(
                "browser.state.load",
                &json!({"surface_id": browser_id, "path": path}),
            )
            .expect("load state");
        assert_eq!(loaded["loaded"], true);
        assert_eq!(loaded["url"], "https://example.test/account");
        let browser = &app.surfaces[&browser_id].browser;
        assert_eq!(
            browser.local_storage.get("alpha").map(String::as_str),
            Some("one")
        );
        assert_eq!(
            browser.session_storage.get("beta").map(String::as_str),
            Some("two")
        );
        assert!(browser.storage_generation >= 3);
        assert!(browser.runtime_actions.iter().any(|action| {
            action.cookie.as_ref().is_some_and(|cookie| {
                cookie.operation == "set" && cookie.name.as_deref() == Some("session")
            })
        }));

        let legacy_path = directory.path().join("legacy.json");
        std::fs::write(&legacy_path, r#"{"legacy":"restored"}"#).expect("write legacy");
        app.handle(
            "browser.state.load",
            &json!({"surface_id": browser_id, "path": legacy_path}),
        )
        .expect("load legacy state");
        let browser = &app.surfaces[&browser_id].browser;
        assert_eq!(
            browser.local_storage.get("legacy").map(String::as_str),
            Some("restored")
        );
        assert!(browser.session_storage.is_empty());
    }

    #[test]
    fn browser_cookie_commands_queue_native_actions_and_runtime_sync_replaces_model() {
        let (mut app, _surface_id, surface_ref, _workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&surface_ref, "https://example.test/account")
            .expect("open url")
            .expect("opened browser");
        let browser_id = opened["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();

        app.handle(
            "browser.cookies.set",
            &json!({
                "surface_id": browser_id,
                "name": "session",
                "value": "native-value",
                "domain": ".example.test",
                "path": "/account",
                "max_age": 3600
            }),
        )
        .expect("set cookie");
        app.handle(
            "browser.cookies.get",
            &json!({"surface_id": browser_id, "name": "session"}),
        )
        .expect("get cookies");
        app.handle(
            "browser.cookies.clear",
            &json!({"surface_id": browser_id, "name": "session"}),
        )
        .expect("clear cookie");

        let actions = &app.surfaces[&browser_id].browser.runtime_actions;
        assert_eq!(actions.len(), 3);
        assert_eq!(actions[0].script, "");
        assert_eq!(
            actions[0].cookie.as_ref().expect("set action").operation,
            "set"
        );
        assert_eq!(
            actions[0].cookie.as_ref().expect("set action").url,
            "https://example.test/account"
        );
        assert_eq!(
            actions[0]
                .cookie
                .as_ref()
                .expect("set action")
                .domain
                .as_deref(),
            Some(".example.test")
        );
        assert_eq!(
            actions[0].cookie.as_ref().expect("set action").max_age,
            Some(3600)
        );
        assert_eq!(
            actions[1].cookie.as_ref().expect("get action").operation,
            "get"
        );
        assert_eq!(
            actions[2].cookie.as_ref().expect("clear action").operation,
            "clear"
        );

        let synced = app
            .handle(
                "browser.runtime.sync",
                &json!({
                    "surface_id": browser_id,
                    "cookies": [
                        {"name": "session", "value": "from-webkit"},
                        {"name": "theme", "value": "dark"}
                    ]
                }),
            )
            .expect("sync native cookies");
        assert_eq!(synced["cookie_count"], 2);
        assert_eq!(
            app.surfaces[&browser_id].browser.cookies.get("session"),
            Some(&"from-webkit".to_string())
        );
        assert_eq!(
            app.surfaces[&browser_id].browser.cookies.get("theme"),
            Some(&"dark".to_string())
        );
    }

    #[test]
    fn recently_closed_browser_restores_same_pane_index_history_and_zoom() {
        let (mut app, terminal_id, _surface_ref, workspace_id) = app_with_current_surface();
        app.browser_enabled = true;
        let pane_id = app.surfaces[&terminal_id].pane_id.clone();
        let created = app
            .handle(
                "surface.create",
                &json!({
                    "workspace_id": workspace_id,
                    "pane_id": pane_id,
                    "type": "browser",
                    "url": "https://example.test/one",
                    "focus": true
                }),
            )
            .expect("create browser");
        let browser_id = created["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();
        app.load_browser_url(&browser_id, "https://example.test/one")
            .expect("load browser");
        app.handle(
            "browser.navigate",
            &json!({"surface_id": browser_id, "url": "https://example.test/two"}),
        )
        .expect("navigate browser");
        {
            let surface = app.surfaces.get_mut(&browser_id).expect("browser");
            surface.title = "Restorable Browser".to_string();
            surface.custom_title = true;
            surface.browser.page_zoom = 1.5;
        }
        let expected_history = app.surfaces[&browser_id].browser.history.clone();
        let expected_history_index = app.surfaces[&browser_id].browser.history_index;
        app.handle("surface.close", &json!({"surface_id": browser_id}))
            .expect("close browser");

        let reopened = app
            .execute_shortcut_name("reopen_closed_browser_panel")
            .expect("reopen browser");
        let reopened_id = reopened["surface_id"]
            .as_str()
            .expect("reopened id")
            .to_string();
        assert_eq!(reopened["handled"], true);
        assert_eq!(reopened["action"], "reopenClosedBrowserPanel");
        assert_eq!(reopened["restored_original_pane"], true);
        assert_ne!(reopened_id, browser_id);
        assert_eq!(app.surfaces[&reopened_id].pane_id, pane_id);
        assert_eq!(
            app.panes[&pane_id].surfaces,
            vec![terminal_id, reopened_id.clone()]
        );
        assert_eq!(
            app.panes[&pane_id].selected_surface.as_deref(),
            Some(reopened_id.as_str())
        );
        let surface = &app.surfaces[&reopened_id];
        assert_eq!(surface.title, "Restorable Browser");
        assert!(surface.custom_title);
        assert_eq!(surface.url.as_deref(), Some("https://example.test/two"));
        assert_eq!(surface.browser.history, expected_history);
        assert_eq!(surface.browser.history_index, expected_history_index);
        assert_eq!(surface.browser.page_zoom, 1.5);
    }

    #[test]
    fn recently_closed_browser_recreates_removed_split_and_skips_stale_workspace() {
        let (mut app, terminal_id, _surface_ref, workspace_id) = app_with_current_surface();
        app.browser_enabled = true;
        let source_pane_id = app.surfaces[&terminal_id].pane_id.clone();
        let opened = app
            .handle(
                "browser.open_split",
                &json!({
                    "workspace_id": workspace_id,
                    "surface_id": terminal_id,
                    "direction": "right",
                    "url": "https://example.test/split",
                    "focus": true
                }),
            )
            .expect("open split browser");
        let browser_id = opened["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();
        let removed_pane_id = opened["pane_id"].as_str().expect("pane id").to_string();
        app.handle("surface.close", &json!({"surface_id": browser_id}))
            .expect("close split browser");
        assert!(!app.panes.contains_key(&removed_pane_id));

        let reopened = app
            .handle("history.reopen_closed", &json!({}))
            .expect("reopen split browser");
        let reopened_id = reopened["surface_id"].as_str().expect("surface id");
        let reopened_pane_id = reopened["pane_id"].as_str().expect("pane id");
        assert_eq!(reopened["restored_original_pane"], false);
        assert_ne!(reopened_pane_id, removed_pane_id);
        assert_ne!(reopened_pane_id, source_pane_id);
        assert_eq!(app.workspaces[&workspace_id].panes.len(), 2);
        assert_eq!(
            app.surfaces[reopened_id].url.as_deref(),
            Some("https://example.test/split")
        );

        app.handle("surface.close", &json!({"surface_id": reopened_id}))
            .expect("close browser again");
        app.remove_workspace(&workspace_id);
        let empty = app
            .reopen_closed_browser_panel()
            .expect("skip stale workspace entry");
        assert_eq!(empty["handled"], false);
        assert_eq!(empty["reason"], "history_empty");
    }

