    #[test]
    fn live_evalhandle_replaces_model_value_without_changing_handle() {
        let (mut app, surface_id, _surface_ref, _workspace_id) = app_with_current_surface();
        app.surfaces.get_mut(&surface_id).expect("surface").kind = SurfaceKind::Browser;

        let model_result = app
            .handle(
                "browser.evalhandle",
                &json!({"surface_id": surface_id, "script": "({model: true})"}),
            )
            .expect("allocate model handle");
        let handle = model_result["handle"].as_str().expect("handle").to_string();
        let native_value = json!({"native": true, "items": [1, 2, 3]});

        let replaced = app
            .browser_runtime_replace_eval_handle(&surface_id, &model_result, native_value.clone())
            .expect("replace handle value");

        assert_eq!(replaced["handle"], handle);
        assert_eq!(replaced["handle_id"], model_result["handle_id"]);
        assert_eq!(replaced["object_id"], handle);
        assert_eq!(replaced["type"], "object");
        assert_eq!(replaced["value"], native_value);
        assert_eq!(
            app.surfaces[&surface_id].browser.eval_handles[&handle],
            native_value
        );
    }

    #[test]
    fn live_snapshot_replaces_ephemeral_refs_and_preserves_model_metadata() {
        let (mut app, surface_id, _surface_ref, _workspace_id) = app_with_current_surface();
        app.surfaces.get_mut(&surface_id).expect("surface").kind = SurfaceKind::Browser;
        let model_result = app
            .handle("browser.snapshot", &json!({"surface_id": surface_id}))
            .expect("model snapshot");
        let model_viewport = model_result["viewport"].clone();

        let replaced = app
            .browser_runtime_replace_snapshot(
                &surface_id,
                &model_result,
                &json!({
                    "snapshot": "document \"Live\"\n- body [ref=e1]\n  - button \"Dynamic\" [ref=e7]",
                    "refs": {"e1": "body", "e7": "#dynamic", "bad": "#ignored"}
                }),
            )
            .expect("replace live snapshot");

        assert_eq!(
            replaced["snapshot"],
            "document \"Live\"\n- body [ref=e1]\n  - button \"Dynamic\" [ref=e7]"
        );
        assert_eq!(replaced["refs"], json!({"e1": "body", "e7": "#dynamic"}));
        assert_eq!(replaced["viewport"], model_viewport);
        assert_eq!(
            app.browser_runtime_target(
                "browser.get.text",
                &json!({"surface_id": surface_id, "selector": "e7"})
            )
            .expect("resolve live ref")
            .1
            .as_deref(),
            Some("#dynamic")
        );
        assert_eq!(app.surfaces[&surface_id].browser.next_element_ref, 8);
    }

    #[test]
    fn native_recording_frames_replace_model_frames_and_reject_stale_generations() {
        let (mut app, surface_id, _surface_ref, _workspace_id) = app_with_current_surface();
        app.surfaces.get_mut(&surface_id).expect("surface").kind = SurfaceKind::Browser;

        app.handle(
            "browser.screencast.start",
            &json!({"surface_id": surface_id}),
        )
        .expect("start screencast");
        app.handle("browser.video.start", &json!({"surface_id": surface_id}))
            .expect("start video");
        let target = app
            .browser_runtime_recording_targets()
            .into_iter()
            .find(|target| target.surface_id == surface_id)
            .expect("recording target");
        let native_png = super::solid_rgb_png(4, 3, (12, 34, 56));

        assert!(app
            .browser_runtime_record_frame(&target, native_png.clone(), 4, 3)
            .expect("record native frame"));
        let browser = &app.surfaces[&surface_id].browser;
        assert_eq!(browser.screencast_frames.len(), 1);
        assert_eq!(browser.video_frames.len(), 1);
        assert!(browser.screencast_frames[0].native);
        assert!(browser.video_frames[0].native);
        assert_eq!(browser.screencast_frames[0].width, 4);
        assert_eq!(browser.screencast_frames[0].height, 3);

        super::maybe_record_screencast_frame(
            &mut app
                .surfaces
                .get_mut(&surface_id)
                .expect("browser surface")
                .browser,
        );
        assert!(
            !app.surfaces[&surface_id]
                .browser
                .screencast_frames
                .last()
                .expect("model screencast frame")
                .native
        );

        let stopped_screencast = app
            .handle(
                "browser.screencast.stop",
                &json!({"surface_id": surface_id}),
            )
            .expect("stop screencast");
        let stopped_video = app
            .handle("browser.video.stop", &json!({"surface_id": surface_id}))
            .expect("stop video");
        assert_eq!(stopped_screencast["frame_count"], 1);
        assert_eq!(stopped_video["frame_count"], 1);
        assert_eq!(
            stopped_screencast["frames"][0]["png_base64"],
            base64::engine::general_purpose::STANDARD.encode(&native_png)
        );
        assert_eq!(stopped_screencast["frames"][0]["source"], "webkit");
        assert!(!app
            .browser_runtime_record_frame(&target, native_png.clone(), 4, 3)
            .expect("reject stopped generation"));

        app.handle(
            "browser.screencast.start",
            &json!({"surface_id": surface_id}),
        )
        .expect("restart screencast");
        let restarted_target = app.browser_runtime_recording_targets().remove(0);
        assert_ne!(
            target.screencast_generation,
            restarted_target.screencast_generation
        );
        assert!(!app
            .browser_runtime_record_frame(&target, native_png.clone(), 4, 3)
            .expect("reject stale generation"));
        assert!(app
            .browser_runtime_record_frame(&restarted_target, native_png, 4, 3)
            .expect("accept restarted generation"));
    }

