    #[test]
    fn command_palette_exposes_contextual_workspace_tab_and_copy_commands() {
        let (mut app, surface_id, _surface_ref, workspace_id) = app_with_current_surface();
        let pane_id = app.surfaces[&surface_id].pane_id.clone();
        app.workspaces.get_mut(&workspace_id).unwrap().custom_title = true;
        app.workspaces
            .get_mut(&workspace_id)
            .unwrap()
            .custom_description = Some("Context".to_string());
        app.surfaces.get_mut(&surface_id).unwrap().custom_title = true;
        app.surface_create(&json!({
            "workspace_id": workspace_id,
            "pane_id": pane_id,
            "type": "terminal",
            "focus": false
        }))
        .expect("second tab");
        app.workspace_create(&json!({"title": "Peer", "focus": false}))
            .expect("peer workspace");

        let rows = app.command_palette_command_rows("");
        let ids = rows
            .iter()
            .filter_map(|row| row["command_id"].as_str())
            .collect::<HashSet<_>>();
        for expected in [
            "palette.clearWorkspaceName",
            "palette.clearWorkspaceDescription",
            "palette.toggleWorkspacePin",
            "palette.moveWorkspaceDown",
            "palette.closeOtherWorkspaces",
            "palette.closeWorkspacesBelow",
            "palette.markWorkspaceUnread",
            "palette.copyWorkspaceID",
            "palette.copyWorkspaceIDAndRef",
            "palette.copyWorkspaceLink",
            "palette.clearTabName",
            "palette.moveTabToNewWorkspace",
            "palette.toggleTabPin",
            "palette.toggleTabUnread",
            "palette.nextTabInPane",
            "palette.previousTabInPane",
            "palette.copyPaneID",
            "palette.copyPaneLink",
            "palette.copySurfaceID",
            "palette.copySurfaceLink",
            "palette.copyIdentifiers",
        ] {
            assert!(ids.contains(expected), "missing {expected}");
        }
        assert!(!ids.contains("palette.moveWorkspaceUp"));
        assert!(!ids.contains("palette.closeWorkspacesAbove"));

        let copied = app
            .command_palette_execute_command("palette.copyIdentifiers")
            .expect("copy identifiers");
        let text = copied["clipboard_text"].as_str().unwrap();
        assert_eq!(copied["clipboard_action"], "copy");
        assert!(text.contains(&format!("workspace_id={workspace_id}")));
        assert!(text.contains(&format!("pane_id={pane_id}")));
        assert!(text.contains(&format!("surface_id={surface_id}")));
        assert!(text.contains("workspace_ref=workspace:1"));
        assert!(text.contains("pane_ref=pane:1"));
        assert!(text.contains("surface_ref=surface:1"));

        let copied = app
            .command_palette_execute_command("palette.copySurfaceLink")
            .expect("copy surface link");
        assert_eq!(
            copied["clipboard_text"],
            format!("cmux://workspace/{workspace_id}/surface/{surface_id}")
        );
    }

