    #[test]
    fn sidebar_workspace_selection_supports_toggle_range_and_group_shortcut() {
        let (mut app, _surface_id, _surface_ref, first) = app_with_current_surface();
        let second = app
            .workspace_create(&json!({"title": "Second"}))
            .expect("second workspace")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let third = app
            .workspace_create(&json!({"title": "Third"}))
            .expect("third workspace")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let fourth = app
            .workspace_create(&json!({"title": "Fourth"}))
            .expect("fourth workspace")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();

        app.sidebar_select_workspace(&json!({"workspace_id": first}))
            .expect("plain select");
        let toggled = app
            .sidebar_select_workspace(&json!({"workspace_id": third, "toggle": true}))
            .expect("toggle select");
        assert_eq!(toggled["selected_workspace_ids"], json!([first, third]));

        let ranged = app
            .sidebar_select_workspace(&json!({"workspace_id": fourth, "range": true}))
            .expect("range select");
        assert_eq!(ranged["selected_workspace_ids"], json!([third, fourth]));

        let extended = app
            .sidebar_select_workspace(
                &json!({"workspace_id": first, "range": true, "extend": true}),
            )
            .expect("extend range");
        assert_eq!(
            extended["selected_workspace_ids"],
            json!([first, second, third, fourth])
        );
        let rows = app.workspace_rows(None).expect("workspace rows");
        assert!(rows.iter().all(|row| row["multi_selected"] == true));

        let grouped = app
            .handle("debug.shortcut.simulate", &json!({"combo": "ctrl+shift+g"}))
            .expect("group shortcut");
        assert_eq!(grouped["handled"], true);
        assert_eq!(grouped["action"], "groupSelectedWorkspaces");
        assert_eq!(
            grouped["selected_workspace_ids"].as_array().unwrap().len(),
            4
        );
        assert_eq!(app.workspace_groups.len(), 1);
    }

