    #[test]
    fn sidebar_range_selection_excludes_collapsed_group_children() {
        let (mut app, _surface_id, _surface_ref, first) = app_with_current_surface();
        let second = app
            .workspace_create(&json!({"title": "Second"}))
            .expect("second workspace")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let third = app
            .workspace_create(&json!({"title": "Third"}))
            .expect("third workspace")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let fourth = app
            .workspace_create(&json!({"title": "Fourth"}))
            .expect("fourth workspace")["workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        let created = app
            .workspace_group_create(
                &json!({"child_workspace_ids": [second.clone(), third.clone()]}),
            )
            .expect("create group");
        let group_id = created["group"]["group_id"].as_str().unwrap();
        let anchor = created["group"]["anchor_workspace_id"]
            .as_str()
            .unwrap()
            .to_string();
        app.workspace_group_set_collapsed(&json!({"group_id": group_id}), true)
            .expect("collapse group");

        app.sidebar_select_workspace(&json!({"workspace_id": first}))
            .expect("select first");
        let ranged = app
            .sidebar_select_workspace(&json!({"workspace_id": fourth, "range": true}))
            .expect("range over collapsed group");
        assert_eq!(
            ranged["selected_workspace_ids"],
            json!([first, anchor, fourth])
        );
        assert!(!ranged["selected_workspace_ids"]
            .as_array()
            .unwrap()
            .iter()
            .any(|id| id == &second || id == &third));
    }

