    #[test]
    fn react_grab_shortcut_routes_terminal_to_the_sole_workspace_browser() {
        let (mut app, terminal_id, terminal_ref, workspace_id) = app_with_current_surface();
        let opened = app
            .open_embedded_terminal_url(&terminal_ref, "https://example.test/react")
            .expect("open browser")
            .expect("browser split");
        let browser_id = opened["surface_id"]
            .as_str()
            .expect("browser id")
            .to_string();
        app.focus_surface(&terminal_id).expect("refocus terminal");

        let toggled = app
            .execute_shortcut_name("toggle_react_grab")
            .expect("toggle React Grab");
        assert_eq!(toggled["handled"], true);
        assert_eq!(toggled["surface_id"], browser_id);
        assert_eq!(toggled["return_terminal_surface_id"], terminal_id);
        assert_eq!(toggled["browser_shortcut_action"], "toggle_react_grab");
        assert_eq!(toggled["react_grab_active"], true);
        assert_eq!(
            app.workspace_selected_surface(&workspace_id).as_deref(),
            Some(browser_id.as_str())
        );

        let snapshot =
            crate::renderer::snapshot_value(&mut app, &json!({})).expect("renderer snapshot");
        let browser_view = snapshot["surface_views"]
            .as_array()
            .expect("surface views")
            .iter()
            .find(|view| view["surface_id"] == browser_id)
            .expect("browser view");
        assert_eq!(browser_view["browser"]["react_grab_active"], true);

        app.open_embedded_terminal_url(&terminal_ref, "https://example.test/second")
            .expect("open second browser")
            .expect("second browser split");
        app.focus_surface(&terminal_id).expect("refocus terminal");
        let ambiguous = app
            .execute_shortcut_name("toggle_react_grab")
            .expect("ambiguous React Grab route");
        assert_eq!(ambiguous["handled"], false);
        assert_eq!(ambiguous["reason"], "react_grab_route_unavailable");
        assert_eq!(
            app.workspace_selected_surface(&workspace_id).as_deref(),
            Some(terminal_id.as_str())
        );
    }

