    #[test]
    fn embedded_terminal_runtime_ready_counts_without_core_pty() {
        let (mut app, surface_id, surface_ref, workspace_id) = app_with_current_surface();
        if let Some(surface) = app.surfaces.get_mut(&surface_id) {
            surface.terminal = None;
        }

        assert!(!super::surface_runtime_ready(&app.surfaces[&surface_id]));
        assert!(app
            .set_embedded_terminal_runtime_ready(&surface_ref, true)
            .expect("ready"));
        assert!(super::surface_runtime_ready(&app.surfaces[&surface_id]));

        let health = app
            .handle(
                "surface.health",
                &serde_json::json!({"workspace_id": workspace_id}),
            )
            .expect("health");
        let row = health["surfaces"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["surface_id"] == surface_id)
            .expect("surface row");
        assert_eq!(row["runtime_surface_ready"], true);

        assert!(app
            .set_embedded_terminal_runtime_ready(&surface_ref, false)
            .expect("not ready"));
        assert!(!super::surface_runtime_ready(&app.surfaces[&surface_id]));
    }

    #[test]
    fn embedded_terminal_runtime_ready_clears_loading_without_text_snapshot() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");
        let workspace_id = app.current_workspace_id().expect("current workspace");

        assert!(app.surfaces[&surface_id].terminal.is_none());
        assert!(super::terminal_surface_loading(&app.surfaces[&surface_id]));

        assert!(app
            .set_embedded_terminal_runtime_ready(&surface_id, true)
            .expect("ready"));
        assert!(!super::terminal_surface_has_content(
            &app.surfaces[&surface_id]
        ));
        assert!(super::surface_runtime_ready(&app.surfaces[&surface_id]));
        assert!(!super::terminal_surface_loading(&app.surfaces[&surface_id]));

        let health = app
            .handle(
                "surface.health",
                &serde_json::json!({"workspace_id": workspace_id}),
            )
            .expect("health");
        let surface = health["surfaces"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["surface_id"] == surface_id)
            .expect("surface row");
        assert_eq!(surface["runtime_surface_ready"], true);
        assert_eq!(surface["terminal_loading"], false);
        assert_eq!(surface["loading"], false);
        assert_eq!(surface["loading_message"], "");

        let terminals = app
            .handle("debug.terminals", &serde_json::json!({}))
            .expect("terminals");
        let terminal = terminals["terminals"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["surface_id"] == surface_id)
            .expect("terminal row");
        assert_eq!(terminal["runtime_surface_ready"], true);
        assert_eq!(terminal["terminal_loading"], false);
        assert_eq!(terminal["loading"], false);
        assert!(app.surfaces[&surface_id].terminal.is_none());
    }

    #[test]
    fn embedded_terminal_runtime_cleanup_clears_live_state() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");
        let surface_ref = app.surface_ref(&surface_id);
        let foreground_pid = std::process::id();
        let terminal_size = EmbeddedTerminalSize {
            columns: 100,
            rows: 32,
            width_px: 1000,
            height_px: 640,
            cell_width_px: 10,
            cell_height_px: 20,
        };

        assert!(app
            .set_embedded_terminal_runtime_ready(&surface_ref, true)
            .expect("ready"));
        assert!(app
            .update_embedded_terminal_text_snapshot(&surface_ref, "last ghostty frame\n")
            .expect("text snapshot"));
        assert!(app
            .update_embedded_terminal_runtime_metadata(
                &surface_ref,
                Some("/dev/pts/42"),
                Some(foreground_pid),
                false,
                Some(terminal_size),
            )
            .expect("runtime metadata"));
        assert!(app
            .update_embedded_terminal_mouse_captured(&surface_ref, true)
            .expect("mouse captured"));
        assert!(app
            .update_embedded_terminal_cursor_shape(&surface_ref, "pointer")
            .expect("cursor shape"));
        assert!(app
            .update_embedded_terminal_cursor_visibility(&surface_ref, false)
            .expect("cursor visibility"));
        assert!(app
            .update_embedded_terminal_link_hover(&surface_ref, Some("https://example.test/docs"))
            .expect("link hover"));
        assert!(app
            .update_embedded_terminal_selection(&surface_ref, true, Some("selected text"))
            .expect("selection"));
        assert!(app
            .update_embedded_terminal_key_sequence(&surface_ref, true, "ctrl+a")
            .expect("key sequence"));
        assert!(app
            .update_embedded_terminal_key_table(&surface_ref, "activate", Some("leader"))
            .expect("key table"));
        assert!(app
            .update_embedded_terminal_progress_report(&surface_ref, "set", Some(42))
            .expect("progress"));
        assert!(app
            .start_embedded_terminal_search(&surface_ref, "needle")
            .expect("search"));
        assert!(app
            .update_embedded_terminal_scrollbar(&surface_ref, 500, 120, 40)
            .expect("scrollbar"));
        app.surfaces
            .get_mut(&surface_id)
            .expect("surface")
            .shell_activity_state = "exited".to_string();

        let present_count = app.surfaces[&surface_id].present_count;
        assert!(app
            .clear_embedded_terminal_runtime_state(&surface_ref)
            .expect("cleared"));
        let surface = &app.surfaces[&surface_id];
        assert_eq!(surface.present_count, present_count + 1);
        assert!(!surface.embedded_terminal_ready);
        assert_eq!(surface.tty, None);
        assert_eq!(surface.embedded_terminal_foreground_pid, None);
        assert_eq!(surface.embedded_terminal_size, Some(terminal_size));
        assert!(!surface.embedded_terminal_mouse_captured);
        assert_eq!(surface.embedded_terminal_cursor_shape, None);
        assert!(surface.embedded_terminal_cursor_visible);
        assert!(!surface.embedded_terminal_mouse_over_link);
        assert_eq!(surface.embedded_terminal_mouse_over_link_url, None);
        assert!(!surface.embedded_terminal_has_selection);
        assert_eq!(surface.embedded_terminal_selection_text, None);
        assert_eq!(surface.embedded_terminal_key_sequence, None);
        assert!(surface.embedded_terminal_key_tables.is_empty());
        assert_eq!(surface.embedded_terminal_progress, None);
        assert_eq!(surface.embedded_terminal_search, None);
        assert_eq!(surface.embedded_terminal_scrollbar, None);
        assert_eq!(surface.shell_activity_state, "unknown");
        assert!(surface
            .buffer
            .lock()
            .expect("buffer")
            .contains("last ghostty frame"));
        assert!(!app
            .clear_embedded_terminal_runtime_state(&surface_ref)
            .expect("already clear"));
    }

