    #[test]
    fn session_terminal_env_omits_managed_terminal_context() {
        let env = HashMap::from([
            ("CMUX_WORKSPACE_ID".to_string(), "workspace".to_string()),
            ("CMUX_PANE_ID".to_string(), "pane".to_string()),
            ("CMUX_SURFACE_ID".to_string(), "surface".to_string()),
            ("CMUX_TAB_ID".to_string(), "tab".to_string()),
            ("CMUX_PANEL_ID".to_string(), "panel".to_string()),
            ("USER_VAR".to_string(), "kept".to_string()),
        ]);

        let filtered = session_terminal_env(&env);

        assert_eq!(filtered.get("USER_VAR").map(String::as_str), Some("kept"));
        for key in [
            "CMUX_WORKSPACE_ID",
            "CMUX_PANE_ID",
            "CMUX_SURFACE_ID",
            "CMUX_TAB_ID",
            "CMUX_PANEL_ID",
        ] {
            assert!(
                !filtered.contains_key(key),
                "managed key {key} should not be persisted in session env"
            );
        }
    }

