    #[test]
    fn new_right_tab_actions_stay_in_pane_focus_on_request_and_restore_order() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let workspace_id = app.current_workspace_id().expect("workspace");
        let source_surface_id = app.current_surface_id().expect("surface");
        let pane_id = app.surfaces[&source_surface_id].pane_id.clone();
        app.surfaces
            .get_mut(&source_surface_id)
            .expect("source surface")
            .terminal_cwd = Some("/tmp/context-tab-cwd".to_string());

        let terminal = app
            .handle(
                "surface.action",
                &json!({
                    "surface_id": app.surface_ref(&source_surface_id),
                    "action": "new-terminal-right"
                }),
            )
            .expect("new terminal tab");
        let terminal_id = terminal["created_surface_id"]
            .as_str()
            .expect("created terminal")
            .to_string();
        assert_eq!(app.workspaces[&workspace_id].panes, vec![pane_id.clone()]);
        assert_eq!(
            app.panes[&pane_id].surfaces,
            vec![source_surface_id.clone(), terminal_id.clone()]
        );
        assert_eq!(
            app.panes[&pane_id].selected_surface.as_deref(),
            Some(source_surface_id.as_str())
        );
        assert_eq!(
            app.surfaces[&terminal_id].terminal_cwd.as_deref(),
            Some("/tmp/context-tab-cwd")
        );

        let browser = app
            .handle(
                "surface.action",
                &json!({
                    "surface_id": source_surface_id.clone(),
                    "action": "new-browser-right",
                    "focus": true
                }),
            )
            .expect("new browser tab");
        let browser_id = browser["created_surface_id"]
            .as_str()
            .expect("created browser")
            .to_string();
        assert_eq!(app.workspaces[&workspace_id].panes, vec![pane_id.clone()]);
        assert_eq!(
            app.panes[&pane_id].surfaces,
            vec![source_surface_id, browser_id.clone(), terminal_id]
        );
        assert_eq!(
            app.panes[&pane_id].selected_surface.as_deref(),
            Some(browser_id.as_str())
        );
        assert_eq!(app.current_surface_id().unwrap(), browser_id);
        assert_eq!(
            app.surfaces[&browser_id].url.as_deref(),
            Some("about:blank")
        );

        let snapshot = app.session_snapshot(false);
        let mut restored = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("restored app");
        restored
            .restore_session_snapshot(snapshot)
            .expect("restore snapshot");
        let restored_surface_id = restored.current_surface_id().expect("restored focus");
        let restored_pane_id = restored.surfaces[&restored_surface_id].pane_id.clone();
        let restored_kinds = restored.panes[&restored_pane_id]
            .surfaces
            .iter()
            .map(|surface_id| restored.surfaces[surface_id].kind)
            .collect::<Vec<_>>();
        assert_eq!(
            restored_kinds,
            vec![
                SurfaceKind::Terminal,
                SurfaceKind::Browser,
                SurfaceKind::Terminal
            ]
        );
        assert_eq!(
            restored.surfaces[&restored_surface_id].kind,
            SurfaceKind::Browser
        );
    }

    #[test]
    fn renderer_owned_scrollback_persistence_waits_for_idle_debounce() {
        assert!(!super::terminal_scrollback_persist_due(None, 10_000));
        assert!(!super::terminal_scrollback_persist_due(Some(1_000), 10_999));
        assert!(super::terminal_scrollback_persist_due(Some(1_000), 11_000));
        assert!(!super::terminal_scrollback_persist_due(
            Some(12_000),
            11_000
        ));
    }

    #[test]
    fn renderer_owned_session_restore_replays_scrollback_once() {
        assert_eq!(
            super::terminal_replay_output("one\ntwo\r\nthree"),
            "one\r\ntwo\r\nthree\r\n"
        );
        assert_eq!(super::terminal_replay_output("prompt\r"), "prompt\r\n");
        assert_eq!(super::terminal_replay_output("prompt\n"), "prompt\r\n");
        assert_eq!(super::terminal_replay_output(""), "");
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("surface");
        app.update_embedded_terminal_text_snapshot(&surface_id, "saved command\nsaved output\n")
            .expect("terminal snapshot");
        app.update_embedded_terminal_scrollback_snapshot(
            &surface_id,
            "older history\nsaved command\nsaved output\n",
        )
        .expect("scrollback snapshot");
        let snapshot = app.session_snapshot(true);

        let mut restored = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("restored app");
        restored
            .restore_session_snapshot(snapshot)
            .expect("restore snapshot");
        let restored_surface_id = restored.current_surface_id().expect("restored surface");
        assert_eq!(
            restored.surfaces[&restored_surface_id]
                .terminal_restore_output
                .as_deref(),
            Some("older history\r\nsaved command\r\nsaved output\r\n")
        );
        let renderer_snapshot =
            crate::renderer::snapshot_value(&mut restored, &json!({"backend": "ghostty"}))
                .expect("renderer snapshot");
        assert_eq!(
            renderer_snapshot["surface_views"][0]["terminal_restore_output"],
            "older history\r\nsaved command\r\nsaved output\r\n"
        );

        assert!(restored
            .set_embedded_terminal_runtime_ready(&restored_surface_id, true)
            .expect("runtime ready"));
        assert!(restored.surfaces[&restored_surface_id]
            .terminal_restore_output
            .is_none());
    }

