    #[test]
    fn session_restore_drops_unsubmitted_terminal_input() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("surface");
        app.record_embedded_terminal_input(&surface_id, Some(b"submitted"));
        app.record_embedded_terminal_input(&surface_id, Some(b"\r"));
        app.record_embedded_terminal_input(&surface_id, Some("draft \u{e9}".as_bytes()));

        let mut snapshot = app.session_snapshot(true);
        let saved_surface = &mut snapshot.windows[0].workspaces[0].panes[0].surfaces[0];
        assert_eq!(saved_surface.input_history, "submitted\n");

        saved_surface.input_history = "submitted\nlegacy draft".to_string();
        let mut restored = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("restored app");
        restored
            .restore_session_snapshot(snapshot)
            .expect("restore snapshot");
        let restored_surface_id = restored.current_surface_id().expect("restored surface");
        assert_eq!(
            restored.surfaces[&restored_surface_id].input_history,
            "submitted\n"
        );
        assert_eq!(
            super::pending_visible_input_line(
                &restored.surfaces[&restored_surface_id].input_history
            ),
            None
        );
    }

    #[test]
    fn renderer_owned_send_text_and_key_queue_for_embedded_surface() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");
        let surface_ref = app.surface_ref(&surface_id);
        assert_eq!(
            app.current_terminal_input_route(),
            Some((surface_id.clone(), true))
        );

        app.handle(
            "surface.send_text",
            &json!({"surface_id": surface_ref, "text": "printf queued"}),
        )
        .expect("send text");
        app.handle(
            "surface.send_key",
            &json!({"surface_id": surface_id, "key": "enter"}),
        )
        .expect("send key");

        assert!(app.surfaces[&surface_id].terminal.is_none());
        app.surfaces
            .get_mut(&surface_id)
            .expect("surface")
            .embedded_terminal_ready = true;
        assert_eq!(
            app.current_terminal_input_route(),
            Some((surface_id.clone(), true))
        );
        let queued = app
            .drain_embedded_terminal_input(&surface_id)
            .expect("queued input");
        assert_eq!(
            queued,
            vec![
                EmbeddedTerminalInput::Text("printf queued".to_string()),
                EmbeddedTerminalInput::Key("enter".to_string())
            ]
        );
        assert!(app
            .drain_embedded_terminal_input(&surface_id)
            .expect("drained")
            .is_empty());
        assert_eq!(
            app.current_terminal_input_route(),
            Some((surface_id.clone(), false))
        );
        app.record_embedded_terminal_input(&surface_id, Some(b"typed"));
        assert_eq!(
            super::pending_visible_input_line(&app.surfaces[&surface_id].input_history).as_deref(),
            Some("typed")
        );
        app.record_embedded_terminal_input(&surface_id, Some(b"\r"));
        assert_eq!(
            super::pending_visible_input_line(&app.surfaces[&surface_id].input_history),
            None
        );
    }

    #[test]
    fn terminal_text_box_formats_attachments_and_submits_through_ghostty_queue() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");
        let directory = tempfile::tempdir().expect("tempdir");
        let path = directory.path().join("prompt notes.txt");
        std::fs::write(&path, "notes").expect("attachment");

        app.handle(
            "terminal.textbox.set_text",
            &json!({"surface_id": surface_id, "text": "review  please"}),
        )
        .expect("set text");
        let attached = app
            .handle(
                "terminal.textbox.attach",
                &json!({"surface_id": surface_id, "paths": [path], "offset": 7}),
            )
            .expect("attach");
        assert_eq!(attached["text_box"]["active"], true);
        assert_eq!(attached["text_box"]["attachments"][0]["offset"], 7);
        let rebased = app
            .handle(
                "terminal.textbox.set_text",
                &json!({"surface_id": surface_id, "text": "urgent review  please"}),
            )
            .expect("rebase attachment");
        assert_eq!(rebased["text_box"]["attachments"][0]["offset"], 14);

        let submitted = app
            .handle(
                "terminal.textbox.submit",
                &json!({"surface_id": surface_id}),
            )
            .expect("submit");
        assert!(submitted["payload"]
            .as_str()
            .expect("payload")
            .contains("prompt\\ notes.txt"));
        assert_eq!(submitted["text_box"]["text"], "");
        assert_eq!(submitted["text_box"]["attachments"], json!([]));
        assert_eq!(
            app.drain_embedded_terminal_input(&surface_id)
                .expect("queued input"),
            vec![
                EmbeddedTerminalInput::Text(submitted["payload"].as_str().unwrap().to_string()),
                EmbeddedTerminalInput::Key("enter".to_string())
            ]
        );
    }

    #[test]
    fn terminal_text_box_focus_escape_shortcuts_and_session_draft_round_trip() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");
        let focused = app
            .execute_shortcut_name("focus_text_box_input")
            .expect("focus shortcut");
        assert_eq!(focused["text_box"]["focus"], "textBox");
        let repeated_focus = app
            .handle(
                "terminal.textbox.set_focus",
                &json!({"surface_id": surface_id, "focus": "textBox"}),
            )
            .expect("repeat focus callback");
        assert_eq!(
            repeated_focus["text_box"]["focus_generation"],
            focused["text_box"]["focus_generation"]
        );
        let terminal = app
            .execute_shortcut_name("focus_text_box_input")
            .expect("terminal focus shortcut");
        assert_eq!(terminal["text_box"]["focus"], "terminal");

        app.handle(
            "terminal.textbox.set_text",
            &json!({"surface_id": surface_id, "text": "draft prompt"}),
        )
        .expect("draft");
        let escaped = app
            .handle(
                "terminal.textbox.escape",
                &json!({"surface_id": surface_id}),
            )
            .expect("first escape");
        assert_eq!(escaped["text_box"]["active"], true);
        assert_eq!(escaped["text_box"]["hide_escape_armed"], true);
        let hidden = app
            .handle(
                "terminal.textbox.escape",
                &json!({"surface_id": surface_id}),
            )
            .expect("second escape");
        assert_eq!(hidden["text_box"]["active"], false);

        let snapshot = app.session_snapshot(false);
        let mut restored = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("restored app");
        restored
            .restore_session_snapshot(snapshot)
            .expect("restore snapshot");
        let restored_surface = restored.current_surface_id().expect("restored surface");
        let state = restored
            .handle(
                "terminal.textbox.state",
                &json!({"surface_id": restored_surface}),
            )
            .expect("restored text box");
        assert_eq!(state["text_box"]["text"], "draft prompt");
        assert_eq!(state["text_box"]["active"], false);
    }

    #[test]
    fn renderer_owned_terminal_shortcuts_queue_named_keys_for_ghostty() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");

        let ctrl_f = app
            .execute_shortcut_name("send_ctrl_f_to_terminal")
            .expect("send ctrl-f shortcut");
        assert_eq!(ctrl_f["handled"], true);
        assert_eq!(ctrl_f["surface_id"], surface_id);
        assert_eq!(ctrl_f["key"], "ctrl-f");
        let clear = app
            .execute_shortcut_name("clear_screen_keep_scrollback")
            .expect("clear screen shortcut");
        assert_eq!(clear["handled"], true);
        assert_eq!(clear["key"], "ctrl-l");
        assert_eq!(
            app.drain_embedded_terminal_input(&surface_id)
                .expect("queued shortcut input"),
            vec![
                EmbeddedTerminalInput::Key("ctrl-f".to_string()),
                EmbeddedTerminalInput::Key("ctrl-l".to_string())
            ]
        );

        app.surfaces.get_mut(&surface_id).expect("surface").kind = SurfaceKind::Browser;
        let ignored = app
            .execute_shortcut_name("clear_screen_keep_scrollback")
            .expect("non-terminal shortcut");
        assert_eq!(ignored["handled"], false);
        assert!(app
            .drain_embedded_terminal_input(&surface_id)
            .expect("no queued browser input")
            .is_empty());
    }

    #[test]
    fn renderer_owned_find_shortcuts_queue_ghostty_actions_and_track_search_state() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");

        let find = app.execute_shortcut_name("find").expect("find shortcut");
        assert_eq!(find["handled"], true);
        assert_eq!(find["binding_action"], "search:");
        assert_eq!(find["terminal_search"]["active"], true);
        let next = app
            .execute_shortcut_name("find_next")
            .expect("find next shortcut");
        assert_eq!(next["binding_action"], "navigate_search:next");
        let previous = app
            .execute_shortcut_name("find_previous")
            .expect("find previous shortcut");
        assert_eq!(previous["binding_action"], "navigate_search:previous");
        let selection = app
            .execute_shortcut_name("use_selection_for_find")
            .expect("selection find shortcut");
        assert_eq!(selection["binding_action"], "search_selection");
        let hidden = app
            .execute_shortcut_name("hide_find")
            .expect("hide find shortcut");
        assert_eq!(hidden["binding_action"], "end_search");
        assert_eq!(hidden["terminal_search"], json!(null));
        assert!(app.surfaces[&surface_id].embedded_terminal_search.is_none());
        assert_eq!(
            app.drain_embedded_terminal_input(&surface_id)
                .expect("queued find actions"),
            vec![
                EmbeddedTerminalInput::BindingAction("search:".to_string()),
                EmbeddedTerminalInput::BindingAction("navigate_search:next".to_string()),
                EmbeddedTerminalInput::BindingAction("navigate_search:previous".to_string()),
                EmbeddedTerminalInput::BindingAction("search_selection".to_string()),
                EmbeddedTerminalInput::BindingAction("end_search".to_string())
            ]
        );

        app.surfaces.get_mut(&surface_id).expect("surface").kind = SurfaceKind::Browser;
        let browser_find = app.execute_shortcut_name("find").expect("browser find");
        assert_eq!(browser_find["handled"], true);
        assert_eq!(browser_find["browser_shortcut_action"], "find");
        assert!(app
            .drain_embedded_terminal_input(&surface_id)
            .expect("no browser binding actions")
            .is_empty());

        let directory = app
            .execute_shortcut_name("find_in_directory")
            .expect("directory find shortcut");
        assert_eq!(directory["mode"], "find");
        assert_eq!(directory["visible"], true);
    }

