    #[test]
    fn embedded_terminal_ghostty_vt_format_uses_live_size_without_core_pty() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let surface_id = app.current_surface_id().expect("current surface");
        let terminal_size = EmbeddedTerminalSize {
            columns: 113,
            rows: 29,
            width_px: 1130,
            height_px: 580,
            cell_width_px: 10,
            cell_height_px: 20,
        };

        assert!(app.surfaces[&surface_id].terminal.is_none());
        app.update_embedded_terminal_runtime_metadata(
            &surface_id,
            None,
            None,
            false,
            Some(terminal_size),
        )
        .expect("runtime metadata");
        app.update_embedded_terminal_text_snapshot(
            &surface_id,
            "old ghostty value\r\u{1b}[2Klive ghostty frame\n",
        )
        .expect("snapshot");

        let size = app
            .requested_terminal_size_for_surface(&json!({"surface_id": surface_id}), &surface_id);
        assert_eq!(size.cols, terminal_size.columns);
        assert_eq!(size.rows, terminal_size.rows);
        assert_eq!(size.pixel_width, 1130);
        assert_eq!(size.pixel_height, 580);

        let overridden_size = app.requested_terminal_size_for_surface(
            &json!({"surface_id": surface_id, "cols": 80}),
            &surface_id,
        );
        assert_eq!(overridden_size.cols, 80);
        assert_eq!(overridden_size.rows, terminal_size.rows);

        match app.handle(
            "renderer.ghostty_vt.format",
            &json!({"surface_id": surface_id}),
        ) {
            Ok(formatted) => {
                assert_eq!(formatted["cols"], terminal_size.columns);
                assert_eq!(formatted["rows"], terminal_size.rows);
                assert!(
                    formatted["text"]
                        .as_str()
                        .unwrap_or_default()
                        .contains("live ghostty frame"),
                    "formatted output was {formatted}"
                );
            }
            Err(err)
                if err.code == "not_supported"
                    && err.message.contains("libghostty-vt was not found") => {}
            Err(err) => panic!("unexpected Ghostty VT error: {err:?}"),
        }
        assert!(app.surfaces[&surface_id].terminal.is_none());
    }

    #[test]
    fn embedded_terminal_mobile_scroll_prefetch_uses_snapshot_without_core_pty() {
        let mut app = AppState::with_paths_and_terminal_startup(
            None,
            None,
            TerminalStartupMode::RendererOwned,
        )
        .expect("app state");
        let workspace_id = app.current_workspace_id().expect("current workspace");
        let surface_id = app.current_surface_id().expect("current surface");
        let text = (1..=20)
            .map(|index| format!("ghostty scroll {index:02}"))
            .collect::<Vec<_>>()
            .join("\n");

        assert!(app.surfaces[&surface_id].terminal.is_none());
        app.update_embedded_terminal_text_snapshot(&surface_id, &text)
            .expect("snapshot");

        let scroll = app
            .handle(
                "terminal.scroll",
                &json!({
                    "workspace_id": workspace_id,
                    "terminal_id": surface_id,
                    "delta_lines": -3,
                    "max_scrollback_rows": 3
                }),
            )
            .expect("scroll");
        assert_eq!(scroll["surface_id"], surface_id);
        assert_eq!(scroll["delta_lines"], -3.0);
        assert_eq!(scroll["render_grid"]["format"], "cmux.render-grid.v1");
        assert!(
            scroll["render_grid"]["scrollback_rows"]
                .as_u64()
                .unwrap_or_default()
                <= 3,
            "scroll was {scroll}"
        );
        assert!(
            scroll["render_grid"]["row_spans"]
                .as_array()
                .unwrap()
                .iter()
                .chain(
                    scroll["render_grid"]["scrollback_spans"]
                        .as_array()
                        .unwrap()
                )
                .any(|span| span["text"]
                    .as_str()
                    .unwrap_or_default()
                    .contains("ghostty scroll")),
            "scroll was {scroll}"
        );
        assert!(app.surfaces[&surface_id].terminal.is_none());
    }

